window.EX_CORR={"bkA1-0":["Meus pais são professores."],"bkA1-1":["A: De onde você é?","B: Eu sou do Brasil.","A: Sua irmã também é do Brasil?","B: Não, ela não é. Ela é de Portugal."],"bkA1-2":["Tom é meu amigo, e nós estamos na mesma turma."],"bkA1-3":["Carla e Pedro estão na praia."],"bkA1-4":["Ela não é médica."],"bkA1-5":["Seu irmão é estudante?"],"bkA1-6":["Oi! Meu nome é Lucas. Tenho 25 anos e sou de Salvador. Minha irmã Julia tem 20. Ela é estudante. Estamos muito felizes na nossa casa nova."],"bkA1-7":["Você está cansado? / Sim, estou.","A Maria está em casa? / Sim, está.","Eles são do Chile? / Não, não são.","Está frio hoje? / Não, não está."],"bkA1-9":["Olá! Este é meu amigo Kenji. Ele é do Japão, mas agora está no Brasil. Ele é cozinheiro num restaurante japonês em São Paulo. A esposa dele é brasileira. O nome dela é Clara, e ela é dentista. Eles são pessoas muito simpáticas."],"bkA1-10":["Este é meu irmão. Eu jogo futebol com ele aos domingos."],"bkA1-11":["Eu adoro pizza, mas minha irmã não gosta."],"bkA1-12":["Ana e eu somos amigas. Nós vamos à escola juntas. Nossa professora gosta muito de nós."],"bkA1-13":["Você pode me ajudar com a minha bolsa?"],"bkA1-14":["Eu os vejo todos os dias."],"bkA1-15":["Ela me liga toda noite."],"bkA1-16":["eu (sujeito) / me","ele (sujeito) / o, lhe","ela (sujeito) / a, lhe","nós (sujeito) / nos","eles (sujeito) / os, lhes"],"bkA1-18":["A: Quem é aquele homem?","B: Ele é meu tio, Carlos.","A: Você o vê com frequência?","B: Sim, eu o visito todo domingo."],"bkA1-20":["Lucas tem um cachorro. O cachorro dele é muito grande."],"bkA1-21":["Esta é a minha família. Minha mãe é enfermeira, e o nome dela é Rosa. Meus pais adoram o jardim deles."],"bkA1-22":["Nós adoramos a nossa casa nova, e as crianças adoram os quartos delas."],"bkA1-23":["Nós visitamos nossos avós todo domingo."],"bkA1-24":["Este livro é meu."],"bkA1-25":["A casa deles fica perto da praia."],"bkA1-26":["eu / meu","você / seu","ele / dele","ela / dela","nós / nosso"],"bkA1-27":["Olá! Eu sou a Beatriz e moro em Curitiba. O nome do meu marido é Rafael. Nosso apartamento é pequeno, mas agradável. Nosso filho, Theo, tem cinco anos. O brinquedo favorito dele é um carro vermelho. Os pais do Rafael moram em São Paulo, e a casa deles é muito grande."],"bkA1-29":["A: De quem é esta jaqueta?","B: Acho que é do Mark.","A: Não, a jaqueta dele é preta. Esta aqui é azul.","B: Ah, então é minha! Obrigado."],"bkA1-30":["Aqueles sapatos ali são caros."],"bkA1-31":["Esta maçã aqui é vermelha, mas aquelas maçãs lá longe são verdes."],"bkA1-32":["A: Esta caneta é sua? Ela está aqui, na minha mesa.","B: Não, a minha caneta é aquela ali.","A: Estas chaves aqui, na minha mão, são suas?","B: Sim, obrigado!"],"bkA1-33":["Olhe estes pássaros na árvore!"],"bkA1-34":["Estes são meus amigos."],"bkA1-35":["Aqueles carros lá longe são muito velhos."],"bkA1-37":["Paula está numa loja com o amigo Leo. Ela tem um vestido verde nas mãos e diz: \"Eu amei este vestido!\" Leo aponta para uns sapatos mais longe e diz: \"Olha aqueles sapatos!\" O vestido é barato, mas os sapatos são caros."],"bkA1-38":["Este é / meu carro, aqui.","Estes são / meus filhos, aqui comigo.","Aquela é / minha casa, lá longe.","Aquelas são / minhas irmãs, lá longe."],"bkA1-40":["Qual está correta? → uma laranja"],"bkA1-41":["Eu tenho um irmão e um tio em Manaus."],"bkA1-42":["Marcos é ator. Ele tem uma casa grande e um carro velho."],"bkA1-43":["A USP é uma universidade em São Paulo."],"bkA1-44":["Ele é engenheiro."],"bkA1-45":["Eu quero um ovo e uma banana."],"bkA1-48":["A: Oi! Posso ajudar?","B: Sim, eu quero um café, por favor.","A: Mais alguma coisa?","B: Sim, um suco de laranja também. Quanto custa?","A: São dez reais."],"bkA1-49":["Minha prima é artista."],"bkA1-50":["Quanto é 15 + 5? → vinte"],"bkA1-51":["Janeiro é o primeiro mês do ano. Março é o terceiro mês."],"bkA1-52":["Meu aniversário é no dia vinte de maio, e eu tenho trinta anos."],"bkA1-53":["Meu escritório fica no terceiro andar."],"bkA1-54":["12 / doze","13 / treze","40 / quarenta","90 / noventa","2º / segundo"],"bkA1-56":["Bem-vindo ao City Hotel! Nosso hotel tem cinco andares. O restaurante fica no primeiro andar, e a academia fica no terceiro. O café da manhã é das sete às dez da manhã. Um quarto para duas pessoas custa noventa dólares a noite."],"bkA1-57":["Vinte mais trinta é cinquenta."],"bkA1-59":["Hoje tem uma corrida em Fortaleza com quarenta corredores. Rodrigo termina em terceiro lugar. A amiga dele, Ana, termina em primeiro. Rodrigo tem vinte e oito anos, e Ana tem trinta e um."],"bkA1-60":["Há dois bancos na minha rua."],"bkA1-61":["Bem-vindo à minha cidade! Há um parque grande perto da minha casa. Há muitas árvores no parque. Há uma escola, mas não há hospitais. Tem um supermercado? Sim, tem."],"bkA1-62":["Há um gato no sofá, e há três cachorros no jardim."],"bkA1-63":["Há cinco pessoas na minha família."],"bkA1-64":["Tem uma farmácia perto daqui?"],"bkA1-65":["Há dois quartos no meu apartamento."],"bkA1-66":["A: Com licença, tem um banco perto daqui?","B: Sim, tem. Fica na Rua das Flores.","A: Ótimo. Tem restaurantes nessa rua?","B: Sim, tem dois restaurantes bons.","A: Muito obrigado!"],"bkA1-67":["Minha sala de aula é pequena. Há doze carteiras e uma mesa grande. Há um computador na mesa. Não há janelas, mas há um pôster bonito na parede."],"bkA1-68":["Tem uma TV no seu quarto? / Sim, tem. Fica do lado da minha cama.","Tem ovos? / Não, não tem. Vamos comprar.","Tem um ponto de ônibus aqui? / Sim, tem. Fica na esquina.","Tem alunos na turma? / Sim, tem vinte."],"bkA1-69":["Tem leite na geladeira?"],"bkA1-70":["Meu irmão assiste TV toda noite."],"bkA1-71":["Julia mora em Porto Alegre. Ela trabalha num banco. Ela não gosta de tempo frio."],"bkA1-72":["Seu pai toma café? Não, ele não toma."],"bkA1-73":["Ela não come carne."],"bkA1-74":["Eles não jogam futebol aos sábados."],"bkA1-75":["Ele fala espanhol?"],"bkA1-76":["Nós geralmente jantamos às oito."],"bkA1-77":["Oi, Carol! Como vai? Eu tenho um emprego novo agora. Trabalho numa cafeteria em Belo Horizonte. Começo às 7h e termino às 15h. Depois do trabalho, vou à academia. Meu chefe é legal, e eu gosto dos meus colegas de trabalho. Até breve! Pedro"],"bkA1-79":["Você gosta de pizza? / Sim, gosto. Eu adoro!","A Ana trabalha aqui? / Não, não trabalha.","A que horas você acorda? / Às seis horas.","Onde eles moram? / Em Natal."],"bkA1-80":["Quando é o seu aniversário? É em julho."],"bkA1-81":["Quem / Minha professora.","Onde / Na cozinha.","Quando / Na segunda-feira.","Por que / Porque estou cansado."],"bkA1-82":["A: Qual é o seu nome?","B: Meu nome é Diego.","A: De onde você é?","B: Sou do Uruguai.","A: Quantos anos você tem?","B: Tenho 22."],"bkA1-83":["O que você come no café da manhã, e onde você almoça?"],"bkA1-84":["Qual é a sua cor favorita?"],"bkA1-85":["Onde ela mora?"],"bkA1-86":["A que horas começa o filme?"],"bkA1-87":["A: Oi! Quem é aquela garota?","B: Aquela é a Lara, minha prima.","A: Onde ela mora?","B: Ela mora em Lisboa, em Portugal.","A: Ah! Então por que ela está no Brasil?","B: Porque ela está de férias."],"bkA1-89":["Valentina é guia de turismo em Salvador. Ela trabalha de terça a domingo. Ela começa a trabalhar às nove da manhã. O lugar favorito dela na cidade é o Pelourinho, porque é muito colorido. Ela mora com seus dois gatos."],"bkA1-90":["O dia depois da segunda-feira é a terça-feira."],"bkA1-91":["O primeiro mês do ano é janeiro. O último mês é dezembro. O fim de semana é sábado e domingo."],"bkA1-92":["No Brasil, o Natal é no verão, e é em dezembro."],"bkA1-93":["Setembro vem antes de outubro."],"bkA1-94":["Nós temos aula às terças e quintas."],"bkA1-96":["Oi, Mia! Saudações do Canadá. É janeiro e aqui é inverno. Faz muito frio e tem muita neve. Eu esquio aos sábados. Em julho é verão, então faz calor. Venha me visitar no verão! Com carinho, Grace"],"bkA1-97":["O dia antes de sexta-feira / quinta-feira","O mês depois de maio / junho","A estação depois do inverno / primavera","O dia depois de sábado / domingo"],"bkA1-99":["A: Quando é o seu aniversário?","B: É no dia 12 de outubro. E o seu?","A: O meu é em junho.","B: Ah, aqui no Brasil isso é no inverno!"],"bkA1-100":["Está frio. Feche a janela, por favor."],"bkA1-101":["Não corra no corredor! Fique em silêncio na biblioteca."],"bkA1-102":["Por favor, sentem-se e abram os livros."],"bkA1-103":["Não toque no forno. Ele está quente!"],"bkA1-104":["Não abra a porta."],"bkA1-105":["Vire à esquerda na próxima rua."],"bkA1-106":["Estou com frio. / Vista uma jaqueta.","Estou com fome. / Coma um sanduíche.","Estou cansado. / Vá dormir cedo.","Estou atrasado! / Se apresse!"],"bkA1-107":["Regras da piscina: Tome um banho antes de nadar. Não corra perto da piscina. Não coma na água. Crianças menores de 10 anos: nadem com um adulto. A piscina fecha às 20h."],"bkA1-108":["A: Com licença, onde fica a estação de trem?","B: Siga em frente e vire à direita no banco.","A: É longe?","B: Não, é perto. Ande por cinco minutos.","A: Muito obrigado!"],"bkA1-110":["A reunião é às 15h."],"bkA1-111":["Meu aniversário é no dia 5 de abril. Eu vou à escola de manhã. Almoçamos ao meio-dia."],"bkA1-112":["As chaves estão em cima da mesa, e o gato está dentro da caixa."],"bkA1-113":["Nós não trabalhamos aos domingos."],"bkA1-115":["Ela mora numa cidade pequena em Minas Gerais."],"bkA1-116":["noite / à","sábado / no","a manhã / de"],"bkA1-117":["Oi, Leo! A festa da Nina é no sábado, às 20h. É na minha casa, na Rua das Flores. Por favor, traga uma bebida. A Nina chega às 20h30, então não se atrase! Até lá! Camila"],"bkA1-118":["Eu moro no Brasil."],"bkA1-119":["Tiago é estudante em Belém. Ele tem aulas às segundas e quartas. As aulas dele começam às 19h. Nos fins de semana, ele trabalha num restaurante. No verão, ele viaja com a família."],"bkA1-120":["Estou com fome. Podemos comer agora?"],"bkA1-121":["O museu abre às segundas-feiras?"],"bkA1-122":["Luana tem dezenove anos."],"bkA1-123":["A: Oi, eu sou a Renata, a nova designer.","B: Prazer em conhecê-la! Eu sou o Marcos. Você é de Recife?","A: Não, não sou. Eu sou de Natal."],"bkA1-124":["Meu celular novo é ótimo. A câmera é excelente, e os aplicativos são rápidos. A tela é grande, mas ele não é pesado."],"bkA1-125":["As crianças estão na escola, mas o bebê está em casa comigo."],"bkA1-126":["Você e a Rita são primas? Sim, somos."],"bkA1-127":["Eu concordo com você."],"bkA1-128":["Ela é sua professora?"],"bkA1-129":["O Diego está no trabalho?"],"bkA1-130":["Nós não estamos com fome."],"bkA1-131":["Meus pais não estão em casa hoje."],"bkA1-132":["Você é enfermeiro ou médico?"],"bkA1-133":["O Pedro é seu irmão? / Não, ele é meu primo.","Você é de Manaus? / Sim, sou.","A sopa está quente? / Sim, está. Cuidado!","Estamos atrasados? / Não, não estamos. São só 7h55."],"bkA1-136":["Esta é a Fernanda. Ela é enfermeira em Florianópolis. O marido dela, Igor, é motorista de táxi. Os filhos deles são gêmeos e têm oito anos. A família não é rica, mas eles são muito felizes."],"bkA1-137":["Nome: Samuel Costa. Idade: 34. Cidade: Belo Horizonte. Sou desenvolvedor de software. Não sou casado. Meu esporte favorito é o vôlei. Meus melhores amigos são o Caio e o Léo. Eles são meus colegas de trabalho."],"bkA1-138":["A: Com licença, o senhor é o Sr. Tanaka?","B: Sim, sou. Você é do hotel?","A: Sim, sou o Bruno, seu motorista. Bem-vindo ao Rio!","B: Obrigado. O hotel é longe daqui?","A: Não, não é. São vinte minutos de carro."],"bkA1-139":["Onde estão meus óculos? Eu não consigo enxergar!"],"bkA1-140":["Onde está a Paula? Preciso falar com ela."],"bkA1-141":["Meus avós moram na Bahia. Eles têm uma fazenda grande."],"bkA1-142":["Hoje está muito quente. Vamos à praia!"],"bkA1-143":["Rafael é meu vizinho. Ele é muito simpático. Eu sempre o ajudo com o carro dele, e ele me ajuda com o meu computador."],"bkA1-144":["A: Você conhece a Bia e o Caio?","B: Sim, eu os conheço muito bem. Eles são meus primos.","A: A Bia é a sua prima favorita?","B: Sim! Eu a adoro."],"bkA1-145":["Meu pai e eu fazemos o jantar às sextas, e a mamãe às vezes nos ajuda."],"bkA1-146":["Esta mensagem é para você. Por favor, leia agora."],"bkA1-147":["Julia e eu estamos na mesma turma."],"bkA1-148":["A professora nos dá muito dever de casa."],"bkA1-149":["Nós assistimos a filmes às sextas."],"bkA1-150":["Ligue para ela hoje à noite."],"bkA1-151":["Você pode nos ajudar com as caixas?"],"bkA1-152":["Eles mandam uma mensagem para ele toda manhã."],"bkA1-153":["Marta é médica. / Ela trabalha num hospital.","Onde estão meus sapatos? / Não consigo encontrá-los.","Aqui está o seu café. / Beba agora.","Sinto saudade do Pedro. / Quero vê-lo."],"bkA1-156":["A: Oi, Leo! A Carla está com você?","B: Não, ela está no trabalho. Por quê?","A: Estou com o celular dela. Está aqui na minha bolsa.","B: Ah! Me dá. Eu posso levar para ela."],"bkA1-157":["Oi, Duda! Estou na academia com o Marcos. Ele está com as minhas chaves, então espere por nós na cafeteria. Você pode comprar dois sanduíches para nós? Eu pago depois. Valeu! Gabi"],"bkA1-158":["Meu nome é Ícaro. Tenho uma irmã, a Lia. Ela mora em Belém com o marido, Otto. Eu os visito todo dezembro. Otto é chef e cozinha para nós toda noite. A Lia não cozinha, mas lava a louça."],"bkA1-159":["Onde está meu celular? Não consigo encontrá-lo."],"bkA1-160":["Mariana ama o irmão dela."],"bkA1-161":["Paulo liga para a mãe dele todo dia."],"bkA1-162":["Este guarda-chuva é seu? Não, não é meu."],"bkA1-163":["A: Esta bolsa é sua?","B: Não, não é minha. É da Laura.","A: Tem certeza? É da mesma cor da sua bolsa velha."],"bkA1-164":["Eu sou o Tomás, e este é o meu blog. Minha irmã Sol mora no Canadá com o marido. Meu irmão Nico adora a bicicleta nova dele. Meus pais e eu moramos em Santiago. Nosso apartamento é pequeno, mas agradável."],"bkA1-165":["Esta jaqueta é sua? Não, a minha jaqueta é preta."],"bkA1-166":["O cachorro está comendo a comida dele, e os gatos estão dormindo nas caminhas deles."],"bkA1-167":["Meu carro está na garagem."],"bkA1-168":["O nome do meu irmão é Leo, e a esposa dele é a Kátia."],"bkA1-169":["Este celular é dela."],"bkA1-170":["Aquelas são as nossas bicicletas."],"bkA1-171":["Este café é seu ou meu?"],"bkA1-172":["Qual é o nome da sua irmã?"],"bkA1-173":["Eu tenho um gato. / É o meu gato.","A Ana tem um gato. / É o gato dela.","O Tom tem um gato. / É o gato dele.","Nós temos um gato. / É o nosso gato.","As crianças têm um gato. / É o gato delas."],"bkA1-176":["Oi, eu sou a Yasmin. Esta é uma foto da minha família numa fazenda em Goiás. Meu pai está ao lado do cavalo dele, o Trovão. Minha mãe está com o chapéu favorito dela. Meus irmãos estão com os cachorros deles. A fazenda não é nossa; é do meu tio."],"bkA1-177":["Guarda: Com licença, esta mala é sua?","Lia: Não, a minha é vermelha. Talvez seja daquele homem.","Guarda: Senhor! Esta é a sua mala?","Homem: Sim, é minha! Muito obrigado."],"bkA1-178":["Bem-vindo ao nosso hostel em Paraty! Seu quarto fica no segundo andar. Sua chave abre o quarto e a porta da frente. A cozinha é para todos os hóspedes, mas, por favor, lave a sua louça. Nosso café da manhã é das 7h às 10h."],"bkA1-179":["Nós adoramos os nossos novos vizinhos."],"bkA1-180":["Alô? Aqui é a Marina. Posso falar com o Pedro?"],"bkA1-181":["Olhe aquelas estrelas no céu esta noite!"],"bkA1-182":["Quanto custam estes tomates aqui na minha cesta?"],"bkA1-183":["A: Quanto custa esta camiseta aqui, na minha mão?","B: Custa quarenta reais.","A: E aquelas calças jeans lá?","B: Custam noventa reais."],"bkA1-184":["Mãe, este é o meu amigo Theo, aqui comigo. E aqueles são os pais dele, ali perto do carro."],"bkA1-185":["Esta pizza está deliciosa, mas aquelas batatas fritas estão frias."],"bkA1-186":["Estes são os seus óculos? Não, aqueles são os meus óculos, na mesa lá."],"bkA1-187":["Este é o meu notebook novo."],"bkA1-188":["Aquela criança ali é o meu filho."],"bkA1-189":["Aquelas bolsas são pesadas."],"bkA1-190":["Estes são os sapatos da Ana?"],"bkA1-191":["Aquele ali é o seu irmão?"],"bkA1-192":["Eu adoro estas fotos antigas dos meus avós."],"bkA1-193":["O que é isto? / É um presente para você.","Quem são aquelas pessoas? / São meus vizinhos.","Estes lugares estão livres? / Sim, você pode sentar aqui.","Aquele é o seu cachorro? / Não, é da minha irmã."],"bkA1-196":["Guia: Bom dia, pessoal! Este quadro aqui é de 1920. Aquele quadro grande lá é do Portinari. Estas cadeiras são muito antigas, então, por favor, não sentem nelas. Aquelas portas no final levam à cafeteria."],"bkA1-197":["A: Bom dia! Posso ajudar?","B: Sim. Quanto custam estes pãezinhos?","A: Cinquenta centavos cada.","B: Certo, seis pãezinhos, por favor. E aquele bolo está fresco?","A: Sim, é de hoje."],"bkA1-198":["Olha! Aquele carro ali é igualzinho ao meu."],"bkA1-199":["Oi, Rita! Estou na feira. Estas mangas aqui estão muito baratas hoje, só 5 reais o quilo. Aqueles abacates na outra barraca são bem grandes, mas são caros. Você quer este abacaxi também? Ele é doce. Joana"],"bkA1-200":["Minha mãe é enfermeira."],"bkA1-201":["Preciso de uma hora para terminar este relatório."],"bkA1-202":["Qual expressão está correta? → uma cidade europeia"],"bkA1-203":["Gustavo é engenheiro. Ele trabalha numa empresa italiana em Joinville. Ele dirige um carro pequeno e tem um apartamento perto do rio."],"bkA1-204":["A: Você quer um sanduíche?","B: Não, obrigado. Só quero uma maçã e um copo de água."],"bkA1-205":["Ela é uma pessoa honesta e uma boa amiga."],"bkA1-206":["É um aplicativo útil para um estudante de inglês."],"bkA1-207":["Meu pai é médico em Recife."],"bkA1-208":["Eu tenho uma entrevista amanhã."],"bkA1-209":["Isso é uma laranja."],"bkA1-210":["Eu tenho um guarda-chuva."],"bkA1-211":["Ela é professora de inglês em Curitiba."],"bkA1-212":["Tem uma universidade na sua cidade?"],"bkA1-213":["São sessenta minutos. / uma hora","Estudantes estudam lá. / uma universidade","É um animal grande e cinza. / um elefante","Policiais usam isso. / um uniforme"],"bkA1-216":["A: Boa noite. Vocês têm um quarto para esta noite?","B: Sim, temos um quarto de casal e um quarto de solteiro.","A: Um quarto de solteiro, por favor. Tem elevador?","B: Sim, tem. Seu quarto fica no quarto andar."],"bkA1-217":["Oi! Eu sou o Otávio. Sou arquiteto, e a minha esposa, Sônia, é veterinária. Temos um filho e uma filha. Moramos numa casa antiga perto de um parque em Campinas. Temos um cachorro, mas não temos carro."],"bkA1-218":["É um exercício fácil."],"bkA1-219":["Vende-se: uma bicicleta azul e uma guitarra elétrica. A bicicleta custa 300 reais. A guitarra custa 800 reais e vem com uma capa. Ligue para o Hugo depois das 18h, no 99876-5432."],"bkA1-220":["Como se diz 17? → dezessete"],"bkA1-221":["O Dia da Independência do Brasil é no dia sete de setembro."],"bkA1-222":["A passagem custa 350 reais. Como se diz 350? → trezentos e cinquenta"],"bkA1-223":["A: Em que andar fica o consultório do dentista?","B: Fica no quinto andar.","A: E o banheiro?","B: Fica no segundo andar."],"bkA1-224":["Há sete dias numa semana e doze meses num ano. Fevereiro tem vinte e oito dias, às vezes 29."],"bkA1-225":["Nosso apartamento fica no décimo segundo andar e tem três quartos."],"bkA1-226":["Venha à nossa festa de cinco anos de casamento, no dia vinte e um de maio."],"bkA1-227":["Esta é a minha terceira vez no Brasil."],"bkA1-228":["Minha avó tem noventa e quatro anos."],"bkA1-229":["Eu tenho dois irmãos e três irmãs."],"bkA1-230":["Clara termina em segundo lugar."],"bkA1-231":["Meu escritório fica no nono andar."],"bkA1-232":["Há sessenta minutos numa hora."],"bkA1-233":["21º / vigésimo primeiro","30 / trinta","3º / terceiro","14 / catorze","1.000 / mil"],"bkA1-236":["Olá, aqui é o consultório do Dr. Almeida. Sua consulta é na quinta-feira, 3 de março, às 14h15. Nosso endereço é Rua Augusta, 480, décimo primeiro andar, sala 1104. Por favor, chegue quinze minutos antes."],"bkA1-237":["A família Silva tem quatro filhos. Bruno é o primeiro filho; ele tem vinte anos. Lara é a segunda; ela tem dezessete. Os gêmeos, Davi e Enzo, são os mais novos. Eles têm onze anos."],"bkA1-238":["A: Dois ingressos para o filme das nove, por favor.","B: Claro. Dá quarenta e seis reais.","A: Aqui estão cinquenta.","B: Obrigado. Aqui está o seu troco, quatro reais.","A: Valeu! Em que fileira ficam os nossos lugares?","B: Na quinta fileira."],"bkA1-239":["Trinta menos dezoito é doze."],"bkA1-240":["Há um problema com o meu computador."],"bkA1-241":["Há muitas pessoas na praia hoje."],"bkA1-242":["A: Tem açúcar? B: Não, não tem."],"bkA1-243":["A: Tem bons restaurantes no seu bairro?","B: Sim, tem. Há um ótimo restaurante japonês ao lado do meu prédio."],"bkA1-244":["Meu quarto de hotel em Lisboa é agradável. Há uma cama grande, e ela é muito confortável. Há duas janelas com vista para o rio. Não há TV, então não posso assistir ao noticiário. Não há toalhas, então preciso ligar para a recepção."],"bkA1-245":["Há um pouco de leite, mas não há biscoitos."],"bkA1-246":["Há ônibus para o aeroporto? Sim, há muitos."],"bkA1-247":["Há uma farmácia na esquina."],"bkA1-248":["Há um supermercado grande perto da minha casa."],"bkA1-249":["Não há alunos no laboratório."],"bkA1-250":["Tem uma academia neste prédio?"],"bkA1-251":["Quantas pessoas há na sua família?"],"bkA1-252":["Não há ponto de ônibus nesta rua."],"bkA1-253":["Quantos quartos tem? / Tem três.","Tem garagem? / Não, não tem, mas você pode estacionar na rua.","Tem lojas por perto? / Sim, tem duas na próxima rua.","Tem Wi-Fi? / Sim, e a senha está na geladeira."],"bkA1-256":["Bem-vindo a Ilha Grande! Não há carros na ilha, então você anda a pé ou pega um barco. Há mais de cem praias. Há uma vila pequena com restaurantes e lojas. Não há banco, então traga dinheiro em espécie."],"bkA1-257":["Apartamento para alugar em Florianópolis. Há dois quartos e um banheiro. Há uma sacada pequena com vista para o mar. Não há garagem, mas há um ponto de ônibus em frente ao prédio. Aluguel: 2.500 reais por mês."],"bkA1-258":["A: Com licença, tem mesa para quatro?","B: Desculpe, não há mesas livres agora.","A: Ah. A espera é longa?","B: Não muito. Uns dez minutos.","A: Tudo bem, podemos esperar."],"bkA1-259":["Há muito trânsito em São Paulo todos os dias."],"bkA1-260":["Carlos lava o carro dele todo domingo."],"bkA1-261":["Você fala inglês no trabalho?"],"bkA1-262":["Meu irmãozinho chora muito à noite."],"bkA1-263":["A: Seus pais moram em São Paulo?","B: Não, não moram. Eles moram em Campinas.","A: Seu pai também trabalha lá?","B: Sim, trabalha."],"bkA1-264":["Todo dia, Beto acorda às 6. Ele toma café e vai para o trabalho de trem. Ele não almoça em casa."],"bkA1-265":["Meu amigo Kaio é um estudante ocupado. Ele estuda medicina na UFMG. À noite, joga vôlei no time da universidade. Tem um emprego de meio período numa livraria. Ele não sai muito, mas assiste a jogos de futebol na TV aos domingos."],"bkA1-266":["Meu gato dorme o dia todo, mas meus cachorros brincam no jardim."],"bkA1-267":["Meu irmão tem dois filhos."],"bkA1-268":["Sua mãe cozinha aos domingos?"],"bkA1-269":["A Isabela toma café de manhã?"],"bkA1-270":["Meu avô não assiste ao noticiário."],"bkA1-271":["Meu pai não toma café depois do almoço."],"bkA1-272":["Onde o seu irmão trabalha?"],"bkA1-273":["Você toca violão? / Não, não toco. Eu toco bateria.","O Leo fala francês? / Não, não fala. Ele fala italiano.","Seus amigos gostam de funk? / Sim, eles adoram.","Chove muito aqui? / Sim, chove, no verão."],"bkA1-276":["Meu nome é Akira e sou comissário de bordo. Não tenho uma rotina normal. Em algumas semanas trabalho cinco dias, e em outras só três. Quando estou em casa, em Guarulhos, durmo bastante e cozinho comida japonesa. Minha esposa é professora, então trabalha de segunda a sexta. Aos domingos, visitamos os pais dela."],"bkA1-277":["Dona Célia tem uma pequena padaria em Olinda. Ela abre às 5h todos os dias, menos segunda-feira. Faz pães e bolos, e o filho dela ajuda com o café. Os turistas adoram a tapioca dela."],"bkA1-278":["A: O que você faz?","B: Sou programador. Trabalho de casa.","A: Você gosta?","B: Gosto. Mas não vejo meus colegas de trabalho com muita frequência."],"bkA1-279":["Meus pais não têm carro."],"bkA1-280":["Quanto custa esta bolsa? Custa 80 reais."],"bkA1-281":["Quantos irmãos você tem? Dois."],"bkA1-282":["Quem é aquele homem? É o meu chefe."],"bkA1-283":["A: Como você vai para o trabalho?","B: De bicicleta. É rápido e barato.","A: A que horas você sai de casa?","B: Às 7h30.","A: Onde fica o seu escritório?","B: Perto do Parque Ibirapuera."],"bkA1-284":["A: De quem é este carro? Ele é muito bonito.","B: É do meu tio.","A: Qual é a cor dele? Azul-escuro ou preto?","B: É azul-escuro."],"bkA1-285":["Por que você está tão feliz? Porque hoje é o meu aniversário!"],"bkA1-286":["Qual ônibus vai para o aeroporto, o 100 ou o 200? E quanto tempo dura a viagem?"],"bkA1-287":["Quanto dinheiro você tem?"],"bkA1-288":["O que você faz nos fins de semana?"],"bkA1-289":["A que horas a loja fecha?"],"bkA1-290":["Quem cozinha o jantar?"],"bkA1-291":["Com que frequência você vai à academia?"],"bkA1-292":["De quem é o celular que está na mesa?"],"bkA1-293":["Quantos anos tem o seu filho? / Ele tem seis.","A que distância fica a praia? / Cerca de dois quilômetros.","Qual é a sua profissão? / Sou eletricista.","Qual você quer, o vermelho ou o azul? / O azul, por favor.","De quem são estas chaves? / São da Tânia."],"bkA1-296":["A: Oi! Qual é o seu nome?","B: Sou Sofía Ramos.","A: De onde você é, Sofía?","B: Sou do México.","A: Quantas noites você quer?","B: Três noites, por favor."],"bkA1-297":["Oi, Nara! Bem-vinda à equipe. Seu primeiro dia é na segunda-feira. Por favor, venha ao terceiro andar às 9h e pergunte pelo Joel. Ele é o seu gerente. Traga seu documento de identidade e uma foto. O almoço é ao meio-dia no refeitório. Até breve! Helena, RH"],"bkA1-298":["Rodrigo é motorista de ônibus em Porto Alegre. Ele trabalha à noite porque gosta das ruas tranquilas. Mora com a avó numa casinha. Aos sábados, joga xadrez no parque com os amigos."],"bkA1-299":["Que idiomas você fala? Português e inglês."],"bkA1-300":["O mês entre março e maio é abril."],"bkA1-301":["No Brasil, os alunos têm férias escolares em janeiro e em julho."],"bkA1-302":["No outono, as folhas caem das árvores."],"bkA1-303":["Os dias úteis são segunda, terça, quarta, quinta e sexta-feira. Abril, junho, setembro e novembro têm trinta dias."],"bkA1-304":["A: Que dia é hoje?","B: É sexta-feira. Amanhã é sábado!","A: Ótimo! E qual é a data?","B: É dia trinta de junho."],"bkA1-305":["O Carnaval geralmente é em fevereiro, no verão brasileiro."],"bkA1-306":["Nos EUA, o ano letivo começa em setembro, no outono."],"bkA1-307":["Nossa viagem para o Chile é em fevereiro."],"bkA1-308":["Há doze meses num ano."],"bkA1-309":["Quando é o aniversário dela?"],"bkA1-310":["A quinta-feira vem depois da quarta-feira."],"bkA1-311":["A estação chuvosa em Manaus vai de dezembro a maio."],"bkA1-312":["Qual é a sua estação favorita?"],"bkA1-313":["Dia de Natal / 25 de dezembro","Dia de Ano-Novo / 1º de janeiro","Dia dos Namorados (EUA) / 14 de fevereiro","Dia da Independência do Brasil / 7 de setembro"],"bkA1-316":["No sul do Brasil, o inverno vai de junho a setembro. Faz frio, e às vezes neva nas serras. O verão vai de dezembro a março. No verão, muita gente vai à praia em Santa Catarina. A primavera começa em setembro."],"bkA1-317":["Calendário escolar – Primeiro semestre. As aulas começam na segunda-feira, 3 de fevereiro. Não há aulas durante o Carnaval, de 3 a 5 de março. As férias de inverno começam na sexta-feira, 27 de junho. As aulas voltam na segunda-feira, 28 de julho."],"bkA1-318":["A: Você está livre na quinta?","B: Não, tenho aula de inglês às quintas. E na sexta?","A: Sexta é perfeito. Vamos ao cinema!","B: Ótimo! A gente se vê na sexta."],"bkA1-319":["O mês depois de julho é agosto."],"bkA1-320":["Não se preocupe. Está tudo bem."],"bkA1-321":["Cuidado! O chão está molhado."],"bkA1-322":["Vamos pedir uma pizza hoje à noite!"],"bkA1-323":["Como fazer uma salada de frutas: Corte as bananas e as maçãs em pedaços pequenos. Coloque-os numa tigela grande. Acrescente um pouco de suco de laranja e misture bem. Não adicione açúcar. A fruta é doce!"],"bkA1-324":["A: Com licença, como eu chego à rodoviária?","B: Siga em frente nesta rua e vire à esquerda na igreja. Não pegue táxi. É bem perto!"],"bkA1-325":["Não esqueça o seu passaporte e me ligue quando chegar."],"bkA1-326":["Por favor, fiquem em silêncio e desliguem os celulares."],"bkA1-327":["Por favor, sente-se aqui."],"bkA1-328":["Não fume aqui, por favor."],"bkA1-329":["Feche a janela."],"bkA1-330":["Vamos juntos à praia."],"bkA1-331":["Por favor, não deixe suas bolsas aqui."],"bkA1-332":["Lave as mãos antes do jantar."],"bkA1-333":["Está chovendo. / Leve um guarda-chuva.","O bebê está dormindo. / Não faça barulho.","A sopa está muito quente. / Não tome agora.","Você tem prova amanhã. / Estude hoje à noite!"],"bkA1-336":["Médico: Olá! Por favor, sente-se. Qual é o problema?","Paciente: Estou com uma dor de cabeça forte.","Médico: Certo. Tome este remédio duas vezes por dia.","Paciente: Posso tomar café?","Médico: Não, não tome café esta semana."],"bkA1-337":["Dicas para o seu primeiro dia de trabalho: Chegue dez minutos mais cedo. Sorria e cumprimente seus colegas. Não use o celular nas reuniões. Faça perguntas, porque ninguém sabe tudo no primeiro dia! E não esqueça o seu almoço."],"bkA1-338":["Oi, Bianca! As crianças jantam às 7. Dê arroz e frango para elas. Está na geladeira. Não dê doces. Elas podem assistir TV até as 20h30. Depois, coloque-as na cama. Me ligue se tiver algum problema. Obrigada, Marcela"],"bkA1-339":["Não coma na sala de aula, por favor."],"bkA1-340":["A Copa do Mundo no Brasil foi em 2014."],"bkA1-341":["Espere por mim no ponto de ônibus."],"bkA1-342":["Tem uma aranha na parede!"],"bkA1-343":["A: Cadê o Lucas?","B: Está no trabalho. Ele sai às 18h.","A: E a Jana?","B: Está na cama. Ela está doente."],"bkA1-344":["Eu nasci em Recife, no dia 10 de março de 1995, à noite."],"bkA1-345":["A: Onde você mora?","B: Moro em Santos, na Rua Paraná, número 45."],"bkA1-346":["Vamos nos encontrar na entrada, na sexta-feira à tarde."],"bkA1-347":["A Ana mora no quinto andar de um prédio na Avenida Paulista."],"bkA1-348":["Até às 8 horas!"],"bkA1-349":["Meu irmão está no hospital."],"bkA1-350":["Minha aula é na terça-feira."],"bkA1-351":["As crianças ficam na escola até o meio-dia."],"bkA1-352":["Nós jantamos em casa aos domingos."],"bkA1-353":["Coloque os pratos / na mesa.","Natal é uma cidade / no nordeste do Brasil.","O despertador toca / às 5h40.","O Dia das Mães no Brasil é / no segundo domingo de maio."],"bkA1-356":["A: Oi, Clara! Você está em casa?","B: Não, estou no shopping. Por quê?","A: Vamos almoçar juntas. Pode ser à 1h da tarde?","B: Claro! Me encontre na praça de alimentação, no terceiro andar."],"bkA1-357":["Rock in the Park! Sábado, 8 de novembro, no Parque Ibirapuera. Os portões abrem às 14h, e a primeira banda toca às 16h. Os food trucks ficam perto do lago. Se chover, o show será no domingo, no mesmo horário."],"bkA1-358":["Marina é comissária de bordo. Ela mora em Brasília, num apartamento pequeno no sexto andar. Trabalha nos fins de semana e à noite. Em dezembro, ela voa muito para a Europa. Nos dias de folga, fica em casa e lê."],"bkA1-359":["Meu pai trabalha num banco."],"bkA1-1001":["Por favor, coloque as duas facas na mesa."],"bkA1-1002":["As crianças estão brincando no jardim."],"bkA1-1003":["Na minha bolsa, tenho dois relógios, três chaves e quatro fotos."],"bkA1-1004":["Olhe aqueles homens e mulheres. Eles são professores."],"bkA1-1005":["Minhas calças jeans são novas, e eu tenho dois pares de óculos."],"bkA1-1006":["Meus dois bebês estão dormindo."],"bkA1-1007":["Minhas calças jeans estão grandes demais."],"bkA1-1008":["As mulheres têm relógios."],"bkA1-1009":["Estas folhas são verdes."],"bkA1-1010":["Eu preciso de dois pares de calças jeans."],"bkA1-1011":["Rosa trabalha numa loja pequena. Hoje ela tem três caixas, duas facas e cinco batatas na mesa dela. Os dois filhos dela estão com ela. Eles estão ajudando na loja."],"bkA1-1012":["homem / homens","faca / facas","cidade / cidades","camundongo / camundongos"],"bkA1-1014":["Escove os dentes depois do almoço."],"bkA1-1015":["Inglês é a minha matéria favorita."],"bkA1-1016":["Meu irmão toca guitarra numa banda."],"bkA1-1017":["A: Eu assisti a um filme ontem à noite.","B: Era bom?","A: Sim! O filme era sobre um robô, e o robô era engraçado."],"bkA1-1018":["Eu adoro música, mas a música desta loja está alta demais."],"bkA1-1019":["Meu tio joga futebol, e o piano do quarto dele é muito velho."],"bkA1-1020":["A vida é bela."],"bkA1-1021":["Eu vou dormir às dez toda noite."],"bkA1-1022":["Ela vai para o trabalho de ônibus."],"bkA1-1023":["Eu jantei em casa."],"bkA1-1024":["Nós somos dos Estados Unidos."],"bkA1-1025":["Anna tem um pequeno restaurante à beira do rio. Ela cozinha comida italiana. Todo dia ela vai ao mercado de ônibus. O almoço é a hora de maior movimento. À noite ela vai para casa e toca violino."],"bkA1-1028":["Vimos um gato. O gato era preto."],"bkA1-2001":["Minha irmã tem dois gatos."],"bkA1-2002":["A: Você tem um irmão?","B: Não, não tenho irmão, mas tenho uma irmã.","A: Ela tem filhos?","B: Sim, ela tem dois meninos."],"bkA1-2003":["Eles têm um jardim grande, mas ele não tem jardim."],"bkA1-2004":["Você tem um lápis?"],"bkA1-2005":["Ele não tem celular."],"bkA1-2006":["Você tem uma bicicleta?"],"bkA1-2007":["Meu nome é Rita. Tenho dois cachorros, mas não tenho gato. Tenho uma bicicleta nova e vou de bicicleta para o trabalho. Eu tomo café da manhã às sete horas todos os dias."],"bkA1-2008":["Você tem uma caneta? / Sim, tenho.","Ele tem carro? / Não, não tem.","Ela tem notebook? / Não, não tem.","Eles têm casa? / Sim, têm."],"bkA1-2010":["A: Você tem cachorro, Paulo?","B: Não, não tenho, mas tenho uma gata.","A: Qual é o nome dela?","B: O nome dela é Mimi."],"bkA1-2012":["Como se diz a sua idade? → Eu tenho 30 anos."],"bkA1-2013":["Lucy está resfriada, então ela não toma café da manhã hoje."],"bkA1-2014":["Nós sempre nos divertimos na festa da Ana."],"bkA1-2015":["Qual pergunta é sobre as horas? → Que horas são?"],"bkA1-2016":["A: Com licença, que horas são?","B: São quinze para as nove.","A: Obrigado! E o trem?","B: Ele sai às nove e dez."],"bkA1-2017":["O filme começa às 8 horas. Eu estudo à noite, mas durmo de madrugada."],"bkA1-2018":["Eu acordo de manhã."],"bkA1-2019":["São sete e meia."],"bkA1-2020":["São dez para as nove."],"bkA1-2021":["A que horas começa o filme?"],"bkA1-2022":["Ana é estudante em Recife. A escola começa às sete e quinze da manhã. O almoço é ao meio-dia. Ela termina às quatro e meia da tarde. Ela vai dormir às dez da noite."],"bkA1-2023":["3h15 / três e quinze","6h45 / quinze para as sete","9h30 / nove e meia","12h / meio-dia"],"bkA1-2026":["Como se diz 5h45? → quinze para as seis"],"bkA1-2027":["Meu ônibus sai às sete horas."],"bkA1-2028":["A: Com licença, que horas são?","B: São vinte para as cinco.","A: Obrigado! A que horas sai o trem?","B: Ele sai às cinco horas."],"bkA1-2029":["grande / pequeno","quente / frio","novo / velho","fácil / difícil","limpo / sujo"],"bkA1-2030":["A sopa está quente, mas o sorvete está gelado.","Minha bolsa é pesada, mas a sua bolsa é leve."],"bkA1-2031":["A: A prova é fácil?","B: Não, é difícil.","A: Seu irmão é alto?","B: Não, ele é baixo."],"bkA1-2032":["Nós temos dois cachorros pequenos."],"bkA1-2033":["Meu quarto é claro: tem janelas grandes e muito sol."],"bkA1-2035":["Pedro é alto. A irmã dele é baixa."],"bkA1-2036":["Esta é uma casa grande. Temos dois quartos grandes. Qual é a sua altura?"],"bkA1-2037":["Meu irmão tem dois cachorros grandes."],"bkA1-2038":["Meu quarto é muito pequeno."],"bkA1-2039":["Qual é o oposto de grande?"],"bkA1-2040":["Sua bolsa é pesada demais para mim."],"bkA1-2041":["A: Seu apartamento novo é grande?","B: Não, é pequeno, mas é muito limpo.","A: É caro?","B: Não, é barato."],"bkA1-2042":["Pedro tem doze anos. Ele é alto, mas a irmã dele, Lia, é baixa. Lia tem nove. A casa deles é velha e grande. O jardim é pequeno, mas é muito bonito."],"bkA1-2043":["Oi, Rita, eu tenho um emprego novo. O escritório é grande e limpo, mas o trabalho é difícil. Meu chefe é jovem e muito simpático. O café é barato! Mas o ônibus é lento, então eu me atraso com frequência. Até breve, Carla."],"bkA1-2045":["É domingo, e o banco não está aberto. Está fechado."],"bkA2-0":["Olhe! As crianças estão brincando no jardim."],"bkA2-1":["Agora mesmo, o Marcos está fazendo o jantar e as irmãs dele estão pondo a mesa."],"bkA2-2":["É manhã de sábado na casa dos Oliveira. O pai está lavando o carro na garagem. A mãe está lendo um livro no sofá. Os gêmeos estão jogando videogame na sala de estar, e o bebê está dormindo no berço dela."],"bkA2-3":["Por favor, fique em silêncio. O bebê está dormindo e eu estou tentando trabalhar."],"bkA2-4":["Ela está estudando inglês neste momento."],"bkA2-5":["Eles estão trabalhando de casa hoje?"],"bkA2-6":["Por que você está usando casaco hoje?"],"bkA2-7":["A: Oi, Julia! Onde você está?","B: Estou no shopping. Estou comprando um presente para o Leo.","A: Ah, legal! O que você está comprando?","B: Uma camiseta. Ele adora azul, então estou procurando uma azul."],"bkA2-8":["São 20h em São Paulo. Renata está sentada na sacada. Ela não está assistindo TV esta noite; está lendo um romance. O marido dela, Caio, está cozinhando macarrão na cozinha. O cachorro deles está dormindo embaixo da mesa."],"bkA2-9":["O que você está fazendo? / Estou fazendo meu dever de casa.","Aonde o papai está indo? / Ele está indo ao banco.","Por que as crianças estão rindo? / Porque estão assistindo a um filme engraçado.","Está chovendo? / Não, não está. Está ensolarado."],"bkA2-10":["No verão passado, nós fomos a Salvador de avião."],"bkA2-11":["Ontem, a Bia acordou tarde, perdeu o ônibus e chegou ao trabalho às dez."],"bkA2-12":["Você viu o jogo ontem à noite? Não, eu não tive tempo."],"bkA2-13":["Nós não fomos à praia no fim de semana passado."],"bkA2-14":["A Carla comprou um celular novo semana passada?"],"bkA2-15":["Onde você passou as suas últimas férias?"],"bkA2-16":["Oi, Tom! Minha viagem ao Rio foi incrível. Cheguei na sexta à noite e fiquei num hotelzinho perto de Copacabana. No sábado, visitei a estátua do Cristo Redentor, mas estava muito nublado, então não vi muita coisa. No domingo, o sol apareceu e passei o dia inteiro na praia. Voltei para casa na segunda de manhã. Com carinho, Lucy"],"bkA2-18":["escrever / escreveu","ver / viu","fazer / fez","pensar / pensou"],"bkA2-19":["Minha família morou em Recife de 2015 a 2019."],"bkA2-20":["Olhe aquelas nuvens escuras! Vai chover."],"bkA2-21":["A: Estou com tanta sede. B: Espere aqui. Vou buscar um copo de água para você."],"bkA2-22":["A: Quais são os seus planos para as férias?","B: Minha esposa e eu vamos visitar os pais dela em Curitiba. Compramos as passagens no mês passado.","A: Que ótimo! Tenho certeza de que vocês vão se divertir."],"bkA2-23":["Minha irmã vai ter um bebê em junho, e acho que ela vai ser uma ótima mãe."],"bkA2-24":["Acho que vai fazer sol amanhã."],"bkA2-25":["Eles não vão comprar um carro novo."],"bkA2-26":["O que você vai fazer hoje à noite?"],"bkA2-27":["A: Ei, você vai à festa de sábado?","B: Não sei. Não tenho carona.","A: Não se preocupe. Eu busco você às oito.","B: Ótimo, valeu! Vou estar pronto."],"bkA2-28":["No ano que vem, o Diego vai estudar no Canadá. Ele já tem uma vaga numa faculdade em Toronto. Ele está preocupado com o frio, mas os amigos dizem que ele vai adorar a cidade. A mãe dele acha que ele vai sentir falta da comida brasileira."],"bkA2-29":["Olhe aquele carro! Está indo rápido demais. / Ele vai bater!","Estou com dor de cabeça. / Vou tomar uma aspirina.","Comprei tinta e pincéis. / Vou pintar meu quarto.","O telefone está tocando. / Eu atendo."],"bkA2-30":["O Monte Everest é a montanha mais alta do mundo."],"bkA2-31":["Meu apartamento novo é maior do que o antigo, mas também é mais caro."],"bkA2-32":["Este é o pior filme do ano, e é mais chato do que o primeiro."],"bkA2-33":["O Rio é mais quente do que Porto Alegre no inverno."],"bkA2-34":["Seu carro é mais rápido do que o meu."],"bkA2-35":["São Paulo é a maior cidade do Brasil."],"bkA2-36":["Esta é a praia mais bonita da Bahia."],"bkA2-37":["Três amigos estão procurando um hotel em Gramado. O Hotel Pinheiro custa R$300 a noite e fica a dez minutos do centro. O Hotel Serra custa R$250. É o mais longe do centro, mas tem a melhor vista. O Hotel Flor é o mais caro, R$400 a noite, mas é o mais perto do centro."],"bkA2-40":["Você parece cansado. Deveria ir dormir cedo esta noite."],"bkA2-41":["A: Você sabe nadar?","B: Sei, sim. Aprendi quando tinha seis anos."],"bkA2-42":["Os alunos não podem usar o celular durante a prova. Eles devem desligá-los."],"bkA2-43":["Você deveria beber mais água."],"bkA2-44":["A Maria sabe falar três idiomas?"],"bkA2-45":["Você deve usar capacete numa moto."],"bkA2-46":["A: Com licença, posso estacionar aqui?","B: Não, desculpe. Você não pode estacionar aqui. É só para ônibus.","A: Ah! Onde devo estacionar, então?","B: Há um estacionamento na próxima rua."],"bkA2-47":["Bem-vindo ao Parque das Aves! Os visitantes podem tirar fotos, mas não podem usar flash. Você não deve alimentar as aves, porque a comida humana pode deixá-las doentes. Crianças menores de 12 anos devem estar com um adulto. O parque abre às 8h30."],"bkA2-48":["Está muito frio lá fora. / Você deveria usar um casaco.","A placa diz \"Proibido fumar\". / Você não pode fumar aqui.","Não entendo este exercício. / Você pode perguntar ao professor.","Meu irmão tem só dois anos. / Ele ainda não sabe ler."],"bkA2-49":["Desculpe, não posso ir à sua festa no sábado. Tenho que trabalhar."],"bkA2-50":["Está frio. Vista a jaqueta antes de sair."],"bkA2-51":["Não consigo achar minhas chaves. Você pode me ajudar a procurá-las?"],"bkA2-52":["Todo dia, Lucas acorda às 6h, mas levanta às 6h30 porque adora a cama dele. Na cozinha, ele liga o rádio para ouvir o noticiário. Depois do trabalho, ele costuma sair com os amigos."],"bkA2-53":["Por favor, apague as luzes quando sair e busque as crianças na escola às cinco."],"bkA2-54":["Minha avó cuida do meu irmãozinho quando meus pais estão no trabalho."],"bkA2-55":["desistir / parar de tentar","descobrir / ficar sabendo","voltar / retornar","sentar / ocupar um lugar"],"bkA2-56":["Vou experimentar / estas calças jeans.","Por favor, abaixe / a música. Está alta demais.","Não desista / agora! Você consegue.","Você pode preencher / este formulário, por favor?"],"bkA2-57":["Oi, Carol, preciso de um favor. Vou viajar neste fim de semana e volto na segunda. Você pode cuidar da minha gata, a Mimi? Basta encher o potinho de água dela e dar comida duas vezes por dia. Por favor, não deixe ela sair, porque ela sempre foge! A chave está embaixo da planta. Obrigada! Ana"],"bkA2-59":["Por favor, desligue o celular durante o filme."],"bkA2-60":["Quanto açúcar você quer no seu café?"],"bkA2-61":["Quantas pessoas vêm à festa? E de quanta comida precisamos?"],"bkA2-62":["Tenho alguns amigos em Manaus e falo um pouco de espanhol."],"bkA2-63":["Não há muito trânsito hoje."],"bkA2-64":["Não há muitas cadeiras na sala de aula."],"bkA2-65":["Não há nenhum suco na garrafa."],"bkA2-66":["A: Bom dia. Posso pegar uns pãezinhos, por favor?","B: Claro. Quantos pãezinhos você quer?","A: Seis, por favor. E vocês têm queijo?","B: Desculpe, hoje não temos queijo."],"bkA2-67":["Marta está fazendo uma lista de compras. Ela tem muito arroz e um pouco de macarrão em casa, mas não tem café. Há só alguns ovos na geladeira, então ela precisa comprar mais. Ela não precisa de fruta, porque tem muitas bananas."],"bkA2-69":["Quanta água você bebe? / Cerca de dois litros por dia.","Quantos irmãos você tem? / Dois. Os dois são mais velhos do que eu.","Tem café? / Tem, sim, tem um pouco na cozinha.","Tem bons restaurantes aqui? / Sim, tem muitos."],"bkA2-70":["Paula é vegetariana. Ela nunca come carne."],"bkA2-71":["Meu pai toma café toda manhã. Ele sempre toma café com o café da manhã. Ele odeia chá, então nunca bebe."],"bkA2-72":["Tom está sempre cansado depois do trabalho, e costuma ir dormir às nove."],"bkA2-73":["Geralmente vamos à praia aos domingos."],"bkA2-74":["Marina está sempre feliz às sextas."],"bkA2-75":["Eu quase nunca assisto TV durante a semana."],"bkA2-76":["Com que frequência você vai à academia?"],"bkA2-77":["Olá, eu sou o Kenji e sou enfermeiro em Belo Horizonte. Eu sempre acordo às 5h porque meu plantão começa às 7h. Geralmente almoço no hospital, mas às vezes levo comida de casa. Raramente saio durante a semana porque estou cansado. Nos fins de semana, frequentemente jogo futebol com meus amigos. Nunca trabalho aos domingos."],"bkA2-79":["100% / sempre","80% / geralmente","50% / às vezes","0% / nunca"],"bkA2-80":["Este é o quarto das minhas irmãs. Elas dividem o quarto."],"bkA2-81":["O nome do meu chefe é Carlos. Os nomes dos filhos dele são Pedro e Lia."],"bkA2-82":["O celular da Julia é novo, mas o carro dos pais dela é muito velho."],"bkA2-83":["Esta é a bicicleta do Pedro."],"bkA2-84":["A casa dos meus avós fica em Minas Gerais."],"bkA2-85":["Este é o notebook do meu irmão."],"bkA2-86":["Onde fica o escritório do seu pai?"],"bkA2-87":["A: De quem é esta jaqueta?","B: Acho que é do Leo.","A: Não, a jaqueta do Leo é preta. Esta é azul.","B: Ah, então provavelmente é da Sara."],"bkA2-88":["Esta é a família Costa. O nome do Sr. Costa é Jorge, e o nome da esposa dele é Helena. Os nomes dos filhos deles são Bruno e Lara. O cachorro do Bruno, o Rex, dorme no quarto da Lara. A casa da família fica perto da praia, em Natal."],"bkA2-89":["De quem é esta bolsa? / É do Tiago.","Onde está o carro da mamãe? / Está na garagem do meu tio.","Quem é a Carla? / É a esposa do meu primo.","De quem são estes sapatos? / São das crianças."],"bkA2-90":["O banco fica entre a farmácia e a padaria."],"bkA2-91":["Vire à direita no semáforo. Depois siga em frente por dois quarteirões. Passe pela escola, e o museu fica na esquina da Rua Bahia com a Rua Goiás. Fica em frente aos Correios."],"bkA2-92":["A: Com licença, como posso chegar à estação?","B: Siga em frente e pegue a segunda rua à esquerda."],"bkA2-93":["O supermercado fica ao lado do banco."],"bkA2-94":["Tem uma farmácia perto daqui?"],"bkA2-95":["A: Com licença, tem algum ponto de ônibus perto daqui?","B: Tem sim, há um na Avenida Paulista.","A: Como chego lá?","B: Siga em frente e vire à esquerda na segunda esquina. Fica em frente a um banco.","A: Muito obrigado!"],"bkA2-96":["Bem-vindo ao nosso hotel! Veja como chegar à praia. Quando sair do hotel, vire à direita e ande até o fim da rua. No posto de gasolina, vire à esquerda. Passe pelo supermercado e atravesse a avenida no semáforo. A praia fica logo à sua frente. Leva cerca de dez minutos."],"bkA2-97":["turn left / vire à esquerda","go straight ahead / siga em frente","cross the street / atravesse a rua","go past the bank / passe pelo banco"],"bkA2-99":["Minha rua é pequena e tranquila. Tem uma padaria na esquina. Ao lado da padaria, tem uma farmácia. Minha casa fica em frente à farmácia, entre uma escola e uma pracinha. Não tem supermercado na minha rua."],"bkA2-100":["Eu estava com fome, então fiz um sanduíche."],"bkA2-101":["Você quer chá ou café? Gosto dos dois, mas prefiro café."],"bkA2-102":["A Ana não foi à escola porque estava doente e ficou na cama o dia todo."],"bkA2-103":["Fiquei em casa porque estava chovendo."],"bkA2-104":["Estou cansado porque trabalhei muito hoje."],"bkA2-105":["Estava muito frio, então não fomos à praia."],"bkA2-106":["Primeiro jantamos e depois assistimos a um filme."],"bkA2-107":["A: Vamos ao cinema hoje à noite!","B: Eu adoraria, mas não tenho dinheiro.","A: Não se preocupe. Eu pago desta vez, e você paga da próxima.","B: Beleza, então vamos nos encontrar no shopping às sete."],"bkA2-108":["O Felipe adora música, mas não toca nenhum instrumento. No ano passado, ele queria aprender violão ou piano. O piano era muito caro, então ele comprou um violão. Agora ele pratica todo dia porque quer tocar no casamento da irmã."],"bkA2-109":["Eu liguei para você / porque preciso da sua ajuda.","Podemos ir de ônibus, / ou podemos pegar um táxi.","Ela estudou muito, / mas não passou na prova.","Começou a chover, / então entramos."],"bkA2-110":["Pode me dar um pouco de água, por favor?"],"bkA2-111":["Há muitos móveis na sala de estar, e há três cadeiras na cozinha."],"bkA2-112":["Minha mãe me deu um conselho e um guarda-chuva antes da minha viagem."],"bkA2-113":["Tenho muito dever de casa hoje à noite."],"bkA2-116":["Prezados hóspedes, o café da manhã é servido das 6h30 às 10h. Temos pão fresco, queijo, presunto e muitas frutas. Também há café, chá e suco de laranja. Você pode comer quantos ovos quiser; basta pedir ao cozinheiro. Por favor, não leve comida para o quarto. Aproveitem a estadia!"],"bkA2-117":["De quanto dinheiro você precisa?"],"bkA2-118":["um pão de forma / pão","um tubo de / pasta de dente","uma barra de / sabão","uma caixa de / leite"],"bkA2-119":["Quanta água você bebe todo dia?"],"bkA2-120":["Por que você está sorrindo, Beatriz?"],"bkA2-121":["Pergunte ao Rafael. Ele sabe a resposta."],"bkA2-122":["Escute! Alguém está batendo na porta."],"bkA2-123":["A: O Gabriel está jogando futebol agora?","B: Não, não está. Ele está estudando para uma prova."],"bkA2-124":["Oi de Florianópolis! O tempo está perfeito hoje. Estou sentada na praia agora. Meus filhos estão nadando no mar, e meu marido está assistindo a um jogo de vôlei com uns amigos. Estamos nos divertindo muito!"],"bkA2-125":["Olhe! O Diego está usando o tênis novo dele, mas não gosta dele."],"bkA2-126":["Seus pais estão viajando esta semana?"],"bkA2-127":["Estamos esperando o ônibus neste momento."],"bkA2-128":["As crianças estão nadando na piscina."],"bkA2-129":["O que a Carla está pintando?"],"bkA2-130":["Não estou usando o computador agora."],"bkA2-131":["O que a sua irmã está assistindo na TV?"],"bkA2-132":["Desta vez não estamos ficando em um hotel."],"bkA2-133":["A: Olá, posso falar com o Sr. Almeida, por favor?","B: Desculpe, ele está em reunião. Está conversando com alguns clientes.","A: Certo. A assistente dele está trabalhando hoje?","B: Não, não está. Ela está viajando esta semana.","A: Sem problema. Ligo de novo mais tarde."],"bkA2-134":["Fernanda está no Aeroporto de Guarulhos. Ela está esperando o voo para Lisboa. O voo está atrasado, então ela está tomando um café e conferindo os e-mails. O irmão dela não está viajando com ela; ele está trabalhando em São Paulo esta semana."],"bkA2-135":["Oi, mãe! Estou escrevendo da biblioteca da escola. Não vou para casa almoçar hoje porque estou fazendo um trabalho com a Lívia e o Tiago. Estamos fazendo um vídeo sobre a floresta amazônica. O Tiago está filmando, e a Lívia e eu estamos escrevendo o roteiro. Volto para casa às seis. Beijos, Nina"],"bkA2-137":["make / making","sit / sitting","lie / lying","study / studying"],"bkA2-139":["Vamos fazer um churrasco na casa do meu tio no próximo domingo. Você quer vir?"],"bkA2-140":["A: Você estava em casa ontem à noite? B: Não, eu estava na academia."],"bkA2-141":["O Rodrigo não fez o dever de casa ontem porque estava doente."],"bkA2-142":["Onde você comprou essa jaqueta? Ela é linda!"],"bkA2-143":["A: Você gostou do show?","B: Gostei, sim. Foi fantástico!","A: A Marcela foi com você?","B: Não, não foi. Ela estava no trabalho."],"bkA2-144":["No sábado passado, minha família e eu fomos ao Parque Ibirapuera fazer um piquenique. Minha mãe fez sanduíches deliciosos para todo mundo. Meu irmãozinho empinou a pipa nova dele bem alto no céu, e meu pai tirou muitas fotos. Chegamos em casa às seis, cansados, mas felizes."],"bkA2-145":["Quando eu era criança, não tinha celular."],"bkA2-146":["Ontem à noite comemos pizza e assistimos a um filme."],"bkA2-147":["Ela comprou um vestido novo para a festa."],"bkA2-148":["Estávamos muito cansados depois da viagem."],"bkA2-149":["Aonde o Paulo foi?"],"bkA2-150":["As crianças não estavam na escola ontem."],"bkA2-151":["A que horas você acordou hoje de manhã?"],"bkA2-152":["Nasci em Porto Alegre em 1998."],"bkA2-153":["A: Oi, Sérgio! Como foi seu fim de semana?","B: Foi ótimo. Fui a um casamento em Belo Horizonte.","A: Sério? De quem era o casamento?","B: Do meu primo. A festa acabou às 3h da manhã!"],"bkA2-154":["Ricardo teve um dia ruim ontem. O despertador dele não tocou, então ele acordou às 8h30. Pegou um táxi para o escritório, mas havia muito trânsito. Chegou atrasado para uma reunião importante. À noite, pediu uma pizza e foi dormir cedo."],"bkA2-155":["Santos Dumont nasceu em Minas Gerais em 1873. Quando tinha 18 anos, mudou-se para Paris. Lá, construiu balões e dirigíveis. Em 1906, voou com seu avião, o 14-bis, diante de uma grande multidão. Muitos brasileiros dizem que ele foi o pai da aviação. Ele morreu em 1932."],"bkA2-157":["Quando você chegou? / Terça-feira passada.","Quem você encontrou? / Meu antigo professor.","Como foi a viagem? / Foi incrível!","Por que você saiu cedo? / Porque eu estava cansado."],"bkA2-159":["A Ana não me ligou ontem à noite."],"bkA2-160":["A: Não temos leite. B: Ah, é mesmo? Eu compro um pouco no caminho de casa."],"bkA2-161":["Cuidado! Aquele copo está na beira da mesa. Ele vai cair."],"bkA2-162":["Não se preocupe, mãe. Eu ligo para você quando chegar em Recife."],"bkA2-163":["A: Você vai assistir à final hoje à noite?","B: Não, não vou. Vou estudar para a prova."],"bkA2-164":["A: O que você vai fazer depois do curso?","B: Vou procurar emprego em Portugal."],"bkA2-165":["Você vai comprar um notebook novo?"],"bkA2-166":["Acho que o Brasil vai ganhar a próxima Copa do Mundo."],"bkA2-167":["Ela vai estudar medicina no ano que vem."],"bkA2-168":["Você me ajuda com a louça?"],"bkA2-169":["A Lara vai estar na reunião?"],"bkA2-170":["A Sofia vai aprender a dirigir no ano que vem."],"bkA2-171":["Prometo que não vou me atrasar de novo."],"bkA2-172":["Onde eles vão ficar em Roma?"],"bkA2-173":["A: Já podem fazer o pedido?","B: Sim. Vou querer o peixe grelhado, por favor.","A: E o que gostariam de beber?","B: Vou querer um suco de laranja."],"bkA2-174":["Carolina e Pedro vão se casar em dezembro. Eles vão fazer a festa numa chácara perto de Campinas. Convidaram 150 pessoas. A Carolina acha que vai chover, mas o Pedro tem certeza de que o tempo vai estar perfeito."],"bkA2-175":["Oi, Jess, Grande novidade! Vou começar um emprego novo em abril. Vou trabalhar numa empresa de tecnologia em Recife, então vou me mudar para lá no mês que vem. Não conheço ninguém na cidade, mas tenho certeza de que vou fazer amigos rápido. Você vai me visitar? Vai adorar as praias! Abraços, Marina"],"bkA2-177":["Estou com fome. / Vou fazer um sanduíche para você.","Está frio aqui. / Vou fechar a janela.","Olhe aquele homem na escada! / Ele vai cair!","Já temos os ingressos. / Vamos ver o show na sexta."],"bkA2-179":["A: A impressora não está funcionando. B: Não se preocupe. Eu conserto para você."],"bkA2-180":["Hoje está mais quente do que ontem. Vamos à praia!"],"bkA2-181":["O Paulo é o melhor aluno da nossa turma. Ele sempre tira notas máximas."],"bkA2-182":["Este celular é mais barato do que aquele."],"bkA2-183":["A Maria é mais nova do que o irmão, mas é a pessoa mais alta da família."],"bkA2-184":["A: O que é mais fácil, espanhol ou inglês?","B: Para mim, espanhol é mais fácil do que inglês, mas inglês é mais útil para o meu trabalho."],"bkA2-185":["Minha avó faz a feijoada mais deliciosa da família."],"bkA2-186":["Sua bolsa é mais pesada do que a minha, e é a maior bolsa do ônibus."],"bkA2-187":["Este é o restaurante mais caro da cidade."],"bkA2-188":["Meu irmão é mais alto do que meu pai."],"bkA2-189":["O vestido azul é mais caro do que o vermelho."],"bkA2-190":["A Marta é tão alta quanto a Clara."],"bkA2-191":["Qual é o rio mais longo do Brasil?"],"bkA2-192":["Meu novo emprego é mais interessante do que o antigo."],"bkA2-193":["A: Gosto destes dois celulares. Qual é melhor?","B: O preto tem uma câmera melhor.","A: Mas é mais caro, né?","B: É, custa R$500 a mais do que o branco.","A: Tá bom, vou levar o branco. É mais barato."],"bkA2-194":["Três amigos correram uma prova em Brasília. O Bruno terminou em 25 minutos, a Lia em 22 minutos e o Jorge em 30 minutos. O Jorge é o mais velho dos três; tem 45 anos. A Lia é mais nova do que o Bruno. Ela é quem mais treina, por isso foi a mais rápida."],"bkA2-195":["A Laura está escolhendo um notebook para a faculdade. O Zeta 3 é mais leve e menor do que o Nova X, então é mais fácil de carregar. O Nova X tem uma tela maior e uma bateria melhor. Também custa R$800 a mais. A Laura assiste a muitos filmes, mas não tem muito dinheiro. No fim, ela escolhe o notebook mais barato."],"bkA2-197":["bom / o melhor","ruim / o pior","longe / o mais longe","muitos / a maioria"],"bkA2-199":["Julho costuma ser o mês mais frio do ano em São Paulo."],"bkA2-200":["Posso usar seu carregador? Meu celular descarregou."],"bkA2-201":["No Brasil, é preciso ter 18 anos para tirar a carteira de motorista."],"bkA2-202":["O Bruno quebrou a perna, então não pode jogar na partida de domingo."],"bkA2-203":["A: Seu inglês é ótimo! Seu irmão também fala inglês?","B: Não, não fala. Mas ele fala espanhol muito bem."],"bkA2-204":["Médico: Você está com um resfriado forte. Deveria ficar de cama por dois dias e não deveria ir ao trabalho. Deveria tomar chá quente com mel."],"bkA2-205":["Você não deveria comer tanto açúcar. Faz mal para os dentes."],"bkA2-206":["Você pode me ajudar? Não consigo abrir este pote."],"bkA2-207":["Ela toca piano muito bem."],"bkA2-208":["Preciso usar gravata na festa?"],"bkA2-209":["Devemos pegar um táxi?"],"bkA2-210":["Você não deve usar o celular na sala de prova."],"bkA2-211":["Você não deveria ir dormir tão tarde."],"bkA2-212":["Você pode falar mais devagar, por favor?"],"bkA2-213":["A: Doutor, eu sempre me sinto cansado.","B: Quantas horas você dorme?","A: Cerca de cinco horas por noite.","B: Isso não é suficiente. Você deveria dormir pelo menos sete horas.","A: Tudo bem, vou tentar. Obrigado, doutor."],"bkA2-214":["Regras da piscina do Clube Atlântico: Todos devem tomar banho antes de nadar. Você pode usar a piscina das 7h às 21h. Não é permitido comer nem beber na água. Crianças menores de 10 anos só podem nadar com um adulto. Você deve trazer sua própria toalha."],"bkA2-215":["Bem-vindo ao meu apartamento! Você pode usar a cozinha e a máquina de lavar. Não pode fumar lá dentro, mas pode fumar na varanda. Por favor, não faça barulho depois das 22h porque meus vizinhos são muito rigorosos. Você deveria visitar a feira no domingo; é ótima. Aproveite! Rosa"],"bkA2-217":["Estou com dor de dente. / Você deveria ir ao dentista.","Quero aprender inglês mais rápido. / Você deveria assistir a séries em inglês.","A placa do museu diz \"Proibido fotos\". / Você não pode usar a câmera.","Perdi meu passaporte. / Você deveria ir à polícia."],"bkA2-219":["Você parece doente. Acho que deveria ir ao médico."],"bkA2-220":["Por favor, tire os sapatos antes de entrar. O chão está limpo."],"bkA2-221":["O leite acabou, então fui ao supermercado."],"bkA2-222":["Este é o nosso ponto. Vamos descer do ônibus."],"bkA2-223":["A Kátia cresceu numa cidade pequena da Bahia, mas agora mora em São Paulo. Ela malha na academia toda manhã e sai com os amigos às sextas."],"bkA2-224":["A: Olá, posso falar com a Dra. Lima?","B: Desculpe, ela saiu. Ela pode ligar de volta mais tarde?","A: Sim, por favor. Meu número é 98765-4321.","B: Um momento, vou anotar.","A: Obrigado. Certo, vou desligar agora. Tchau!"],"bkA2-225":["Está quente aqui. Posso tirar a jaqueta? E por favor, não jogue fora aquela caixa. Eu preciso dela."],"bkA2-226":["Minha jaqueta? Pendurei no armário. E seus livros estão no chão. Por favor, pegue-os."],"bkA2-227":["Estou congelando! Você pode desligar o ar-condicionado?"],"bkA2-228":["Por favor, anote seu nome e endereço aqui."],"bkA2-229":["Tire-os."],"bkA2-230":["Meu carro quebrou na estrada."],"bkA2-231":["A que horas decola o seu voo?"],"bkA2-232":["Geralmente comemos fora nos sábados à noite."],"bkA2-233":["A: Boa tarde. Gostaria de fazer o check-in, por favor.","B: Claro. Posso ver seu passaporte?","A: Aqui está.","B: Obrigado. Seu quarto é o 305. O café da manhã é das sete às dez.","A: Ótimo. E até que horas preciso fazer o check-out?","B: Antes do meio-dia, por favor."],"bkA2-234":["No mês passado, o Rafael decidiu largar o açúcar. No começo foi difícil. Ele jogou fora todo o chocolate da casa e pesquisou receitas saudáveis na internet. Agora ele malha três vezes por semana e se sente ótimo. A irmã dele quer tentar também."],"bkA2-235":["Oi, Leo, estou saindo para o supermercado. Antes de ir para a escola, por favor, leve o lixo para fora e guarde a louça. Não esqueça de desligar o computador. Sua avó vem às cinco, então arrume seu quarto! Até mais, Pai"],"bkA2-237":["crescer / tornar-se adulto","ligar de volta / retornar uma ligação","comer fora / fazer uma refeição em um restaurante","acalmar-se / relaxar e parar de ficar nervoso"],"bkA2-239":["Não conheço esta palavra. Vou procurá-la no dicionário."],"bkA2-240":["Há muitos turistas em Gramado em julho. Os hotéis estão lotados."],"bkA2-241":["Não tenho muito tempo hoje. Podemos conversar amanhã?"],"bkA2-242":["Você gostaria de um pouco de bolo?"],"bkA2-243":["A: Tem leite na geladeira?","B: Tem, mas só um pouquinho. Precisamos comprar mais."],"bkA2-244":["Minha cidade é ótima para comer. Tem muitos restaurantes bons — mais de 500! Mas não tem muitos parques; só há dois. Há poucas árvores na avenida principal, e há trânsito demais."],"bkA2-245":["Não posso comprar. Não tenho dinheiro suficiente. E há carros demais na cidade."],"bkA2-246":["Quantos idiomas você fala? Tenho muito dever de casa hoje."],"bkA2-247":["Não tenho nenhum dinheiro."],"bkA2-248":["Há um pouco de água na garrafa."],"bkA2-249":["Não tenho muito tempo livre."],"bkA2-250":["Há bons hotéis perto da praia?"],"bkA2-251":["Quantas pessoas trabalham no seu escritório?"],"bkA2-252":["Não sobrou muita comida na cozinha."],"bkA2-253":["A: Vamos fazer um bolo para o aniversário da Dani. Temos farinha?","B: Temos, temos bastante farinha.","A: Ótimo. Quantos ovos precisamos?","B: Quatro. Mas só temos dois.","A: Tudo bem, vou comprar alguns."],"bkA2-254":["Vila Nova é um vilarejo pequeno nas montanhas. Há só algumas casas e não há hospital. Há muitas vacas e cavalos, mas não há muitos carros. No inverno, cai um pouco de neve, e muitos turistas vêm vê-la."],"bkA2-255":["Oi, Beto, você pode ir ao mercado? Precisamos de muita coisa para o churrasco de domingo. Por favor, compre dois quilos de carne e algumas linguiças. Não precisamos de pão; comprei ontem. Temos só um pouco de carvão, então compre um saco. E não compre bebida demais, porque a Carla vai trazer. Obrigada! Vera"],"bkA2-256":["Precisamos de uns ovos para o bolo., Tem um pouco de leite na geladeira., Comprei umas maçãs na feira., Você aceita um chá?","Não temos nenhum pão., Ela não comprou nenhum sapato., Não há ônibus nenhum hoje., Não preciso de ajuda nenhuma, obrigado."],"bkA2-257":["Quanto custa? / Vinte reais.","Quantos filhos você tem? / Dois, um menino e uma menina.","Sobrou café? / Só um pouquinho. Vou fazer mais.","Você tem cadeiras suficientes? / Não, precisamos de mais três."],"bkA2-259":["Há gente demais neste ônibus. Vamos esperar o próximo."],"bkA2-260":["A: Com que frequência você visita seus avós? B: Uma vez por mês."],"bkA2-261":["Meu chefe nunca se atrasa para as reuniões."],"bkA2-262":["Raramente vou ao dentista, talvez uma vez a cada dois anos."],"bkA2-263":["A: Você come sushi de vez em quando?","B: Sim, geralmente como às sextas com minha equipe. Mas nunca faço em casa. É muito difícil!"],"bkA2-264":["Oi! Sou a Joana e trabalho numa padaria. Eu sempre começo a trabalhar às 5h, todos os dias. Às vezes tomo um café às 9h, cerca de duas vezes por semana. Raramente tiro um dia de folga; só tive dois dias de folga no ano passado. E nunca como o pão que eu faço, porque não gosto de pão!"],"bkA2-265":["Você joga videogame de vez em quando? Não, eu nunca jogo."],"bkA2-266":["Ela nunca consegue lembrar meu aniversário. Às vezes vou a pé para o trabalho."],"bkA2-267":["O Rodrigo está sempre feliz de manhã."],"bkA2-268":["Eu nunca tomo refrigerante."],"bkA2-269":["A Carla geralmente vai à academia."],"bkA2-270":["Com que frequência o Leo joga tênis?"],"bkA2-271":["Meus pais às vezes assistem a filmes nas tardes de domingo."],"bkA2-272":["Nós nunca estamos em casa nas manhãs de sábado."],"bkA2-273":["A: Você costuma cozinhar em casa?","B: Nem tanto. Geralmente almoço no escritório.","A: E o jantar?","B: Às vezes faço macarrão, mas muitas vezes peço comida."],"bkA2-274":["Gustavo é taxista no Rio. Ele geralmente trabalha das 6h às 16h. Muitas vezes almoça no carro. Nunca trabalha aos domingos porque vai à igreja com a família. Às vezes joga futebol na praia à noite."],"bkA2-275":["Perguntamos a 100 alunos da nossa escola sobre seus hábitos. Noventa alunos sempre usam o celular antes de dormir. Sessenta alunos geralmente tomam café da manhã em casa. Só 15 alunos costumam ler livros por prazer, e 5 alunos nunca fazem o dever de casa! A maioria dos alunos às vezes pratica esportes no fim de semana."],"bkA2-277":["Com que frequência você vai ao cinema? / Cerca de uma vez por mês.","Você chega atrasado ao trabalho de vez em quando? / Quase nunca. Sou muito pontual.","Você sempre vai a pé para a escola? / Não, às vezes pego o ônibus.","Com que frequência sua avó liga para você? / Quase todo dia. Ela sente saudade de mim!"],"bkA2-279":["A: Você toma café da manhã? B: Tomo, todo dia. Nunca pulo."],"bkA2-280":["Este é o carro do meu pai. Ele o comprou no ano passado."],"bkA2-281":["O banheiro feminino fica à esquerda, ao lado da escada."],"bkA2-282":["A: De quem é este guarda-chuva? B: É da Tânia."],"bkA2-283":["A: Qual é o nome desta rua?","B: Rua das Flores. A casa da minha avó fica no fim da rua."],"bkA2-284":["Olhe esta foto do casamento da minha tia. A mulher de vestido branco é minha tia Rita. O homem alto ao lado dela é o marido dela, meu tio Paulo. A menina com eles é a filha deles, a Bia. Então a Bia é minha prima!"],"bkA2-285":["Os brinquedos das crianças estão espalhados pelo chão."],"bkA2-286":["De quem são estas chaves? Acho que são do meu irmão."],"bkA2-287":["O vestido da Ana é lindo."],"bkA2-288":["Ficamos na casa do meu amigo em Belém."],"bkA2-289":["É o cachorro da Carolina."],"bkA2-290":["De quem é este celular?"],"bkA2-291":["A mãe do meu melhor amigo é enfermeira."],"bkA2-292":["Jantamos na casa do Rafael ontem à noite."],"bkA2-293":["A: Com licença, perdi minha mochila ontem.","B: De que cor ela é?","A: É verde, com uma bandeirinha do Brasil.","B: É esta aqui? Estava na sala dos professores.","A: Sim, é minha! Obrigado!"],"bkA2-294":["Hoje é aniversário do Lucas. A festa é na chácara dos avós dele. A mãe do Lucas fez o bolo, e a banda do tio dele vai tocar. O melhor amigo do Lucas, o Téo, não pode vir porque está doente."],"bkA2-295":["O Pet Shop da Maria fica na Rua Sete, ao lado da clínica odontológica do Dr. Kato. Abre de segunda a sábado. O filho da Maria, o Felipe, dá banho nos cachorros. Aos sábados, as crianças podem trazer brinquedos de pet antigos e trocá-los por novos. O telefone da loja é 3222-1010."],"bkA2-297":["Ana é a / esposa do Leo.","Leo é o / marido da Ana.","Rosa é a / filha da Ana e do Leo.","Ana é a / mãe da Rosa."],"bkA2-299":["A: Onde está o Bruno? B: Está no dentista. Está com dor de dente."],"bkA2-300":["A: Com licença, onde fica o caixa eletrônico mais próximo? B: Fica na esquina, ao lado da padaria."],"bkA2-301":["Atravesse a ponte e vire à direita."],"bkA2-302":["A farmácia fica em frente ao banco. Basta atravessar a rua."],"bkA2-303":["A: Com licença. Onde fica a estação de trem?","B: Não é longe daqui. Desça esta rua e vire à esquerda na igreja."],"bkA2-304":["Para chegar ao Pelourinho a partir do hotel, ande pela Avenida Sete por cerca de cinco minutos. Pegue a segunda rua à direita. Passe por uma igreja grande e você verá uma praça. O restaurante fica na praça, entre uma loja de souvenirs e um banco."],"bkA2-305":["Siga em frente e pegue a primeira à esquerda."],"bkA2-306":["O café fica em frente ao museu, no fim da rua."],"bkA2-307":["Vire à esquerda no supermercado."],"bkA2-308":["Os Correios ficam entre o banco e a academia."],"bkA2-309":["Vire à direita no semáforo."],"bkA2-310":["O banco fica à direita da padaria."],"bkA2-311":["Como chego ao aeroporto daqui?"],"bkA2-312":["O ponto de ônibus fica em frente ao hospital."],"bkA2-313":["A: Com licença, o shopping fica longe daqui?","B: Não, são uns cinco minutos a pé.","A: Ótimo. Por onde eu vou?","B: Desça esta rua e vire à direita no posto de gasolina.","A: Muito obrigado!","B: De nada."],"bkA2-314":["Bem-vindo ao Colégio Estrela! Ao entrar, a secretaria fica à sua direita. A biblioteca fica no segundo andar, ao lado da sala de informática. A cantina fica no fim do corredor, em frente à quadra. Os banheiros ficam perto da escada."],"bkA2-315":["Oi, Nando! A festa é no meu apartamento novo. Desça do metrô na estação Consolação. Suba a Rua Augusta por dois quarteirões e vire à esquerda na Rua Luís Coelho. Meu prédio é o terceiro à direita, em frente a uma pracinha. É cinza com a porta vermelha. Moro no 7º andar, apartamento 72. Até às oito! Bia"],"bkA2-317":["É longe? / Não, é bem perto.","Posso ir a pé? / Pode, são só dois quarteirões.","Onde fica exatamente? / Fica entre o banco e a padaria.","Quanto tempo leva? / Cerca de dez minutos."],"bkA2-319":["Passe pelo túnel e você verá o estádio à sua esquerda."],"bkA2-320":["Eu queria ir ao show, mas os ingressos esgotaram."],"bkA2-321":["A Mariana está aprendendo japonês porque quer trabalhar em Tóquio."],"bkA2-322":["Anda logo, senão vamos perder o ônibus!"],"bkA2-323":["A: Você quer sair ou ficar em casa hoje à noite?","B: Vamos ficar em casa. Não quero sair porque está chovendo."],"bkA2-324":["Ontem foi um dia corrido. Primeiro, fui ao banco. Depois, almocei com meu amigo Rui. Então fui à academia, mas estava muito cansado, então voltei para casa cedo."],"bkA2-325":["Era meu aniversário, então meus amigos fizeram um bolo e cantamos juntos."],"bkA2-326":["O Rafa gosta de rock e pop, mas não gosta de funk."],"bkA2-327":["Ela estava cansada, então foi dormir cedo."],"bkA2-328":["Podemos pegar o ônibus ou ir a pé. Qual você prefere?"],"bkA2-329":["O hotel era lindo, mas era muito caro."],"bkA2-330":["A Paula se atrasou porque perdeu o ônibus."],"bkA2-331":["Liguei para o Pedro, mas ele não atendeu."],"bkA2-332":["Você prefere a praia ou a serra?"],"bkA2-333":["A: Por que você está tão feliz hoje?","B: Porque passei na prova de direção!","A: Parabéns! Foi difícil?","B: Foi, mas eu pratiquei muito."],"bkA2-334":["Júlio e Camila abriram um restaurante pequeno em Belém no ano passado. No início, tinham só alguns clientes, então o Júlio criou uma página no Instagram. Agora o restaurante vive cheio, mas eles estão muito cansados porque trabalham todo dia. No ano que vem, querem contratar mais dois cozinheiros."],"bkA2-335":["No domingo passado, o Tiago quis ir pescar com o pai. Primeiro, eles prepararam uns sanduíches e bebidas. Depois foram de carro até um lago perto de Goiânia. Esperaram três horas, mas não pescaram nenhum peixe. Então comeram os sanduíches e foram nadar. Por fim, compraram um peixe na feira no caminho de casa!"],"bkA2-337":["Estava calor, / então fomos à praia.","Você quer suco / ou água?","Gosto de suco, / mas não gosto de refrigerante.","Bebi um pouco de água / porque estava com sede."],"bkA2-339":["Eu não tinha guarda-chuva, então me molhei."],"bkA2-340":["Preciso de dinheiro para comprar os ingressos."],"bkA2-341":["Quantas garrafas de água precisamos para a viagem?"],"bkA2-342":["As notícias de hoje são muito boas!"],"bkA2-343":["A: Pode me trazer um copo de água e um sanduíche, por favor?","B: Claro. Você quer gelo na água?"],"bkA2-344":["Na minha cozinha tem um forno, uma mesa grande e alguns móveis antigos da minha avó. Eu sempre tenho frutas numa fruteira e pão para o café da manhã."],"bkA2-345":["Você pode me dar uma ajuda com o meu dever de casa? É um exercício difícil."],"bkA2-346":["Há muito arroz no saco."],"bkA2-347":["Preciso comprar móveis novos para o meu apartamento."],"bkA2-348":["Você pode me dar algumas informações sobre o passeio?"],"bkA2-349":["Quantos primos a Rita tem?"],"bkA2-350":["Ela me deu dois conselhos."],"bkA2-351":["Você gostaria de uma xícara de chá?"],"bkA2-352":["Não temos muitos móveis na nossa casa nova."],"bkA2-353":["A: O que precisamos para a lasanha?","B: Um pouco de queijo, uns tomates e uma cebola.","A: Quanto queijo?","B: Mais ou menos meio quilo.","A: Certo. E quantos tomates?","B: Cinco ou seis grandes."],"bkA2-354":["Oi, sou a Débora. Vou me mudar para um apartamento novo na semana que vem. Tenho muitos móveis, então preciso de um caminhão grande. Não tenho muito dinheiro, mas meus amigos vão me ajudar de graça. Também tenho três caixas de livros e muitos utensílios de cozinha."],"bkA2-355":["Vai viajar pela Air Sol? Por favor, leia. Você pode levar uma bagagem de mão. Líquidos devem estar em frascos pequenos (máximo de 100 ml). Você não pode trazer alimentos frescos de outros países para o Brasil, como frutas ou queijo. Por favor, chegue com duas horas de antecedência. Boa viagem!"],"bkA2-357":["uma fatia de / pizza","uma tigela de / cereal","uma lata de / refrigerante","um conselho / conselho"],"bkA2-359":["Havia muito trânsito no caminho para o trabalho hoje de manhã."],"bkA2-1001":["Às nove horas da noite passada, eu estava lendo um livro."],"bkA2-1002":["Enquanto almoçávamos, começou a chover."],"bkA2-1003":["A: O que você estava fazendo às sete da noite passada?","B: Eu estava cozinhando, e meu irmão estava assistindo TV.","A: Seus pais estavam ajudando você?","B: Não, não estavam. Eles estavam no mercado."],"bkA2-1004":["Ela estava assistindo a um filme quando eu liguei."],"bkA2-1005":["Eu caí quando estava correndo para pegar o ônibus."],"bkA2-1006":["Eles estavam jogando futebol no parque."],"bkA2-1007":["Eu sabia a resposta, mas não disse nada."],"bkA2-1008":["Ela não estava lendo uma revista."],"bkA2-1009":["Eles estavam esperando o ônibus?"],"bkA2-1010":["Eu estava tomando banho quando o telefone tocou."],"bkA2-1011":["No sábado passado, o Leo estava voltando do trabalho a pé quando começou a chover. Ele não tinha guarda-chuva, então correu para um café pequeno. Lá dentro, a amiga dele, a Mia, estava tomando café e lendo o jornal. Eles conversaram por uma hora."],"bkA2-1012":["Você estava dormindo? / Não, não estava.","O que ele estava fazendo? / Estava fazendo o almoço.","Aonde eles estavam indo? / Estavam indo para a escola.","Estava chovendo? / Sim, estava."],"bkA2-1013":["Meu pai estava nos levando para casa quando a tempestade começou."],"bkA2-1014":["A: O que você estava fazendo às nove da noite passada?","B: Eu estava estudando para a prova de inglês.","A: Sério? Eu liguei, mas você não atendeu.","B: Desculpe, meu celular estava na bolsa."],"bkA2-1015":["A Ana canta muito bonito."],"bkA2-1016":["A aula estava chata, então quase peguei no sono."],"bkA2-1017":["O Pedro é um motorista cuidadoso. Ele dirige com cuidado e sempre chega em segurança."],"bkA2-1018":["Ela fala inglês bem, e a pronúncia dela é perfeita."],"bkA2-1019":["Mal o conheço, mas ele trabalha duro todo dia."],"bkA2-1020":["Ela fala inglês bem."],"bkA2-1021":["Minha irmã tem um carro vermelho."],"bkA2-1022":["Ela aprende rápido."],"bkA2-1023":["Ele dança bem."],"bkA2-1024":["Comprei uma linda mesa antiga."],"bkA2-1025":["Na semana passada, o Diego visitou um pequeno restaurante italiano perto da casa dele. O garçom era muito simpático e falava educadamente com todo mundo. O macarrão estava delicioso, mas a música estava alta demais, então o Diego não conseguiu conversar com facilidade com o amigo. Ele saiu cedo e voltou para casa devagar."],"bkA2-1026":["fácil / facilmente","bom / bem","rápido / rapidamente","gentil / gentilmente"],"bkA2-1028":["As crianças brincaram felizes no jardim."],"bkA2-1029":["A mala é pesada demais para eu carregar."],"bkA2-1030":["A: Vamos comprar este sofá.","B: É grande demais para a nossa sala.","A: Mas é macio e bonito.","B: É, mas é caro demais para nós, e a sala não é grande o suficiente."],"bkA2-1031":["Não beba esse chá. Está quente demais e tem açúcar demais."],"bkA2-1032":["Não consigo dormir porque há barulho demais na rua."],"bkA2-1033":["Não temos cadeiras suficientes."],"bkA2-1034":["Meu irmão não tem idade suficiente para dirigir."],"bkA2-1035":["No fim de semana passado, o Rui e os amigos foram à praia. O sol estava forte, mas a água estava fria demais para nadar. Eles não tinham cadeiras suficientes, então sentaram em toalhas. Havia gente demais perto da lanchonete, então comeram sanduíches no carro."],"bkA2-1036":["A bicicleta é cara demais para o Marcos comprar."],"bkA2-1037":["Não posso comprar esta jaqueta. / É cara demais.","Não podemos sentar todos. / Não há cadeiras suficientes.","Não consigo dormir. / Há barulho demais.","As crianças não podem ir no brinquedo. / Elas não são altas o suficiente."],"bkA2-1039":["Ela é nova demais para assistir a este filme. É para adultos."],"bkA2-1040":["Ele é alto o suficiente para alcançar a prateleira, e compramos maçãs suficientes para a festa."],"bkA2-1041":["A água não está quente o suficiente para nadar."],"bkA2-1042":["O chá está quente demais para beber."],"bkA2-1043":["O gato está escondido atrás do sofá, então não consigo vê-lo."],"bkA2-1044":["A: Com licença, onde fica o correio?","B: Desça esta rua e passe pelo banco. O correio fica em frente ao parque, entre a farmácia e a escola."],"bkA2-1045":["Estou no supermercado agora. Mais tarde, vou ao banco."],"bkA2-1046":["Fomos para casa depois do filme."],"bkA2-1047":["Ele saiu da loja."],"bkA2-1048":["Passe pela igreja e vire à esquerda."],"bkA2-1049":["O apartamento da Mia fica na Rua dos Carvalhos. Fica entre uma padaria e uma floricultura. Em frente ao prédio há uma pracinha. Toda manhã a Mia atravessa a praça até o ponto de ônibus, e depois do trabalho vai direto para casa."],"bkA2-1050":["across / de um lado ao outro","through / por dentro de","along / ao longo de","past / passando por"],"bkA2-1052":["Tenha cuidado ao atravessar a rua. Olhe para os dois lados."],"bkA2-1053":["Ela tirou as chaves da bolsa, e o cachorro pulou no sofá."],"bkA2-1054":["O cachorro saiu correndo de casa quando abri a porta."],"bkA2-1055":["Atravessamos o túnel de carro e saímos do outro lado."],"bkA2-1056":["O ponto de ônibus fica atrás da biblioteca."],"bkA2-2001":["Posso me sentar aqui, por favor?"],"bkA2-2002":["Qual frase é a mais formal? → Posso abrir a janela, por favor?"],"bkA2-2003":["A: Bom dia. Posso ajudar?","B: Sim. Poderia me mostrar aquela bolsa azul, por favor?","A: Claro. Gostaria de ver a vermelha também?","B: Sim, por favor.","A: Você se importaria de esperar um minuto? Vou buscá-la.","B: Sem problema."],"bkA2-2004":["A: Você gostaria de um pouco de água?","B: Sim, por favor. Obrigado.","A: Quer que eu traga um copo para você?","B: Claro. E você se importaria de abrir a janela?"],"bkA2-2005":["Você poderia me ajudar com este exercício, por favor?"],"bkA2-2006":["Gostaria que eu carregasse sua bolsa?"],"bkA2-2007":["Você poderia me dar o cardápio?"],"bkA2-2008":["Posso usar seu telefone?"],"bkA2-2009":["Você se importaria de fechar a janela?"],"bkA2-2010":["Ana está na casa do amigo Paulo. Ela está com sede. \"Posso tomar um pouco de água, por favor?\", ela pergunta. \"Claro\", diz Paulo. \"Quer gelo?\" \"Não, obrigada.\" Então Ana vê a TV. \"Posso ligá-la?\" \"Desculpe, não pode. Meu irmãozinho está dormindo\", diz Paulo. \"Que tal ouvir música?\" \"Boa ideia!\""],"bkA2-2011":["Posso pegar sua caneta emprestada? / Claro, aqui está.","Quer que eu abra a janela? / Sim, por favor. Está quente aqui.","Por que não assistimos a um filme? / Boa ideia! Adoro comédias.","Você se importaria de esperar um minuto? / Não, de jeito nenhum."],"bkA2-2012":["A: Com licença. Poderia me dizer as horas, por favor?","B: Claro. São dez e meia.","A: Muito obrigado.","B: Sem problema."],"bkA2-2014":["Que tal irmos ao parque no domingo?"],"bkA2-2015":["A: Você gosta de filmes de terror? B: Gosto, sim."],"bkA2-2016":["A: Eu nado muito bem. B: Eu também!"],"bkA2-2017":["A: Estou com fome.","B: Eu também.","A: Você também está cansado?","B: Não, não estou."],"bkA2-2018":["A: Não gosto de tempo frio.","B: Nem eu.","A: Adoro o verão.","B: Sério? Eu não. É quente demais."],"bkA2-2019":["A: Adoro pizza. B: Eu também.","A: Não sei nadar. B: Nem eu."],"bkA2-2020":["A: Você ligou para a Marta? B: Sim, liguei.","Minha irmã não gosta de chá, e eu também não."],"bkA2-2021":["Você é de Recife? Sou, sim."],"bkA2-2022":["Eu também."],"bkA2-2023":["Nem eu."],"bkA2-2024":["Meu irmão também."],"bkA2-2025":["Bia: Adoro fazer trilha. Leo: Eu também! Não gosto de praia. Bia: Nem eu. Não sei nadar. Leo: Nem eu!"],"bkA2-2026":["Estou tão cansado. / Eu também.","Não gosto de cebola. / Nem eu.","Não sei dirigir. / Nem eu.","Ainda não terminei. / Nem eu."],"bkA2-2027":["A: Estou aprendendo espanhol.","B: Está? É difícil?","A: Um pouco. Não consigo falar muito rápido.","B: Nem eu. Também estou aprendendo."],"bkA2-2028":["A: Eu não assisti ao jogo ontem à noite. B: Nem eu."],"bkA2-2029":["Qual frase tem a pontuação correta? → Gosto do hotel. No entanto, ele é caro."],"bkA2-2030":["Qual frase está escrita corretamente? → Hoje é aniversário do meu irmão."],"bkA2-2032":["Temos uma reunião na segunda-feira, e meu chefe fala português."],"bkA2-2033":["Está um dia bonito, e o cachorro está balançando o rabo."],"bkA2-2034":["Está chovendo hoje, então vamos ficar em casa."],"bkA2-2035":["O gato está lambendo a pata."],"bkA2-2037":["Oi, sou o Tom. Moro em Chicago, mas minha família é do México. Às sextas, ensino espanhol e inglês numa escola. Em julho, visito meus pais na Cidade do México."],"bkA2-2038":["Posse / Carla's bag","Contração de it is / It's cold today.","Fala citada / He said, \"Good morning.\"","Lista de itens / I need eggs, milk, and rice."],"bkA2-2039":["Meu cachorro adora a cama nova dele. Ela é muito macia."],"bkA2-2040":["Oi, Marcos, Sou a Ana, sua nova colega de Lisboa. Chego na terça e quero visitar o Rio em março. Quando chegar, ligo para você. No entanto, meu inglês não é perfeito, então fale devagar, por favor. Obrigada!"],"bkA2-2041":["Meu amigo Lucas fala francês e alemão."],"bkA2-2042":["A: Oi! Sou a Karen. Qual é o seu nome?","B: Sou o Paulo. Prazer em conhecê-la!","A: Prazer também. De onde você é?","B: Sou do Brasil e falo português."],"bkA2-2043":["Este é o celular do meu irmão."],"bkA2-2044":["Pode me trazer mais uma xícara de café, por favor?"],"bkA2-2045":["Alguns alunos gostam de matemática, mas outros preferem artes."],"bkA2-2046":["Você gostaria de mais alguma coisa?"],"bkA2-2047":["Tenho dois celulares. Um é para o trabalho, e o outro é para casa.","Ela não está pronta, então precisa de mais duas horas."],"bkA2-2048":["Não gosto desta camisa. Posso ver outra?","Algumas pessoas adoram chuva, outras odeiam.","Onde estão as outras crianças?"],"bkA2-2049":["Gosto desta música, mas não gosto das outras."],"bkA2-2050":["Não consigo achar minhas chaves. Você tem outra?"],"bkA2-2051":["Posso tomar mais um copo de água?"],"bkA2-2052":["Algumas pessoas gostam de jazz, mas outras preferem rock."],"bkA2-2053":["A: Posso ajudar?","B: Sim, gosto destes sapatos, mas são pequenos demais.","A: Gostaria de experimentar outro tamanho?","B: Sim, por favor. Tamanho 8."],"bkA2-2054":["Maria tem dois empregos. De manhã, trabalha num banco. À noite, dá aulas de inglês. Alguns dos alunos dela são crianças, e outros são adultos. Ela quer outro emprego nos fins de semana, mas o marido diz que não."],"bkA2-2055":["Oi, Paulo! Estou em São Paulo com a Carla e as amigas dela. Duas das amigas adoram museus, então visitaram o MASP hoje. As outras queriam fazer compras, então foram a um shopping. Amanhã temos outro dia cheio. Carla e eu queremos ver o parque, e as outras querem ir a um show. Até breve! Ana"],"bkA2-2057":["Tenho uma caneta aqui, e / a outra está na minha bolsa.","Algumas crianças jogam futebol, / outras jogam videogame.","Este celular é velho. Quero / outro.","Há dez jogadores. Cinco estão aqui, e / os outros estão atrasados.","Não quero esta cor. Você tem / outras cores?"],"bkA2-2058":["Maria e João conversam um com o outro todo dia."],"bkA2-2059":["Esta pizza é ruim, mas aquela é ainda pior."],"bkA2-2060":["O Monte Everest é a montanha mais alta do mundo."],"bkA2-2062":["A bolsa do Lucas é mais pesada do que a minha, então a minha é mais leve do que a dele."],"bkA2-2063":["Meu irmão é mais alto do que eu. Ele é o menino mais alto da turma."],"bkA2-2064":["Ela é a melhor aluna. Meu inglês está melhor do que antes."],"bkA2-2065":["Esta bolsa é mais barata do que aquela."],"bkA2-2066":["O Tom é mais alto do que o irmão."],"bkA2-2067":["Salvador é menor do que o Rio."],"bkA2-2068":["O carro azul é mais barato do que o vermelho."],"bkA2-2069":["Este é o livro mais interessante da biblioteca."],"bkA2-2070":["A: Com licença, quanto custa este notebook?","B: Custa 900 dólares.","A: É caro. Você tem um mais barato?","B: Tenho, este é mais barato. Custa 600 dólares.","A: Ótimo, vou levar."],"bkA2-2071":["Ana tem 25 anos. O irmão dela, Davi, tem 30, então ele é mais velho que a Ana. A Ana é mais alta que o Davi, mas o Davi é mais forte. A irmã deles, a Lia, é a mais nova. Ela tem 20 anos e é a mais baixa da família."],"bkA2-2072":["Procurando hotel em Fortaleza? O Hotel Sol é mais barato do que o Hotel Mar, mas é menor e fica mais longe da praia. O Hotel Mar é o hotel mais caro da cidade e tem a maior piscina. O Hotel Sol também é menos moderno do que o Hotel Mar. Os dois hotéis têm café da manhã grátis."],"bkA2-2074":["maior / menor","mais alto / mais baixo","mais rápido / mais lento","mais quente / mais frio"],"bkA2-2075":["Recife fica mais longe de Porto Alegre do que Salvador."],"bkB1-0":["Já fomos a Salvador três vezes até agora."],"bkB1-1":["Meus pais se casaram em 1998."],"bkB1-2":["A: Você já provou açaí?","B: Já, provei no verão passado em Belém. Estava delicioso."],"bkB1-3":["A Carla mora em Recife desde 2019. Antes disso, ela morou em Natal por dois anos."],"bkB1-4":["Eu vi aquele filme no fim de semana passado."],"bkB1-5":["O Paulo mora em Curitiba desde 2020."],"bkB1-6":["Você já foi à Amazônia?"],"bkB1-7":["Conheço o Pedro / desde que éramos crianças.","Nos conhecemos / numa festa em 2012.","Eles já / terminaram o projeto.","Você viu / o jogo ontem à noite?"],"bkB1-9":["Lucas é um fotógrafo de Florianópolis. Ele já viajou para doze países até agora. Sua primeira viagem ao exterior foi para a Argentina, em 2014. Ele nunca foi à Ásia, mas quer visitar o Japão no ano que vem. No mês passado, foi ao Chile para um casamento."],"bkB1-10":["Se eu tivesse mais tempo livre, aprenderia a tocar violão."],"bkB1-11":["Se chover amanhã, vamos cancelar o churrasco."],"bkB1-12":["Se eu fosse você, conversaria com o gerente sobre o problema."],"bkB1-13":["Se ela estudar bastante, vai passar na prova na semana que vem."],"bkB1-14":["Se eu tivesse um carro, iria de carro para o trabalho."],"bkB1-15":["Se eu tivesse dinheiro, poderia comprar um celular novo."],"bkB1-16":["O que você faria se ganhasse na loteria?"],"bkB1-17":["Se você apertar este botão, / a máquina liga.","Se eu encontrar a Marta amanhã, / dou a ela o seu recado.","Se morássemos perto da praia, / iríamos surfar todo dia.","Se você não dorme o suficiente, / você se sente cansado."],"bkB1-19":["Oi, Bruno, Obrigada por me convidar para a sua festa no sábado! Se eu sair cedo do trabalho, com certeza vou. Se sair tarde, pelo menos passo aí para a sobremesa. A propósito, se eu tivesse carro, daria carona para a Júlia, mas o meu está na oficina. Se precisar de alguma coisa para a festa, é só me mandar mensagem. Até logo, Tati"],"bkB1-20":["Eu gosto muito de caminhar na chuva."],"bkB1-21":["Eles decidiram comprar uma casa em Campinas."],"bkB1-22":["Minha irmã Bia está tentando ter uma vida mais saudável. Ela quer comer mais legumes e parou de tomar refrigerante. Também evita comer fast food. No mês que vem, planeja entrar numa aula de ioga e espera dormir melhor à noite."],"bkB1-23":["Estou ansioso para ver você e prometo chegar na hora."],"bkB1-24":["Você se importaria de fechar a janela?"],"bkB1-25":["É divertido aprender um novo idioma."],"bkB1-26":["Ela parou de comer carne há dois anos."],"bkB1-27":["Sinto falta de / morar perto dos meus avós.","Terminamos de / pintar a cozinha às 18h.","Ele se recusou a / responder às perguntas do repórter.","Você está com vontade de / sair hoje à noite?"],"bkB1-29":["A: Você quer ir ao cinema hoje à noite?","B: Eu adoraria, mas preciso estudar para a prova.","A: Ah, vamos lá! Você não pode ficar estudando o dia todo.","B: Você tem razão. A que horas começa o filme?","A: Às oito. Eu compro os ingressos."],"bkB1-30":["Esta ponte foi construída em 1974."],"bkB1-31":["O inglês é falado em muitos países do mundo."],"bkB1-32":["A estátua do Cristo Redentor foi concluída em 1931. Hoje, ela é visitada por milhões de turistas todos os anos."],"bkB1-33":["Os e-mails foram enviados ontem, e o relatório está sendo escrito agora."],"bkB1-34":["O pacote foi entregue esta manhã."],"bkB1-35":["Minha bicicleta foi roubada ontem à noite."],"bkB1-36":["Estes sapatos são feitos em Franca."],"bkB1-37":["Os resultados serão anunciados na próxima sexta."],"bkB1-39":["As primeiras mudas de café foram trazidas para o Brasil da Guiana Francesa em 1727. Hoje, o Brasil é o maior produtor de café do mundo. A maior parte do café é cultivada em Minas Gerais, São Paulo e Espírito Santo. Grande parte dele é exportada para os Estados Unidos e a Europa."],"bkB1-40":["A mulher que mora ao lado é médica."],"bkB1-41":["Esse é o restaurante onde tivemos nosso primeiro encontro."],"bkB1-42":["Tenho um amigo cujo pai é piloto. Ele mora numa cidade onde não há semáforos."],"bkB1-43":["O livro que você me emprestou era ótimo, e o autor, que é da Bahia, é muito famoso."],"bkB1-44":["Este é o homem que me ajudou no aeroporto."],"bkB1-45":["Conheci uma menina que fala cinco idiomas."],"bkB1-46":["O celular que comprei semana passada está quebrado."],"bkB1-47":["Um chef é uma pessoa / que cozinha num restaurante.","Uma padaria é um lugar / onde você compra pão.","Uma chave é uma coisa / que abre uma porta.","Um órfão é uma criança / cujos pais morreram."],"bkB1-48":["um professor que explica bem, meu primo que toca numa banda","uma máquina que faz café, o filme que ganhou o Oscar","a cidade onde nasci, o hotel onde ficamos"],"bkB1-49":["PRECISA-SE: AUXILIAR DE FIM DE SEMANA A Casa Verde é uma loja de plantas familiar que funciona em Porto Alegre desde 1990. Procuramos alguém que ame plantas e goste de conversar com os clientes. A pessoa que for contratada trabalhará aos sábados e domingos. Candidatos cujo espanhol seja bom terão vantagem, porque muitos de nossos clientes vêm do Uruguai. Envie seu currículo para o e-mail abaixo."],"bkB1-50":["Você é de Manaus, não é?"],"bkB1-51":["Ela não ligou para você, ligou?"],"bkB1-52":["A: Está um dia lindo, não está?","B: Está sim! Você nunca esteve neste parque, esteve?","A: Não, nunca. Podemos voltar semana que vem, não podemos?"],"bkB1-53":["Vamos pedir pizza, que tal? Você gosta de calabresa, não gosta?"],"bkB1-54":["Ele sabe nadar, não sabe?"],"bkB1-55":["Eles moram em Belo Horizonte, não moram?"],"bkB1-56":["Estou atrasado, / não estou?","Ninguém ligou, / ligou?","O Tom tem um cachorro, / não tem?","Não esqueça os ingressos, / tá?"],"bkB1-59":["A: Você é o novo designer, não é?","B: Sou sim. Comecei na segunda.","A: Bem-vindo! Você ainda não conheceu a chefe, conheceu?","B: Ainda não. Ela está no escritório hoje?","A: Está sim. Vou apresentar vocês."],"bkB1-60":["Ele está trabalhando há 14 horas. Deve estar exausto."],"bkB1-61":["Quando eu era criança, costumava jogar videogame toda tarde."],"bkB1-62":["Não pode ser a Ana na porta. Ela está em Londres esta semana! Deve ser o entregador. Pedi uma pizza e não estou esperando mais ninguém."],"bkB1-63":["Meu avô trabalhava numa fazenda, mas não gostava."],"bkB1-64":["Você morava em Salvador?"],"bkB1-65":["Ela deve estar em casa."],"bkB1-66":["Nós costumávamos acampar todo verão."],"bkB1-67":["O carro dele está lá fora, então / ele deve estar em casa.","Ela tem só 12 anos, então / não pode ser a nova gerente.","Eles moravam no Rio, então / devem conhecer bem a cidade.","Você não dormiu ontem à noite, então / deve estar cansado."],"bkB1-68":["Ele ganhou na loteria. Deve estar rico., Eles andaram o dia todo. Devem estar cansados., O restaurante vive cheio. A comida deve ser boa.","Faz 40°C lá fora. Você não pode estar com frio., Ela acabou de almoçar muito. Não pode estar com fome., Ele não tem carro. Esse não pode ser o carro dele."],"bkB1-69":["Quando o Rafael era adolescente, ele morava numa cidadezinha em Goiás. Ele ia de bicicleta para a escola e não tinha celular. Agora mora em São Paulo e trabalha num escritório. Tem pouco tempo livre e sente falta da vida tranquila que tinha."],"bkB1-70":["Você pode me fazer um favor?"],"bkB1-71":["Fique quieto! Não faça tanto barulho."],"bkB1-72":["Nas manhãs de sábado, eu faço o serviço de casa. Primeiro, arrumo a cama. Depois lavo a louça e faço o café da manhã para meus filhos. À tarde, faço exercícios no parque."],"bkB1-73":["Preciso fazer meu dever de casa antes de dar um telefonema."],"bkB1-74":["Meu irmão ganhou muito dinheiro vendendo carros."],"bkB1-77":["Ainda não estou pronto para tomar / uma decisão.","Você poderia lavar / a louça hoje à noite?","Ele sempre faz / o melhor que pode no trabalho.","Pare de tirar / sarro da sua irmã!"],"bkB1-78":["Você fez algum plano para o fim de semana?"],"bkB1-79":["Oi, Marina! Fiz uma lista das coisas que precisamos fazer antes da festa. Você pode fazer as compras na sexta? Eu faço o bolo e os salgadinhos. O Pedro disse que faria uma playlist, mas está fazendo hora extra no trabalho, então pode se atrasar. Por favor, não faça barulho quando chegar. A vovó vai estar dormindo! Beijos, Clara"],"bkB1-80":["Fui à farmácia comprar um remédio."],"bkB1-81":["Esta faca serve para cortar pão."],"bkB1-82":["Comprei flores para minha mãe. Dei a ela no domingo."],"bkB1-83":["Esperamos o ônibus por quarenta minutos."],"bkB1-84":["Vim para o Canadá para aprender inglês."],"bkB1-85":["Fui ao banco para abrir uma conta."],"bkB1-86":["Este presente é para mim ou para a sua irmã?"],"bkB1-87":["Obrigado / pela sua ajuda.","Ela se mudou para Lisboa / para estudar design.","Esta sala é / só para hóspedes.","Ele explicou a regra / aos novos alunos."],"bkB1-88":["ouvir música, falar com o seu chefe, pertencer a alguém","esperar alguém, procurar suas chaves, pagar pelos ingressos"],"bkB1-89":["Toda manhã, a Júlia vai à padaria comprar pão fresco para a família. Aos sábados, compra um bolo de chocolate para o filho, o Theo. Na semana passada, ela também comprou um cartão para a professora do Theo e o entregou a ela no último dia de aula. Theo escreveu uma mensagem de agradecimento dentro do cartão."],"bkB1-90":["Embora estivesse chovendo, fomos dar uma caminhada."],"bkB1-91":["O hotel era caro. Além disso, o atendimento foi terrível."],"bkB1-92":["Eu queria estudar no exterior no ano passado. No entanto, não tinha dinheiro suficiente, então arranjei um emprego de meio período. Apesar de trabalhar muitas horas, continuei estudando inglês toda noite. Meu irmão adora cidades grandes, enquanto eu prefiro lugares tranquilos, então escolhi uma cidade pequena na Irlanda. Vou no ano que vem, a menos que algo inesperado aconteça."],"bkB1-93":["Ela passou na prova apesar de estar doente, e os pais ficaram muito orgulhosos. Ela tinha estudado muito. Portanto, o resultado não foi surpresa."],"bkB1-94":["Apesar do trânsito, chegamos na hora."],"bkB1-95":["Embora estivesse frio, eles foram nadar."],"bkB1-96":["Apesar de estar cansado, ele terminou o relatório."],"bkB1-97":["Você não vai passar / a menos que estude mais.","Carlos é muito tímido, / enquanto a irmã dele é muito extrovertida.","O voo atrasou; / portanto, perdemos a conexão.","Ela fala quatro idiomas; / além disso, toca piano."],"bkB1-99":["A: Você curtiu o show ontem à noite?","B: Curti, embora estivesse lotado.","A: Sério? Ouvi dizer que os ingressos esgotaram.","B: Esgotaram. No entanto, meu primo tinha um sobrando.","A: Que sorte! Eu não consegui nenhum."],"bkB1-100":["Você poderia me dizer onde fica a estação?"],"bkB1-101":["Será que ele vai à festa?"],"bkB1-102":["Você sabe a que horas o museu abre? Eu também gostaria de saber quanto custam os ingressos."],"bkB1-103":["Você pode me dizer que horas são? E sabe se o banco está aberto?"],"bkB1-104":["Não sei onde ela mora."],"bkB1-105":["Você poderia me dizer onde fica o hospital mais próximo?"],"bkB1-106":["Você sabe se o pacote chegou?"],"bkB1-107":["Você sabe quanto tempo dura a viagem?"],"bkB1-109":["Olá! Meu nome é Diego e vou me mudar para Florianópolis no mês que vem. Gostaria de saber se há cursos de português para estrangeiros na cidade. Você também poderia me dizer quanto custam os cursos e se eles têm aulas à noite? Trabalho durante o dia, então só posso estudar depois das 18h. Agradeço desde já! Diego Ramírez"],"bkB1-110":["Há quanto tempo você tem este celular? — Desde o Natal."],"bkB1-111":["Quando o Brasil sediou a Copa do Mundo pela segunda vez? — Em 2014."],"bkB1-112":["O Rodrigo não está aqui agora. Ele foi à academia."],"bkB1-113":["A: Você terminou o relatório?","B: Terminei, enviei para o chefe há uma hora, mas ele ainda não respondeu."],"bkB1-114":["Oi, Leo! Estou em Lisboa há três semanas e estou adorando. No fim de semana passado fui a Sintra de trem. Nunca vi palácios tão lindos! Ontem provei meu primeiro pastel de nata aqui."],"bkB1-115":["Você assistiu à final ontem à noite? Eu ainda não vi, então não me conte o placar!"],"bkB1-116":["Minha avó é enfermeira há quarenta anos e ainda adora o trabalho. Meu avô trabalhou como taxista até se aposentar."],"bkB1-117":["Você já foi ao Chile?"],"bkB1-118":["Nos mudamos para Fortaleza quando eu tinha dez anos."],"bkB1-119":["Trabalho aqui há três anos."],"bkB1-120":["A Sofia já comprou os ingressos?"],"bkB1-121":["Ela acabou de terminar a primeira maratona."],"bkB1-122":["Quantas vezes você já visitou a Bahia?"],"bkB1-123":["Moro em Manaus / desde 2018 e adoro.","Morei em Manaus / por dois anos, depois me mudei para Belém.","Você já / experimentou paraquedismo?","Quando você / começou a aprender inglês?"],"bkB1-126":["A Paula já escreveu três livros até agora e está trabalhando no quarto."],"bkB1-127":["Marina é desenvolvedora de software de Recife. Ela trabalha na mesma empresa de tecnologia desde 2017. No ano passado, foi a uma conferência em Berlim, e foi a primeira vez dela na Europa. Ela estuda alemão há seis meses, mas ainda não voltou à Alemanha. A equipe dela acabou de lançar um novo aplicativo de saúde."],"bkB1-128":["Oi, Gabi, Adivinha? Finalmente achei um apartamento! Vi na terça e assinei o contrato ontem. É pequeno, mas tem uma varanda com vista para o mar. Ainda não me mudei, porque o dono ainda está pintando as paredes. Meu irmão se ofereceu para ajudar com as caixas no próximo sábado. Você já visitou Vitória? Você deveria vir! Abraços, Nanda"],"bkB1-129":["A: Você já foi a Foz do Iguaçu?","B: Já, fui em 2019.","A: Você viu as cataratas pelo lado argentino também?","B: Não. Eu só tinha um dia.","A: Que pena. Ouvi dizer que é incrível."],"bkB1-130":["Se você aquece o gelo, ele derrete."],"bkB1-131":["Onde você moraria se pudesse escolher qualquer cidade do mundo?"],"bkB1-132":["Empresto meu guarda-chuva se você devolver amanhã."],"bkB1-133":["A: O que você faria se perdesse o passaporte no exterior?","B: Iria à embaixada brasileira.","A: E se você não tivesse dinheiro nenhum?","B: Ligaria para os meus pais."],"bkB1-134":["A menos que chova, almoçaremos no jardim. Se estiver muito quente, vamos nos sentar debaixo da mangueira."],"bkB1-135":["Se eu fosse mais alto, jogaria vôlei profissionalmente."],"bkB1-136":["As plantas morrem se não receberem água suficiente."],"bkB1-137":["Se ele me ligar, conto a novidade."],"bkB1-138":["Se tivéssemos uma cozinha maior, cozinharíamos mais em casa."],"bkB1-139":["Se ela falasse inglês, poderia conseguir o emprego."],"bkB1-140":["Se você não se apressar, vai perder o trem."],"bkB1-141":["Se você mistura azul e amarelo, obtém verde."],"bkB1-142":["Você aceitaria o emprego se eles oferecessem?"],"bkB1-143":["Se você está com fome, / tem lasanha na geladeira.","Se eu tivesse asas, / voaria para a praia todo dia.","Se você congela a água, / ela vira gelo.","Se o ônibus atrasar de novo, / vou reclamar com a empresa."],"bkB1-146":["Se meu time ganhar o campeonato neste domingo, vou ficar tão feliz!"],"bkB1-147":["Laura trabalha num hotel em Gramado. Se os hóspedes chegam antes das 14h, podem deixar as malas na recepção. Se neva, o que é muito raro, o hotel prepara chocolate quente para todos. A Laura sempre diz: \"Se eu tivesse mais dias de férias, viajaria para o Japão.\" Se ela economizar o suficiente este ano, vai visitar a irmã em Portugal."],"bkB1-148":["REGRAS DA ACADEMIA Se você é aluno novo, agende uma sessão gratuita com um instrutor. Se usar um aparelho, limpe-o depois de terminar. As toalhas são grátis, mas se você perder uma, pagará R$20. Se a academia estiver muito cheia, não use o mesmo aparelho por mais de 20 minutos. Se tiver dúvidas, fale com a equipe na recepção."],"bkB1-149":["A: Você vai à praia com a gente no sábado?","B: Talvez. Se eu terminar meu projeto na sexta, eu vou.","A: E se você não terminar?","B: Aí vou ter que trabalhar o fim de semana todo, infelizmente.","A: Bom, se precisar de ajuda, é só me ligar."],"bkB1-150":["Nadar faz bem para as costas."],"bkB1-151":["O Marcos não pode se dar ao luxo de comprar um carro novo este ano."],"bkB1-152":["Você tem interesse em fazer um curso no Canadá?"],"bkB1-153":["Meu chefe sugeriu fazer a reunião on-line, e todos concordaram em começar às nove."],"bkB1-154":["A: Você lembra de ter trancado a porta quando saímos?","B: Lembro sim. E não esqueça de dar comida ao gato hoje à noite."],"bkB1-155":["Thiago continua olhando o celular durante a aula, então o professor pediu que ele parasse."],"bkB1-156":["Estou acostumado a acordar cedo e também não me importo de trabalhar até tarde."],"bkB1-157":["Estou pensando em mudar de emprego."],"bkB1-158":["O Paulo prometeu me ligar depois do jogo."],"bkB1-159":["Aprender chinês é difícil."],"bkB1-160":["Ele parou de comer açúcar."],"bkB1-161":["Não consigo imaginar viver sem meu celular."],"bkB1-162":["Eles esperam visitar Fernando de Noronha no ano que vem."],"bkB1-163":["We stopped smoking. / Paramos de fumar.","We stopped to smoke. / Paramos para fumar.","I remember visiting Ouro Preto. / Lembro que visitei Ouro Preto.","Remember to visit Ouro Preto. / Lembre-se de visitar Ouro Preto."],"bkB1-166":["Vale a pena visitar o centro histórico de Paraty."],"bkB1-167":["A Beatriz odiava cozinhar, mas no ano passado decidiu fazer um curso de culinária em São Paulo. No começo, ela vivia queimando o arroz! Agora gosta de experimentar receitas novas e aprendeu a fazer pão. Quer abrir um café pequeno um dia, mas ainda não pode se dar ao luxo de fazer isso."],"bkB1-168":["Oi, pessoal, Escrevo para convidar vocês a conhecer o nosso novo clube de corrida! Nos encontramos todo sábado às 7h no Parque Ibirapuera. Não se preocupe em ser lento. Nosso objetivo é ajudar iniciantes a começar a correr sem se machucar. Recomendamos levar água e usar tênis confortáveis. Se quiser participar, responda a este e-mail. Esperamos conhecer você! Carol"],"bkB1-169":["A: Você gostaria de vir jantar na sexta?","B: Eu adoraria! A que horas?","A: Por volta das oito. Você se importa de comer comida picante?","B: De jeito nenhum. Adoro experimentar coisas novas.","A: Ótimo! Estou pensando em fazer um curry tailandês."],"bkB1-170":["O novo hospital será inaugurado pelo governador na semana que vem."],"bkB1-171":["Meu carro está sendo consertado no momento, então estou indo de ônibus."],"bkB1-172":["A Mona Lisa foi pintada por Leonardo da Vinci."],"bkB1-173":["A feijoada é feita com feijão preto e porco. Geralmente é servida com arroz, couve e laranja em fatias."],"bkB1-174":["Nossa escola mudou muito. No ano passado, uma nova biblioteca foi construída. Agora, as salas de aula são limpas toda semana por uma equipe de alunos, e novos computadores serão instalados no mês que vem. A antiga quadra ainda não foi reformada, mas será em breve."],"bkB1-175":["O ladrão foi pego pela polícia, e os celulares roubados foram devolvidos aos donos."],"bkB1-176":["Os vencedores serão escolhidos pelo público, e os prêmios serão entregues na sexta."],"bkB1-177":["A carta foi escrita pelo meu avô."],"bkB1-178":["Estes biscoitos foram assados pela minha tia esta manhã."],"bkB1-179":["As sobremesas são preparadas toda manhã."],"bkB1-180":["Um novo estádio está sendo construído na nossa cidade."],"bkB1-181":["Os ingressos podem ser comprados on-line."],"bkB1-182":["Quando esta igreja foi construída?"],"bkB1-183":["O açaí / é colhido na Amazônia.","O primeiro iPhone / foi lançado em 2007.","Muitas novelas brasileiras / são vendidas para outros países.","As Olimpíadas de 2016 / foram realizadas no Rio de Janeiro."],"bkB1-186":["Os resultados foram enviados a todos os alunos por e-mail ontem."],"bkB1-187":["As sandálias Havaianas foram criadas no Brasil em 1962. O design foi inspirado em sandálias japonesas chamadas zori. No início, eram usadas principalmente por trabalhadores porque eram baratas. Hoje, são vendidas em mais de 100 países e usadas por celebridades. Milhões de pares são produzidos todos os anos."],"bkB1-188":["AVISO AOS MORADORES A água do prédio será desligada na terça-feira, das 9h às 15h, porque os canos estão sendo trocados. O elevador também será verificado no mesmo dia, então pedimos que os moradores usem as escadas. Todo o lixo deve ser levado aos novos contêineres, que foram instalados na semana passada perto da garagem. Pedimos desculpas pelo transtorno. A Administração"],"bkB1-189":["A: Com licença, meu notebook já foi consertado?","B: Deixe-me verificar. Qual é o seu nome, por favor?","A: Carlos Mendes. Deixei aqui na segunda.","B: Sim, foi consertado esta manhã. A tela foi trocada.","A: Ótimo! Quanto devo?"],"bkB1-190":["O cara cujo carro foi roubado chamou a polícia."],"bkB1-191":["Você lembra do dia em que nos conhecemos?"],"bkB1-192":["O Rio, que é famoso por suas praias, recebe milhões de turistas todos os anos."],"bkB1-193":["O aplicativo que uso para estudar é grátis. O professor que o recomendou é do Chile."],"bkB1-194":["Salvador é a cidade onde meus pais cresceram. É também o lugar onde eles se casaram, numa igreja com mais de 300 anos."],"bkB1-195":["O filme que vimos ontem à noite tinha um ator que nasceu no Brasil."],"bkB1-196":["Minha vizinha, que é enfermeira, trabalha no hospital onde eu nasci."],"bkB1-197":["O livro que estou lendo é incrível."],"bkB1-198":["Esse é o aluno cuja mãe é minha dentista."],"bkB1-199":["Este é o café onde tomamos café da manhã."],"bkB1-200":["Meu tio, que mora no Canadá, é chef de cozinha."],"bkB1-201":["Preciso de alguém que saiba consertar meu computador."],"bkB1-202":["Esta é a bolsa que você perdeu?"],"bkB1-203":["Você conhece alguém / que fale japonês?","Nunca vou esquecer o verão / em que fomos de carro à Patagônia.","Ficamos num hotel / que tinha piscina na cobertura.","Aquela é a cantora / cujas músicas são todas sobre a Bahia."],"bkB1-204":["a enfermeira que cuidou de mim, os alunos que passaram na prova","o ônibus que vai ao aeroporto, a receita que minha avó criou","o menino cuja bicicleta é vermelha, a empresa cujo diretor renunciou"],"bkB1-206":["Aquele é o professor cuja aula você curtiu tanto?"],"bkB1-207":["A Vila Madalena é um bairro de São Paulo famoso por sua arte de rua. O Beco do Batman, onde artistas pintaram quase todas as paredes, é o ponto mais popular. Muitas pessoas que visitam a região também vão aos bares que ficam abertos até tarde. Juliana, cujo apartamento fica perto da praça principal, diz que os fins de semana são barulhentos, mas divertidos."],"bkB1-208":["Oi, Matheus, O apartamento sobre o qual você perguntou ainda está disponível. Fica numa rua tranquila onde há muitas árvores. O dono, que mora no primeiro andar, é muito simpático. O quarto, que dá para o jardim, pega sol de manhã. O único problema é a cozinha, cuja janela não abre. Me avise se quiser ver. Renata"],"bkB1-209":["A: Quem é a mulher que está conversando com seu pai?","B: É a Dona Lúcia, a vizinha cujo filho toca numa banda.","A: Ah, a banda que tocou no festival?","B: Isso mesmo! O festival onde nos conhecemos.","A: Eu lembro! Foi uma noite ótima."],"bkB1-210":["Tem uma farmácia perto daqui, não tem?"],"bkB1-211":["Você terminou o exercício, não terminou?"],"bkB1-212":["Todo mundo adorou o show, não adorou?"],"bkB1-213":["A: O voo sai às seis, não sai?","B: Sai. Devemos sair de casa cedo, não devemos?","A: Com certeza. Você não vai esquecer os passaportes, vai?"],"bkB1-214":["Marcos: Você não estava na festa, estava?","Lia: Não, tive que trabalhar. Foi divertido, não foi?","Marcos: Foi ótimo! Seu irmão estava lá, não estava?"],"bkB1-215":["Sou seu melhor amigo, não sou? Feche a porta, pode ser?"],"bkB1-216":["Ela quase nunca reclama, reclama? Eles nunca foram à Europa, foram?"],"bkB1-217":["Você gosta de futebol, não gosta?"],"bkB1-218":["Seus pais são de Belém, não são?"],"bkB1-219":["Sua irmã tem dois filhos, não tem?"],"bkB1-220":["Nós não pagamos o café, pagamos?"],"bkB1-221":["Não foi culpa sua, foi?"],"bkB1-222":["Você sabe falar espanhol, não sabe?"],"bkB1-223":["Você gostaria de um café, / não gostaria?","Nada aconteceu, / aconteceu?","Sente-se, / que tal?","Ela vai ligar mais tarde, / não vai?"],"bkB1-226":["Ana e Bruno vão se casar em maio, não vão?"],"bkB1-227":["Tiago e Paula estão esperando no ponto de ônibus. \"O ônibus atrasou de novo, não foi?\", diz Paula. \"Foi. Você não trouxe guarda-chuva, trouxe?\", pergunta Tiago. \"Não\", ela responde, \"mas não vai chover, vai?\" Tiago olha para o céu escuro e ri."],"bkB1-228":["Oi, Rafa, Você ainda vai ao churrasco do Júlio no domingo, não vai? Eu disse a ele que você levaria as bebidas. Você não esqueceu, esqueceu? Começa ao meio-dia, mas a maioria das pessoas vai chegar mais tarde. A propósito, você sabe o novo endereço do Júlio, não sabe? É Rua das Flores, 45, perto da padaria. Nos vemos lá! Cami"],"bkB1-229":["A: Você é brasileiro, não é?","B: Sou sim. Como você sabia?","A: Pelo seu sotaque! Você é do Sul, não é?","B: Isso mesmo, de Porto Alegre. Você já esteve lá, não já?","A: Não, nunca. Mas adoraria ir."],"bkB1-230":["Alguém está batendo. Deve ser o Diego. Ele disse que viria às sete, e já são sete."],"bkB1-231":["Juliana tinha cabelo comprido, mas agora está bem curto."],"bkB1-232":["No começo eu não gostava do frio, mas agora estou acostumado."],"bkB1-233":["Quando meu pai era jovem, não tinha carro. Ele andava de bicicleta para todo lugar.","Você ia a pé para a escola quando era criança?"],"bkB1-234":["Mudar para o Canadá foi difícil no começo. Eu não estava acostumado a dirigir na neve. Agora estou acostumado a usar três camadas de roupa!"],"bkB1-235":["Meus pais moravam numa fazenda, então estão acostumados a acordar às 5h."],"bkB1-236":["Você está dirigindo há dez horas, então deve estar cansado. E este não pode ser o nosso hotel: o nosso tem piscina, e este não tem."],"bkB1-237":["Eu jogava futebol quando era criança."],"bkB1-238":["Ela não pode estar em casa; o carro dela não está na garagem."],"bkB1-239":["Esta não pode ser a bolsa da Maria."],"bkB1-240":["Eu tocava bateria."],"bkB1-241":["Você tinha cabelo comprido?"],"bkB1-242":["Eles devem estar muito orgulhosos da filha."],"bkB1-243":["Ela está bocejando o tempo todo. / Deve estar com sono.","Ele está usando aliança. / Deve ser casado.","O Leo está no escritório agora. / Aquele não pode ser o Leo na praia.","Eles acabaram de comprar uma mansão. / Devem ser ricos."],"bkB1-244":["Eu fumava (hábito passado), mas parei., Nós tínhamos (hábito passado) um cachorro chamado Tupi., Eles iam (hábito passado) à igreja todo domingo.","Ela está acostumada (acostumado) a morar sozinha agora., Ele está acostumado (acostumado) a trabalhar à noite., Estou acostumado (acostumado) a comer comida picante."],"bkB1-246":["Antes havia um cinema aqui, mas agora é uma farmácia."],"bkB1-247":["Quando era jovem, Dona Célia vendia frutas numa feira em Belém. Ela não tinha muito tempo livre, mas dançava nas noites de sábado. Agora tem 80 anos e mora com a neta. Ela não está acostumada a morar num apartamento grande, mas gosta da vista."],"bkB1-248":["Dez anos atrás, Lagoa Santa era uma cidade tranquila. Não havia shoppings, e as pessoas conheciam todos os vizinhos. Agora há prédios novos por toda parte e muito trânsito. Meu avô diz que ainda não está acostumado ao barulho. Mas ele gosta do novo hospital, que fica bem perto da casa dele."],"bkB1-249":["A: De quem é aquele carro na frente da sua casa?","B: Deve ser da minha irmã. Ela disse que vinha hoje.","A: Mas a sua irmã tem um carro pequeno, não tem?","B: Tinha. Ela comprou um maior no mês passado.","A: Ah, então deve ser dela."],"bkB1-250":["Preciso marcar uma consulta com o dentista."],"bkB1-251":["Você já fez a pesquisa para o trabalho de história?"],"bkB1-252":["Você poderia fazer uma cópia deste documento para mim?"],"bkB1-253":["Antes da minha viagem ao Chile, tenho muita coisa para fazer. Preciso fazer uma reserva de hotel, pesquisar sobre o clima e fazer uma lista do que levar. Também tenho que passar a roupa!"],"bkB1-254":["A: O que sua mãe faz?","B: Ela é engenheira. Faz muitos negócios com a China.","A: Legal! Ela ganha muito dinheiro?"],"bkB1-255":["A tempestade causou muitos danos às casas perto do rio, mas voluntários estão fazendo o possível para ajudar."],"bkB1-256":["Você pode lavar a louça enquanto eu faço o café?"],"bkB1-257":["Não se preocupe, você foi bem na prova. Cometeu só dois errinhos."],"bkB1-258":["As crianças fizeram uma bagunça enorme na sala de estar."],"bkB1-259":["Ela está fazendo um curso de espanhol on-line."],"bkB1-260":["Por favor, verifique se a porta está trancada."],"bkB1-261":["Meu pai cozinha aos domingos."],"bkB1-262":["Ela fez um ótimo discurso no casamento."],"bkB1-263":["O chef sempre faz / o macarrão do zero.","Nosso professor nos fez fazer / um exercício extra.","Correr todo dia faz / muito bem para você.","O barulho da festa tornou / difícil dormir."],"bkB1-266":["Você fez uma oferta por aquele apartamento?"],"bkB1-267":["Todo sábado, a família Silva faz o serviço de casa junta. O Sr. Silva cozinha, e a filha Bia arruma as camas. Os gêmeos passam o aspirador, mas muitas vezes fazem bagunça com os brinquedos. Depois do almoço, a Sra. Silva faz café e todos fazem algo divertido, como jogar cartas."],"bkB1-268":["VAGA: RECEPCIONISTA DE HOTEL Nosso hotel em Bonito está procurando uma recepcionista. Você fará reservas, atenderá telefonemas e fará algum trabalho de escritório. Você deve fazer os hóspedes se sentirem bem-vindos e fazer o possível para resolver os problemas deles. Oferecemos aulas de inglês gratuitas, para que você progrida no idioma. Envie seu currículo até sexta."],"bkB1-269":["A: O que você vai fazer neste fim de semana?","B: Tenho que fazer umas compras e depois vou fazer lasanha para meus pais.","A: Parece ótimo. Posso fazer algo para ajudar?","B: Claro! Você poderia fazer uma salada?","A: Sem problema. Levo no domingo."],"bkB1-270":["Estou economizando dinheiro para um notebook novo."],"bkB1-271":["Ela trabalha no hospital há dez anos."],"bkB1-272":["Posso sair mais cedo hoje?"],"bkB1-273":["A: Aonde você vai?","B: Ao supermercado. Precisamos de ovos para o bolo.","A: Você pode trazer leite para mim também?"],"bkB1-274":["Me candidatei a uma vaga numa startup. Enviei meu currículo para a gerente, e ela me pediu para fazer uma entrevista."],"bkB1-275":["Vou para Recife para uma conferência na semana que vem."],"bkB1-276":["Obrigado por vir! Precisamos de mais gente para ajudar com o evento."],"bkB1-277":["Minha mãe sempre faz feijoada para nós aos domingos."],"bkB1-278":["Ele pediu um copo de água."],"bkB1-279":["Esta máquina serve para fazer suco."],"bkB1-280":["Ela comprou um presente para a avó."],"bkB1-281":["Enviei um e-mail ao gerente do hotel."],"bkB1-282":["Fomos a Gramado para o festival do chocolate."],"bkB1-283":["Fumar faz mal / para a saúde.","Sinto muito / por ter me atrasado.","Ela é nova demais / para dirigir um carro.","Você poderia passar o sal / para mim, por favor?"],"bkB1-284":["explicar a alguém, ir para a cama, responder a um e-mail, acontecer com alguém","pedir ajuda, solicitar um visto, ser famoso por algo, buscar informações"],"bkB1-286":["O Brasil é famoso por sua música e suas praias."],"bkB1-287":["Gabriel foi a Lisboa por seis meses para estudar arquitetura. Antes de ele partir, os amigos organizaram uma festa para ele. A tia dele lhe deu um dicionário de português de presente. Em Lisboa, ele escreve sempre para os pais e envia fotos para a irmãzinha toda semana."],"bkB1-288":["Prezado Sr. Lopes, Obrigada pelo seu e-mail. Escrevo para confirmar sua reserva de duas noites, de 3 a 5 de maio. O café da manhã está incluso e é servido das 7h às 10h. Se precisar de um táxi para o aeroporto, é só pedir na recepção. Também temos bicicletas para os hóspedes, sem custo. Atenciosamente, Pousada Mar Azul"],"bkB1-289":["A: Oi! Gostaria de enviar este pacote para Manaus.","B: Claro. É um presente para alguém?","A: É sim, para o aniversário do meu sobrinho.","B: Certo. Vai levar uns cinco dias para chegar lá.","A: Perfeito. Obrigado pela ajuda!"],"bkB1-290":["Leve uma jaqueta caso esfrie mais tarde."],"bkB1-291":["Você pode pegar meu carro emprestado, desde que dirija com cuidado."],"bkB1-292":["O jogo foi cancelado devido à chuva forte."],"bkB1-293":["Trabalhar em casa tem muitas vantagens. Em primeiro lugar, você economiza tempo porque não precisa se deslocar. Além disso, pode organizar o próprio horário. No entanto, algumas pessoas se sentem sozinhas. Como sentem falta dos colegas, muitas vezes voltam ao escritório alguns dias por semana."],"bkB1-294":["Saí cedo para conseguir pegar o último ônibus. No entanto, eu o perdi e tive que pegar um táxi."],"bkB1-295":["Embora a Maria ganhe um bom salário, ela mora com os pais. O irmão dela, por outro lado, mora sozinho."],"bkB1-296":["Salve seu arquivo com frequência. Caso contrário, você pode perder seu trabalho. E me ligue assim que terminar."],"bkB1-297":["Embora fosse tarde, continuamos dançando."],"bkB1-298":["Vou à festa, a menos que chova."],"bkB1-299":["Apesar de não ter muita experiência, ela conseguiu o emprego."],"bkB1-300":["O Paulo adora comida picante, enquanto a esposa dele odeia."],"bkB1-301":["Anotei para não esquecer."],"bkB1-302":["A estrada foi fechada em consequência da enchente."],"bkB1-303":["Leve um guarda-chuva / caso chova.","Eu ajudo você / desde que você me ajude depois.","O museu é gratuito; / no entanto, é preciso reservar um ingresso.","Ela estava cansada; / mesmo assim, foi à academia."],"bkB1-306":["Apesar de ser muito rico, ele mora numa casa pequena."],"bkB1-307":["O Rio de Janeiro é uma cidade maravilhosa para turistas. No entanto, pode fazer muito calor no verão, então os visitantes devem beber bastante água. Embora as praias sejam gratuitas, as cadeiras e os guarda-sóis não são. Além disso, a cidade tem ótimos museus, como o Museu do Amanhã. A menos que goste de multidões, evite Copacabana na noite de Ano Novo."],"bkB1-308":["Prezado cliente, Sentimos muito, mas seu pedido chegará com dois dias de atraso devido a uma greve no porto. Embora a culpa não seja nossa, gostaríamos de oferecer frete grátis na sua próxima compra. Além disso, se preferir cancelar o pedido, pode fazê-lo desde que o produto ainda não tenha sido enviado. Caso contrário, você o receberá na quinta-feira. Atenciosamente, Casa Tech"],"bkB1-309":["A: Você vai aceitar o emprego em Brasília?","B: Não tenho certeza. O salário é ótimo. No entanto, eu teria que me mudar.","A: Mas você sempre quis morar numa cidade nova, não é?","B: Verdade. Por outro lado, minha família está aqui.","A: Bom, o que quer que você decida, eu apoio."],"bkB1-310":["Você faz ideia de quantos anos ele tem?"],"bkB1-311":["Gostaria de saber se o café da manhã está incluso."],"bkB1-312":["Você consegue lembrar onde estacionamos o carro?"],"bkB1-313":["Com licença, você poderia me dizer onde fica o portão? Não tenho certeza se meu voo sai no horário."],"bkB1-314":["A: Você sabe por que a Carla saiu do emprego no mês passado?","B: Nem ideia. Será que ela arranjou um melhor?"],"bkB1-315":["Você poderia me dizer quanto custa isto? Também gostaria de saber se vocês aceitam cartão de crédito."],"bkB1-316":["Não tenho certeza de que horas começa o show, mas sei onde é."],"bkB1-317":["Será que ela vem hoje à noite?"],"bkB1-318":["Você poderia me dizer onde posso comprar um chip de celular?"],"bkB1-319":["Posso perguntar qual é o seu e-mail?"],"bkB1-320":["Você pode me dizer se este ônibus vai para o aeroporto?"],"bkB1-321":["Me pergunto por que o voo foi cancelado."],"bkB1-322":["Você sabe de quem é este celular?"],"bkB1-323":["Onde fica a saída? / Você pode me dizer onde fica a saída?","O museu está aberto hoje? / Gostaria de saber se o museu está aberto hoje.","Quanto custa um ingresso? / Você sabe quanto custa um ingresso?","Quando começa o passeio? / Você poderia me dizer quando começa o passeio?"],"bkB1-326":["Você poderia me dizer se este lugar está livre?"],"bkB1-327":["Vanessa está na recepção de um hotel em Buenos Aires. Ela pergunta ao recepcionista se o quarto está pronto, mas não está. Então quer saber onde pode deixar a mala. O recepcionista pergunta se ela gostaria de um mapa da cidade. Vanessa diz que sim e pergunta a que horas é servido o café da manhã."],"bkB1-328":["Olá, Vi seu anúncio do violão e tenho algumas perguntas. Você poderia me dizer quantos anos tem o violão? Também gostaria de saber se vem com capa. E você sabe se as cordas são novas? Se estiver tudo certo, gostaria de vê-lo neste fim de semana. Pode me dizer qual horário é melhor para você? Obrigado, Henrique"],"bkB1-329":["A: Com licença, você sabe onde fica a estação de metrô mais próxima?","B: Claro. Fica a dois quarteirões daqui, na Avenida Paulista.","A: Obrigado! E você poderia me dizer se os trens funcionam até tarde?","B: Acho que funcionam até a meia-noite.","A: Ótimo, muito obrigado!"],"bkB1-1001":["Quando chegamos ao cinema, o filme já tinha começado."],"bkB1-1002":["A: Você viu o Leo na festa?","B: Não. Quando cheguei lá, ele já tinha ido embora.","A: E a Sofia?","B: Ela ainda não tinha chegado, então conversei com o Mark.","A: O Mark? Eu nunca o tinha conhecido antes daquele dia."],"bkB1-1003":["Quando liguei, eles já tinham saído de casa. Fiquei feliz porque tinha passado na prova."],"bkB1-1004":["Quando chegamos à estação, o trem já tinha partido."],"bkB1-1005":["Quando cheguei, o Tom já tinha saído de casa."],"bkB1-1006":["Eles já tinham comido quando você chegou em casa?"],"bkB1-1007":["Na sexta passada, a Carla foi ao aeroporto buscar o primo. Quando chegou lá, o avião dele já tinha pousado, mas ele não estava no saguão de desembarque. Ela estava esperando havia vinte minutos quando o celular tocou. O primo tinha ido ao terminal errado!"],"bkB1-1008":["A Paula ficou chateada porque tinha esquecido o passaporte em casa."],"bkB1-1009":["Ele estava com muita fome / porque não tinha comido o dia todo.","Não consegui abrir a porta / porque tinha perdido a chave.","O jardim estava lindo / porque ela tinha plantado flores novas.","O chão da cozinha estava molhado / porque as crianças tinham derramado suco."],"bkB1-1010":["A: Você parece chateado. O que aconteceu?","B: Perdi minha carteira a caminho do trabalho.","A: Você tinha conferido a bolsa antes de sair de casa?","B: Tinha sim. Tenho certeza de que a tinha colocado na bolsa."],"bkB1-1011":["A Sara não quis almoçar porque já tinha comido."],"bkB1-1012":["Ela estava esperando havia uma hora quando ele finalmente chegou."],"bkB1-1013":["Eu nunca tinha visto neve antes de me mudar para o Canadá."],"bkB1-1014":["Ela não tinha visto aquele filme antes."],"bkB1-1015":["Estou cansada porque passei a manhã inteira limpando."],"bkB1-1016":["A: Você parece cansado. Tem dormido bem?","B: Não, não tenho dormido bem desde segunda. Tenho trabalhado até tarde toda noite."],"bkB1-1017":["Estudo inglês há três anos. Há quanto tempo você mora aqui?"],"bkB1-1018":["Está chovendo desde esta manhã."],"bkB1-1019":["Trabalho aqui desde 2019."],"bkB1-1020":["Há quanto tempo você está aprendendo a dirigir?"],"bkB1-1021":["Dan é padeiro. Ele trabalha na mesma padaria há oito anos. Esta semana ele tem treinado uma nova assistente, a Eva. Ela começou na segunda. Hoje o Dan está cansado porque está assando pão desde as quatro da manhã."],"bkB1-1022":["Ela está estudando para a prova desde segunda."],"bkB1-1023":["Por que suas mãos estão tão sujas? / Estive pintando a cerca.","Você parece exausto! / É, estou correndo desde as seis.","Seus olhos estão vermelhos. / Você andou chorando?","As ruas estão molhadas. / Tem chovido a noite toda."],"bkB1-1025":["Estou esperando você desde as duas horas."],"bkB1-1026":["Conheço a Rita desde a escola. Ela está lendo aquele livro a semana toda."],"bkB1-1027":["Ela o conhece há anos."],"bkB1-1028":["Eles não têm jogado futebol ultimamente."],"bkB1-1029":["Os visitantes não devem tocar nas pinturas. É estritamente proibido."],"bkB1-1030":["Ontem a Marta teve que ficar até tarde no escritório por causa de uma reunião urgente."],"bkB1-1031":["A: Por que você está saindo tão cedo?","B: Tenho que buscar minha filha às cinco.","A: Ela precisa voltar de ônibus?","B: Não, não precisa. Eu levo de carro."],"bkB1-1032":["Você não deve usar o celular durante a prova. É contra as regras. Amanhã é feriado, então não precisamos acordar cedo."],"bkB1-1033":["Na semana passada tive que renovar meu passaporte, e no mês que vem meu irmão terá que fazer o mesmo."],"bkB1-1034":["Ela não precisa usar uniforme na escola nova."],"bkB1-1035":["Você teve que mostrar o passaporte no aeroporto?"],"bkB1-1036":["O Ben não precisa vir à reunião."],"bkB1-1037":["Eu tive que terminar esta redação ontem."],"bkB1-1038":["Sua irmã precisa usar óculos?"],"bkB1-1039":["Lena trabalha num hospital. Ela tem que usar uniforme, mas não precisa trabalhar nos fins de semana. Amanhã ela tem que começar às seis porque uma colega está doente. Os visitantes não devem usar o celular na unidade de terapia intensiva."],"bkB1-1040":["A placa diz proibido fotos no museu. / Você não pode tirar fotos.","A entrada no parque é grátis. / Você não precisa pagar.","O voo da Mia sai às 6h. / Ela tem que acordar muito cedo.","Ontem o trem foi cancelado. / Tivemos que pegar um táxi."],"bkB1-1042":["Meu irmão é estudante, então não precisa pagar o ônibus. É grátis para ele."],"bkB1-1043":["Foi uma manhã tão fria que o lago congelou."],"bkB1-1044":["Havia tanta gente no show que não conseguimos encontrar nossos amigos."],"bkB1-1045":["A: Como foi o hotel?","B: Que lugar lindo! Os quartos eram tão grandes, e a equipe era tão simpática que lembravam dos nossos nomes.","A: Tenho certeza de que vocês se divertiram muito!"],"bkB1-1046":["A prova foi tão difícil que ninguém terminou. Foi uma prova muito incomum."],"bkB1-1047":["Tenho tanto trabalho hoje, e há tantos e-mails para responder."],"bkB1-1048":["Ela é uma pessoa tão gentil que todo mundo gosta dela."],"bkB1-1049":["Nos divertimos muito na festa ontem à noite."],"bkB1-1050":["O filme era tão chato que peguei no sono."],"bkB1-1051":["Foi um dia tão quente que ficamos na água a tarde toda."],"bkB1-1052":["Ela fala tão rápido que ninguém a entende."],"bkB1-1053":["No verão passado, Daniel foi à Islândia. A paisagem era tão linda que ele tirou mais de mil fotos. Era um país tão frio que ele usava casaco até em julho. Ele conheceu pessoas tão simpáticas no albergue, e eles cozinhavam o jantar juntos toda noite. A viagem foi tão cara que ele não pode viajar de novo este ano."],"bkB1-1054":["A sopa estava tão quente / que queimei a língua.","Foi um filme tão longo / que fizemos uma pausa.","Ela tem tantos amigos / que o celular não para de tocar.","Eles tinham lugares tão bons / que viam tudo."],"bkB1-1056":["Havia tanto trânsito que perdemos o voo."],"bkB1-1057":["Minha irmã tem medo de cachorros."],"bkB1-1058":["Nossa viagem à Bahia depende do tempo."],"bkB1-1059":["A: Você tem interesse em jazz?","B: Tenho, gosto muito."],"bkB1-1060":["Marina tem orgulho do filho. Ele joga xadrez muito bem e nunca tem medo de perder."],"bkB1-1061":["Ela é casada com um médico, e ele é famoso por suas músicas."],"bkB1-1062":["Chegamos a Curitiba ao meio-dia, e o Tom pediu desculpas por se atrasar."],"bkB1-1063":["Você acredita em fantasmas?"],"bkB1-1064":["Houve um grande aumento nos preços no ano passado."],"bkB1-1065":["Ela tem orgulho de ter vencido a corrida."],"bkB1-1066":["Estamos esperando o trem."],"bkB1-1067":["Ele pediu desculpas a mim por ter se atrasado."],"bkB1-1068":["Qual é o motivo do atraso?"],"bkB1-1069":["A: Por que você está tão preocupado com amanhã?","B: Tenho uma entrevista de emprego e tenho medo de errar.","A: Não se preocupe. Você é bom em conversar com as pessoas.","B: Obrigado. Ainda estou esperando o e-mail deles com o horário."],"bkB1-1070":["Rafael é professor em Curitiba. Ele é casado com a Paula, uma enfermeira. Rafael é bom em explicar as coisas, mas é ruim em lembrar nomes. Ele tem orgulho dos alunos e se interessa por ciência. Na semana que vem ele viaja para Recife e tem medo de voar."],"bkB1-1071":["Oi, Carla, obrigado pela sua mensagem. Cheguei a Lisboa ontem. O hotel é diferente das fotos, mas é limpo e tranquilo. Agora estou esperando um táxi para o centro histórico. Lisboa é famosa pela comida, então estou muito animado. Amanhã vou ver alguns apartamentos, porque posso ficar aqui um ano. Até breve! Bruno"],"bkB1-1073":["O sucesso depende / de trabalho duro.","Concordo totalmente / com você.","Ele é muito bom / em desenhar.","O Brasil é famoso / por suas praias."],"bkB1-1074":["Ela está brava com o irmão por ter perdido as chaves dela."],"bkB1-1075":["Maria tem dois irmãos. Os dois são engenheiros."],"bkB1-1076":["A: Você quer chá ou café? B: Tanto faz. Qualquer um serve."],"bkB1-1077":["Convidei vinte pessoas, mas nenhuma delas veio."],"bkB1-1078":["A: Você gosta de jazz ou de música clássica? B: Não gosto de nenhum dos dois."],"bkB1-1079":["Tenho dois primos, Rita e Paulo. Os dois moram em Salvador, no mesmo prédio. Nenhum dos dois tem carro, então pegam ônibus. Somos cinco na minha família, e todos nós adoramos futebol, até minha avó. Pedi ajuda aos meus quatro amigos, mas nenhum respondeu."],"bkB1-1080":["Não há ovos na geladeira. Preciso fazer compras.","A: Tem biscoitos?","B: Não, não tem nenhum."],"bkB1-1081":["Tanto minha mãe quanto meu pai trabalham no hospital. Não consigo achar minhas chaves em nenhum dos bolsos. Nenhuma das duas respostas está correta."],"bkB1-1082":["Nenhum dos meus irmãos gosta de comida picante."],"bkB1-1083":["Os dois falam português em casa."],"bkB1-1084":["Nem a Julia nem a irmã falam francês."],"bkB1-1085":["Não gosto de nenhum destes dois filmes."],"bkB1-1086":["A: Qual você quer, a camisa azul ou a verde?","B: Por mim, qualquer uma serve.","A: Sério? Gosto das duas.","B: Então vamos comprar as duas."],"bkB1-1087":["Nossa turma tem vinte alunos. Todos passaram na primeira prova, mas nenhum passou na segunda. Os dois professores, o Sr. Lopes e a Sra. Dias, ficaram surpresos. Nenhum deles esperava notas tão baixas."],"bkB1-1088":["Oi, Dan, Verifiquei dois restaurantes para sábado. Nenhum deles tem mesa para dez pessoas, porque os dois são pequenos. Mas qualquer um dos lugares consegue uma mesa para seis. Todos os nossos amigos disseram que estão livres depois das 19h, mas nenhum quer dirigir longe. Vamos decidir amanhã. Bea"],"bkB1-1090":["Both / os dois, ambos","Either / um ou outro (de dois)","Neither / nenhum dos dois","None / nenhum de vários","All / todos (três ou mais)"],"bkB1-1091":["Jo tem dois empregos, mas nenhum deles paga bem."],"bkB1-1092":["Meu chefe me fez trabalhar até tarde de novo ontem à noite."],"bkB1-1093":["A escola não permite que os alunos usem celular em aula."],"bkB1-1094":["No verão passado, meu pai me deixou dirigir a caminhonete dele. Ele disse que eu só podia dirigir em estradas rurais."],"bkB1-1095":["O professor nos fez escrever a redação de novo. Não tínhamos permissão para usar dicionários."],"bkB1-1096":["A lei exige que as empresas tratem os trabalhadores com justiça. O novo aplicativo nos ajuda a economizar tempo."],"bkB1-1097":["Minha mãe não me deixa ficar acordado até tarde."],"bkB1-1098":["Os visitantes não têm permissão para estacionar em frente ao portão."],"bkB1-1099":["Os trabalhadores foram obrigados a usar capacete."],"bkB1-1100":["Os passageiros têm permissão para levar uma bolsa pequena."],"bkB1-1101":["Meus pais me deixaram ir ao show."],"bkB1-1102":["Não tínhamos permissão para tirar fotos no museu."],"bkB1-1103":["A: Por que você não pode ir ao cinema hoje à noite?","B: Meu pai me fez limpar a garagem.","A: Que pena. Você tem permissão para ir amanhã?","B: Acho que sim. Ele me deixa ir se eu terminar."],"bkB1-1104":["Na Brightly Tech, a empresa deixa os funcionários trabalharem de casa às sextas. Todos são obrigados a comparecer à reunião de segunda. Os funcionários não têm permissão para levar cachorros ao escritório. A empresa não obriga ninguém a trabalhar nos fins de semana."],"bkB1-1105":["Obrigar alguém (ativa) / O professor nos fez ler.","Permitir de modo informal / Minha mãe me deixa ficar acordado.","Permissão na passiva / Não temos permissão para fumar aqui.","Obrigação na passiva / Fui obrigado a esperar do lado de fora."],"bkB1-1107":["Oi, Rita, como está sua escola nova? Aqui, as regras são rígidas. Não temos permissão para usar celular durante a aula, e o professor nos faz deixá-los numa caixa. No entanto, nosso diretor nos deixa almoçar do lado de fora quando o tempo está bom. Na semana passada, ele até permitiu que nossa turma jogasse futebol no campo grande. Ainda não tenho permissão para ir sozinho para casa, então meu pai me busca. Escreva logo! Caio"],"bkB1-1108":["Crianças menores de doze anos não têm permissão para andar nesta montanha-russa."],"bkB1-1109":["Fui obrigado a trabalhar o fim de semana todo."],"bkB2-0":["Semana passada, o Tom me disse: \"Ligo para você amanhã.\" → Semana passada, o Tom me disse que ligaria para mim no dia seguinte."],"bkB2-1":["Direta: \"Estamos nos mudando para Recife no mês que vem.\"","Indireta: Eles disseram que estavam se mudando para Recife no mês seguinte."],"bkB2-2":["O médico me perguntou há quanto tempo eu estava me sentindo mal e se eu estava tomando algum remédio."],"bkB2-3":["Ela me perguntou onde eu tinha comprado meus sapatos."],"bkB2-4":["A professora disse às crianças para não tocarem na tela."],"bkB2-5":["O Paulo me perguntou onde eu morava."],"bkB2-6":["Ela prometeu que enviaria o relatório até sexta."],"bkB2-7":["A: A Carla ligou enquanto eu estava fora?","B: Ligou sim. Ela disse que precisava falar com você.","A: Ela disse sobre o quê?","B: Disse que era sobre a reunião de amanhã.","A: Certo, vou ligar de volta agora mesmo."],"bkB2-8":["Ontem, a Marina teve uma entrevista de emprego numa empresa de tecnologia em Curitiba. O gerente perguntou por que ela queria sair do emprego atual. Marina disse a ele que estava buscando novos desafios. Ele também perguntou se ela poderia começar em março. Ela disse que precisaria de duas semanas para cumprir o aviso prévio."],"bkB2-9":["Ele disse: \"Eu sei nadar.\" / Ele disse que sabia nadar.","Ele disse: \"Estou nadando.\" / Ele disse que estava nadando.","Ele disse: \"Eu nadei.\" / Ele disse que tinha nadado.","Ele disse: \"Vou nadar.\" / Ele disse que ia nadar."],"bkB2-10":["Se tivéssemos pegado o ônibus mais cedo, não teríamos perdido o começo do filme."],"bkB2-11":["Se o Lucas tivesse estudado medicina há dez anos, seria médico agora."],"bkB2-12":["Se eu soubesse do trânsito, teria saído de casa mais cedo hoje de manhã."],"bkB2-13":["Se ela tivesse me pedido, eu a teria ajudado."],"bkB2-14":["Se eu tivesse trazido um guarda-chuva, não teria me molhado."],"bkB2-15":["Se ele tivesse economizado algum dinheiro no ano passado, poderia viajar agora."],"bkB2-16":["Se você tivesse me pedido, eu teria emprestado dinheiro."],"bkB2-17":["Querida Ana, Sinto muito por ter perdido sua festa de aniversário no sábado. Meu voo de Manaus foi cancelado por causa de uma tempestade, e o seguinte estava lotado. Se o tempo tivesse estado melhor, eu teria estado lá com você. Sinceramente, se eu tivesse reservado um voo na sexta, não estaria me sentindo tão culpada agora! Adoraria levar você para jantar na semana que vem para comemorar. Beijos, Júlia"],"bkB2-18":["Se eu não tivesse comido tanto, / não estaria me sentindo mal agora.","Se eles tivessem saído na hora, / não teriam perdido o voo.","Se ela não fosse tão tímida, / teria falado na reunião.","Se você tivesse carregado o celular, / poderia ter ligado para nós."],"bkB2-19":["Se o Rafael não tivesse quebrado a perna no mês passado, estaria jogando na partida de hoje à noite."],"bkB2-20":["A nova ponte está sendo construída agora, então temos que pegar outro caminho."],"bkB2-22":["Este hotel foi construído em 1920 e foi reformado várias vezes desde então. No ano que vem, uma nova piscina será acrescentada."],"bkB2-23":["A: Por que a Paula está tão feliz?","B: Ela acabou de ser promovida a gerente.","A: Ótimo! E quem vai fazer o antigo trabalho dela?","B: A vaga só poderá ser preenchida no mês que vem."],"bkB2-24":["Os documentos precisam ser assinados antes de serem enviados ao advogado."],"bkB2-25":["O carro está sendo consertado na oficina esta semana."],"bkB2-26":["Minha bicicleta foi roubada."],"bkB2-27":["Um novo shopping vai ser inaugurado em Fortaleza."],"bkB2-28":["O novo software já terá sido instalado até segunda."],"bkB2-29":["A famosa estátua do Cristo Redentor, no Rio de Janeiro, foi concluída em 1931. Foi projetada por um engenheiro brasileiro, Heitor da Silva Costa, e o rosto foi criado por um escultor romeno. Ao longo dos anos, a estátua foi atingida por raios muitas vezes. Hoje é visitada por cerca de dois milhões de pessoas por ano, e em 2007 foi escolhida como uma das Novas Sete Maravilhas do Mundo."],"bkB2-30":["As ruas estão todas molhadas. Deve ter chovido durante a noite."],"bkB2-32":["A: Não consigo achar as chaves do carro em lugar nenhum.","B: Você deve tê-las deixado no carro. Você veio dirigindo, não veio?","A: Não, não posso tê-las deixado no carro. Vim de ônibus!"],"bkB2-33":["A Julia não pode ter visto o e-mail à tarde — estava num avião sem Wi-Fi. Mas deve tê-lo lido depois de pousar, porque respondeu às 21h."],"bkB2-34":["Ele deve ter esquecido da reunião."],"bkB2-35":["Ela deve ter pegado o trem errado."],"bkB2-36":["A: Por que a cozinha está uma bagunça?","B: As crianças devem ter feito panquecas enquanto estávamos fora.","A: Não podem ter feito panquecas. Não tem farinha em casa.","B: Então o amigo delas, o Leo, pode ter trazido.","A: Bom, quem quer que tenha sido, alguém tem que limpar isso!"],"bkB2-37":["Quando o Sr. Alves chegou em casa na sexta à noite, a porta da frente estava aberta. O notebook dele tinha sumido, mas o relógio caro ainda estava na mesa. Não havia danos na fechadura nem nas janelas. A vizinha disse que tinha visto um rapaz abrir a porta com uma chave por volta das 20h. O sobrinho do Sr. Alves é a única outra pessoa que tem uma chave da casa."],"bkB2-38":["Os olhos da Ana estão vermelhos e inchados. / Ela deve ter chorado.","O Rui está com uma queimadura de sol feia. / Ele deve ter passado o dia na praia.","O bolo inteiro sumiu. / Alguém deve tê-lo comido.","O Leo tirou 100% na prova. / Ele deve ter estudado muito."],"bkB2-39":["O Tiago parece exausto. Ele não pode ter dormido bem ontem à noite."],"bkB2-40":["Tivemos que adiar a reunião para a próxima terça porque o diretor estava doente."],"bkB2-42":["No ano passado, a Bia decidiu começar um novo hobby: escalada. No início, ela quase desistiu porque era muito difícil. Depois de alguns meses, alcançou os escaladores mais experientes. Agora admira o treinador como modelo. Na semana passada, encontrou por acaso uma foto antiga de sua primeira escalada e riu."],"bkB2-43":["A: Você descobriu a que horas a loja abre?","B: Ainda não. Vou pesquisar na internet.","A: Obrigado. Acabou meu pacote de dados no celular."],"bkB2-44":["Minha avó criou cinco filhos sozinha. Todo mundo na família a admira."],"bkB2-45":["Não aguento mais todo esse barulho."],"bkB2-46":["turn down / recusar uma oferta","come up with / ter uma ideia","run into / encontrar por acaso","carry out / realizar ou concluir uma tarefa","figure out / entender ou resolver"],"bkB2-48":["A: Ei, ainda estamos de pé para o jantar de hoje à noite?","B: Desculpe, tenho que cancelar. Surgiu um imprevisto no trabalho.","A: Ah, não. Podemos deixar para sexta, então?","B: Sexta dá certo. Vou compensar você, prometo!"],"bkB2-49":["Quando o Diego se mudou para Toronto, achou difícil se enturmar. Ele não conhecia ninguém, e o frio realmente o deixava para baixo. Então se inscreveu numa aula de salsa, onde encontrou por acaso uma velha amiga de Porto Alegre. Ela o apresentou aos amigos dela, e logo ele estava saindo com eles todo fim de semana. Agora diz que não consegue imaginar voltar."],"bkB2-50":["Queria ter mais tempo para ler, mas trabalho dez horas por dia."],"bkB2-51":["Queria não ter comido tanto na festa ontem à noite. Se ao menos eu tivesse ouvido minha mãe!"],"bkB2-52":["Queria que meu vizinho parasse de ouvir música alta à noite. Se ao menos eu morasse num lugar mais tranquilo!"],"bkB2-53":["Queria falar japonês fluentemente."],"bkB2-54":["Queria ter ido ao show."],"bkB2-55":["Se ao menos morássemos perto da praia."],"bkB2-56":["Queria que você parasse de me interromper."],"bkB2-57":["Oi, Marcos, Lembra quando estávamos na escola e eu sempre dizia que queria poder viajar pelo mundo? Pois é, estou escrevendo de um albergue no Peru! A viagem tem sido incrível, mas queria ter trazido roupas mais quentes — as montanhas estão congelantes. Também queria que meu espanhol fosse melhor; só sei algumas frases. Se ao menos você estivesse aqui comigo! Abraços, Lia"],"bkB2-58":["Paulo tem 40 anos e trabalha num banco em Belo Horizonte. Ele costuma dizer: \"Se ao menos eu tivesse estudado música quando era mais jovem.\" Também queria que seu trabalho fosse menos estressante. A esposa dele queria que ele passasse menos tempo no celular. No mês passado, ele finalmente começou a ter aulas de violão aos sábados."],"bkB2-59":["Queria ter / um apartamento mais tranquilo.","Queria estar / de férias agora.","Queria que você / abaixasse a música.","Se ao menos não / tivéssemos perdido o último ônibus."],"bkB2-60":["Você pode não acreditar em mim, mas eu tranquei a porta antes de sair."],"bkB2-61":["A: Não acho que a Marta goste do novo emprego.","B: Ela gosta sim! Só acha o deslocamento cansativo."],"bkB2-62":["Sei que você acha o Pedro preguiçoso, mas ele trabalha muito sim. No mês passado, ele terminou o projeto no prazo, sim."],"bkB2-63":["Ela fala três idiomas mesmo, acredite ou não."],"bkB2-64":["Eu gostei muito do show mesmo."],"bkB2-65":["Sente-se, por favor, e fique à vontade."],"bkB2-66":["Nós avisamos você sobre o trânsito, sim."],"bkB2-67":["A: Você lembrou de comprar leite?","B: Comprei sim, mas deixei no supermercado.","A: Sério? Você anda esquecendo muita coisa ultimamente.","B: Eu sei. Eu preciso mesmo de férias!"],"bkB2-68":["\"Você não pagou a conta.\" / \"Paguei sim! Aqui está o recibo.\"","\"Ela não se importa com a gente.\" / \"Ela se importa sim. Só não demonstra.\"","\"Eles não querem ajudar.\" / \"Querem sim, mas estão ocupados.\"","\"Você não me ama.\" / \"Eu amo você sim!\""],"bkB2-70":["Nunca vi um pôr do sol tão bonito."],"bkB2-71":["A Carla não só venceu a corrida, como também quebrou o recorde nacional. Raramente vemos tanto talento!"],"bkB2-72":["Mal fechei a porta, o telefone tocou."],"bkB2-73":["Raramente vamos ao cinema hoje em dia."],"bkB2-74":["Nunca provei uma comida tão deliciosa."],"bkB2-75":["Em hipótese alguma você deve abrir esta porta."],"bkB2-76":["Eles nem imaginavam a festa surpresa."],"bkB2-77":["AVISO IMPORTANTE – Biblioteca Municipal. Em hipótese alguma é permitido levar comida ou bebida para as salas de leitura. Isso não só protege nossos livros, como também mantém as salas limpas para todos. Somente após mostrar sua carteirinha da biblioteca você poderá pegar livros emprestados. Raramente abrimos exceções a estas regras. Agradecemos a colaboração."],"bkB2-78":["No verão passado, a Renata fez trilha na Chapada Diamantina. Mal chegou, começou a chover forte. Ela não só se molhou, como também perdeu o mapa. Em nenhum momento, porém, pensou em desistir. Só quando chegou ao topo da cachoeira percebeu o quanto estava cansada."],"bkB2-79":["Mal / nos sentamos, o garçom trouxe o cardápio.","Mal / o filme começou, as luzes se apagaram.","Em hipótese alguma / você deve compartilhar sua senha com ninguém.","Só quando cheguei em casa / percebi que a carteira tinha sumido."],"bkB2-80":["Nossa equipe fez progressos significativos no projeto no ano passado."],"bkB2-83":["Abrir um negócio nunca é fácil. Primeiro, é preciso pesquisar o mercado. Depois, é preciso correr um risco e investir suas economias. Se tudo correr bem, você terá lucro em um ou dois anos. Ao longo do caminho, deve prestar atenção nos clientes e cumprir suas promessas."],"bkB2-84":["Era uma manhã terrivelmente fria, mas as crianças estavam bem acordadas às 6h. A neve foi uma surpresa total."],"bkB2-85":["Ela fez um grande esforço para terminar a maratona."],"bkB2-86":["strike / um equilíbrio","raise / consciência","meet / um prazo","draw / uma conclusão","break / o gelo"],"bkB2-88":["A: Como foi a entrevista de emprego?","B: Acho que causei uma boa impressão. Pediram que eu fizesse uma apresentação curta.","A: Você conseguiu manter a calma?","B: Na maior parte do tempo, mas quase perdi o fio da meada em um momento.","A: Bom, você fez o seu melhor. Agora é só esperar."],"bkB2-89":["Prezada equipe, Obrigada por todo o trabalho duro neste ano. Fizemos grandes progressos, e nossas vendas subiram bastante. No entanto, devemos prestar muita atenção ao feedback dos clientes, pois alguns levantaram preocupações sobre os prazos de entrega. No mês que vem, faremos uma reunião para tratar dessas questões e elaborar um novo plano. Por favor, venham preparados para compartilhar suas ideias. Atenciosamente, Helena"],"bkB2-90":["Apesar da chuva forte, o show aconteceu como planejado."],"bkB2-91":["O voo atrasou devido à tempestade. Apesar disso, ainda chegamos ao casamento a tempo."],"bkB2-92":["Embora estivesse exausta, ela continuou trabalhando. Devido a uma greve, todos os ônibus foram cancelados."],"bkB2-93":["Embora estivesse frio, fomos nadar."],"bkB2-94":["Apesar de ter muita experiência, ele não conseguiu o emprego."],"bkB2-95":["Devido às estradas congeladas, muitas escolas foram fechadas."],"bkB2-96":["Enquanto meu irmão adora futebol, eu prefiro vôlei."],"bkB2-97":["A: Você gostou da viagem a Salvador?","B: Gostei, mesmo que tenha chovido a maior parte do tempo.","A: Que pena. Mas você conseguiu ver o centro histórico?","B: Vimos sim. No entanto, tivemos que pular a praia por causa da chuva."],"bkB2-98":["Embora o Brasil tenha uma das maiores florestas tropicais do mundo, o desmatamento ainda é um problema sério. Devido à extração ilegal de madeira e à pecuária, grandes áreas da Amazônia foram destruídas. Mesmo assim, houve algum progresso nos últimos anos, já que o governo aumentou a fiscalização. Enquanto algumas pessoas veem a floresta principalmente como um recurso econômico, outras acreditam que ela deve ser protegida a qualquer custo."],"bkB2-99":["O restaurante era caro; / mesmo assim, comíamos lá toda semana.","Devido a um problema técnico, / o show começou uma hora atrasado.","Mesmo tendo um mapa, / ela se perdeu no centro histórico.","O Tom é extrovertido, / enquanto o irmão gêmeo dele é muito tímido."],"bkB2-100":["Meu chefe me lembrou de conferir os números de novo antes de enviá-los."],"bkB2-101":["\"Você deveria consultar um especialista\", disse o médico ao Marcos. → O médico aconselhou o Marcos a consultar um especialista."],"bkB2-102":["Segunda: A Lara disse: \"Termino o relatório hoje.\" → Sexta: \"A Lara disse que terminaria o relatório naquele dia, mas não terminou.\""],"bkB2-103":["Direta: \"Você deve usar capacete. Você pode ficar nervoso no começo, mas pode parar a qualquer momento.\"","Indireta: O instrutor disse que tínhamos que usar capacete. Acrescentou que poderíamos ficar nervosos no começo, mas que poderíamos parar a qualquer momento."],"bkB2-104":["Direta: \"Estive aqui ontem e voltarei amanhã.\"","Indireta: O Bruno disse que tinha estado lá no dia anterior e que voltaria no dia seguinte."],"bkB2-105":["Na reunião, a Sônia sugeriu fazer uma pequena pausa, e todos concordaram. O Rodrigo admitiu que tinha cometido um erro no orçamento e pediu desculpas. O gerente se ofereceu para dar a ele um prazo extra, mas o Rodrigo recusou e disse que corrigiria ele mesmo. Mais tarde, a Sônia negou ter visto o e-mail, embora ele estivesse claramente aberto na tela dela."],"bkB2-106":["O Rafael nos disse que a loja estava fechada e que reabriria na segunda."],"bkB2-107":["Meu avô sempre nos dizia que a Terra gira em torno do Sol e que a honestidade é a melhor política."],"bkB2-108":["Ela disse que ia se atrasar para o jantar."],"bkB2-109":["A Julia sugeriu ir à praia depois do almoço."],"bkB2-110":["Meu gerente me perguntou se eu tinha terminado o relatório."],"bkB2-111":["O Leo negou ter quebrado a janela."],"bkB2-112":["Ele nos avisou para não nadarmos perto das pedras."],"bkB2-113":["today / naquele dia","yesterday / no dia anterior","next week / na semana seguinte","two days ago / dois dias antes","here / lá"],"bkB2-114":["\"Eu levo as suas malas.\" / Ela se ofereceu para levar minhas malas.","\"Não esqueça de ligar para a mamãe.\" / Ela me lembrou de ligar para a mamãe.","\"Desculpe o atraso.\" / Ela pediu desculpas por ter se atrasado.","\"Cuidado, o chão está molhado.\" / Ela me avisou que o chão estava molhado."],"bkB2-116":["A: O que a professora disse sobre a prova?","B: Ela disse que seria mais difícil do que a última.","A: Ela disse quais capítulos estudar?","B: Disse, falou que deveríamos focar nos capítulos quatro e cinco.","A: Certo, então vou começar pelo capítulo quatro hoje à noite."],"bkB2-117":["Ontem à noite, a Heloísa ligou de Lisboa para o irmão, o Caio. Ela contou que tinha arranjado um emprego num estúdio de design e que começaria na segunda seguinte. O Caio perguntou se ela estava planejando ficar em Portugal de vez. A Heloísa disse que ainda não sabia, mas que sentia muita falta da comida brasileira. Também pediu que ele enviasse café de Minas."],"bkB2-118":["Oi, Duda, Só uma atualização rápida da reunião que você perdeu. O Sr. Nogueira disse que o prazo tinha sido adiado para o dia 15. Ele perguntou se alguém poderia ajudar a equipe de marketing, e o Thiago se ofereceu. O Sr. Nogueira também nos lembrou de não usar mais o logo antigo. Por fim, disse que o escritório estaria fechado na próxima sexta para manutenção. Até amanhã, Bia"],"bkB2-119":["\"Estou esperando o ônibus\", disse a Nina. → A Nina disse que estava esperando o ônibus."],"bkB2-120":["Se a Camila não tivesse tanto medo de voar, ela teria nos visitado em Lisboa no ano passado."],"bkB2-121":["O que você teria feito ontem se não tivesse achado seu passaporte a tempo?"],"bkB2-122":["Se não fosse pela ajuda da minha irmã no ano passado, eu nunca teria terminado minha tese."],"bkB2-123":["Se o árbitro não tivesse anulado o gol, nosso time teria vencido a final no domingo passado."],"bkB2-124":["Se eu tivesse aceitado aquele emprego em São Paulo, estaria morando lá agora."],"bkB2-125":["A: Por que você não me contou da festa?","B: Achei que você estivesse ocupado. Se eu soubesse que você estava livre, teria convidado.","A: Bom, se você tivesse perguntado, saberia que estou sempre livre às sextas!"],"bkB2-126":["Se o Diego não fosse tão impaciente em geral, não teria gritado com o garçom ontem. Se tivéssemos conferido a previsão do tempo, não teríamos ido velejar."],"bkB2-127":["Eu poderia ter conseguido um desconto se tivesse mostrado a carteirinha de estudante no balcão, mas esqueci."],"bkB2-128":["Se eles tivessem verificado os pneus, o acidente não teria acontecido."],"bkB2-129":["Se eu tivesse ido para a cama mais cedo ontem à noite, não estaria tão cansado agora."],"bkB2-130":["Se o Rafa tivesse usado protetor solar, não teria se queimado."],"bkB2-131":["Se a Lia não tivesse medo do oceano, teria ido mergulhar com a gente."],"bkB2-132":["Não teríamos nos perdido se tivéssemos usado o GPS."],"bkB2-133":["Se ela tivesse aceitado o emprego, estaria rica agora."],"bkB2-134":["Se eu tivesse economizado mais dinheiro, / estaria de férias agora.","Se eu fosse melhor em matemática, / não teria sido reprovado na prova na semana passada.","Se o Nando não tivesse perdido a hora, / não teria perdido o ônibus.","Se você tivesse me contado antes, / eu não teria feito outros planos para hoje à noite."],"bkB2-135":["Perdi o trem, então me atrasei. / Se eu não tivesse perdido o trem, não teria me atrasado.","Não falo alemão, então não entendi o guia. / Se eu falasse alemão, teria entendido o guia.","Ela quebrou o braço, então não pode jogar hoje. / Se ela não tivesse quebrado o braço, poderia jogar hoje.","Não reservamos mesa, então tivemos que esperar. / Se tivéssemos reservado mesa, não teríamos precisado esperar."],"bkB2-137":["A: Você parece chateada. O que aconteceu?","B: Reprovei no exame de direção hoje de manhã.","A: Ah, não! O que deu errado?","B: Não parei numa placa de pare. Se eu tivesse sido mais cuidadosa, teria passado.","A: Não se preocupe. Se você praticar um pouco mais, vai passar da próxima vez."],"bkB2-138":["Dois anos atrás, o Otávio recebeu uma oferta de emprego no Canadá, mas recusou porque não queria deixar a família. No mês passado, a ex-colega Pietra, que havia aceitado uma oferta parecida, visitou-o em Recife. Ela contou sobre sua vida em Vancouver: o salário alto, a neve, os invernos longos. \"Se eu tivesse ido, estaria ganhando o dobro agora\", pensou o Otávio. Mas então olhou para os filhos brincando no quintal. \"Se eu tivesse partido, não os teria visto crescer\", disse a si mesmo, sorrindo."],"bkB2-139":["Se eu soubesse da greve de ônibus, teria pegado um táxi."],"bkB2-140":["Quando chegamos ao hotel, nosso quarto ainda estava sendo limpo, então tivemos que esperar no saguão."],"bkB2-141":["Acredita-se que o suspeito tenha deixado o país ontem à noite."],"bkB2-142":["Odeio ser interrompido quando estou falando."],"bkB2-143":["Quando os bombeiros chegaram, a maior parte do prédio já tinha sido destruída. Felizmente, ninguém se feriu."],"bkB2-144":["Todo ano, milhares de toneladas de café são produzidas em Minas Gerais. Neste momento, novos métodos de cultivo estão sendo testados por pesquisadores locais. Até agora, excelentes resultados foram alcançados, e espera-se que toda a região os use até 2030."],"bkB2-145":["Este remédio deve ser mantido na geladeira. Não deve ser dado a crianças menores de 12 anos."],"bkB2-146":["Os vencedores serão anunciados amanhã, e os prêmios já terão sido entregues até o fim do mês."],"bkB2-147":["A Marta ganhou um buquê de flores depois do discurso. As flores tinham sido enviadas pelos alunos dela."],"bkB2-148":["Acredita-se que os ladrões tenham fugido pela janela."],"bkB2-149":["Meu celular foi roubado enquanto eu estava no ônibus."],"bkB2-150":["A casa estava sendo pintada quando a visitamos."],"bkB2-151":["Diz-se que a velha mansão é mal-assombrada."],"bkB2-152":["O Pedro recebeu uma bolsa de estudos."],"bkB2-153":["A reunião deveria ter sido cancelada antes."],"bkB2-154":["Nosso voo está sendo atrasado por causa da neblina."],"bkB2-155":["Eles estão consertando a estrada. / A estrada está sendo consertada.","Eles tinham consertado a estrada. / A estrada tinha sido consertada.","Eles terão consertado a estrada. / A estrada terá sido consertada.","Eles podem consertar a estrada. / A estrada pode ser consertada."],"bkB2-157":["A antiga estação de trem de Campinas, construída em 1884, está sendo transformada num centro cultural. O projeto foi aprovado no ano passado, depois de o prédio ter sido abandonado por décadas. A obra está sendo paga pela prefeitura e por um banco privado. Quando estiver pronto, o centro será usado para shows, exposições e oficinas. Espera-se que abra na próxima primavera."],"bkB2-158":["A: Com licença, meu carro já foi consertado?","B: Ainda não, senhor. Ele está sendo verificado pelo nosso mecânico agora.","A: Quando acha que estará pronto?","B: Deve ficar pronto até as quatro horas.","A: Ótimo. Serei avisado quando estiver pronto?","B: Sim, o senhor receberá uma mensagem de texto."],"bkB2-160":["Ontem toquei a campainha da Rita cinco vezes, mas ela não atendeu. Ela deve ter estado no banho naquela hora."],"bkB2-161":["O Mateus não pode ter lido o e-mail; ele está numa ilha remota sem internet a semana toda."],"bkB2-162":["Não sei por que a Gabi está atrasada. Ela pode ter pegado trânsito, ou talvez tenha perdido a hora."],"bkB2-163":["A: A janela está quebrada e há uma bola de beisebol no chão.","B: As crianças do vizinho devem ter acertado enquanto brincavam.","A: Mas elas não podem ter estado brincando lá fora. Estão na casa da avó desde sexta!"],"bkB2-164":["O alarme do museu não disparou ontem à noite. Deve ter sido desligado por alguém que sabia o código. O guarda não pode ter estado dormindo naquela hora, porque as câmeras mostram ele andando por aí."],"bkB2-165":["A: O Lucas não veio à festa.","B: Ele não pode ter esquecido. Falou disso a semana toda!","A: Talvez. Ou pode ter passado mal. Ele estava resfriado na sexta."],"bkB2-166":["Olhe todas essas caixas vazias! A Luana deve ter comprado muita coisa on-line. Mas não pode ter aberto todas, porque algumas ainda estão lacradas."],"bkB2-167":["Quem pode ter deixado este bilhete na minha mesa? A letra parece familiar, então deve ter sido alguém da nossa equipe."],"bkB2-168":["Ela não pode ter visto a mensagem; o celular dela estava desligado."],"bkB2-169":["O ladrão pode ter entrado pela janela da cozinha."],"bkB2-170":["O Paulo não pode ter pegado meu carregador."],"bkB2-171":["Eles podem ter perdido a última balsa."],"bkB2-172":["Alguém deve ter usado meu notebook enquanto eu estava fora."],"bkB2-173":["O pacote pode ter sido enviado para o endereço errado."],"bkB2-174":["O carro dela não está na garagem. / Ela deve ter ido de carro para o trabalho.","O bebê finalmente adormeceu. / Ele deve ter estado muito cansado.","Tem glitter por todo o sofá. / As crianças devem ter estado fazendo artesanato.","Ele sabe todas as respostas. / Ele deve ter visto a prova antes."],"bkB2-176":["Quando a Clara chegou em casa, a porta da frente estava destrancada e as luzes estavam acesas. A colega de apartamento, a Bia, deveria estar em Salvador no fim de semana. Na mesa da cozinha, a Clara encontrou a mala da Bia e um sanduíche pela metade que ainda estava morno. \"A Bia deve ter voltado mais cedo\", pensou. Então ouviu alguém cantando no chuveiro."],"bkB2-177":["A: Você viu meus fones de ouvido? Estavam na escrivaninha.","B: Não, mas o Theo esteve no seu quarto mais cedo. Ele pode tê-los pegado emprestado.","A: Ele não pode tê-los pegado. Ele está na escola o dia todo.","B: Então você deve tê-los colocado na mochila hoje de manhã.","A: Você tem razão! Aqui estão."],"bkB2-178":["O detetive Moura olhou ao redor da pequena padaria. O caixa estava vazio, mas o ladrão não tinha tocado na máquina de café, que era cara. Havia pegadas de farinha que levavam à porta dos fundos, que estava aberta. O padeiro, Sr. Lopes, disse que a tinha trancado às 18h. A única outra pessoa com chave era o ajudante dele, que estava no hospital desde terça."],"bkB2-179":["O chão está completamente seco, então não pode ter chovido ontem à noite."],"bkB2-180":["A polícia está investigando a causa do incêndio no galpão."],"bkB2-181":["O novo restaurante não correspondeu à expectativa; a comida era apenas mediana."],"bkB2-182":["Nossos planos de comprar a casa fracassaram quando o banco recusou o empréstimo."],"bkB2-184":["Quando o pai da Joana se aposentou, ela assumiu a padaria da família em Belém. Logo percebeu que o forno velho era o principal problema, então decidiu se livrar dele e comprar um novo. Numa reunião de família, ela apresentou a ideia de vender bolos on-line. Alguns parentes ficaram céticos, mas o plano acabou sendo um enorme sucesso."],"bkB2-185":["A: Estou ficando gripado, então vou ficar em casa hoje.","B: Coitado! Você arranjou tempo para ligar para o médico?","A: Ainda não, mas resolvo isso mais tarde."],"bkB2-186":["A fábrica teve que demitir 200 funcionários no ano passado. Felizmente, a maioria foi contratada por um concorrente alguns meses depois."],"bkB2-187":["Tentei convencê-lo a ir ao show, mas ele desistiu no último minuto."],"bkB2-188":["Ninguém conseguia entender o que o locutor estava dizendo. O barulho da multidão o abafava."],"bkB2-189":["Por favor, não conte a ninguém — não quero que ele se safe dessa."],"bkB2-190":["Ela puxou à avó; elas têm o mesmo sorriso."],"bkB2-191":["O ladrão finalmente confessou ter roubado o quadro."],"bkB2-192":["Você poderia abaixar isso?"],"bkB2-193":["Não consigo acompanhar todos esses aplicativos novos."],"bkB2-194":["Ela destacou que os números não batiam."],"bkB2-195":["rule out / excluir uma possibilidade","stand out / ser facilmente notado","wear out / usar algo até não poder mais ser usado","bring about / fazer algo acontecer","pull through / se recuperar de uma doença grave"],"bkB2-197":["A: Você soube que o Caio e a Fernanda brigaram?","B: Sério? O que aconteceu?","A: Ele esqueceu o aniversário dela, e ela não deixou barato.","B: Espero que resolvam logo.","A: Eu também. Eles são amigos desde a escola."],"bkB2-198":["Oi, Lucas, Más notícias: nossa viagem a Ilhabela fracassou. O hotel ligou dizendo que fez overbooking, então não pode mais nos hospedar. Pesquisei outras opções, mas está tudo lotado ou caro demais. Mas não quero descartar a viagem completamente. Talvez possamos remarcar para o mês que vem? Me diga o que acha. Duda"],"bkB2-199":["Marcelo sempre se destacou no trabalho, então, quando o chefe saiu do cargo, pediram que ele assumisse a equipe. No começo, ele achou difícil transmitir suas ideias nas reuniões. Também teve que recusar vários convites para sair com os antigos colegas porque estava muito ocupado. Depois de seis meses, porém, os resultados da equipe tinham melhorado, e todos concordaram que ele havia correspondido às expectativas."],"bkB2-200":["Queria que meu irmão parasse de pegar minhas roupas emprestadas sem pedir."],"bkB2-201":["Espero que você se divirta muito em Buenos Aires na semana que vem!"],"bkB2-202":["Agora que moro em Tóquio, queria ter estudado japonês na escola."],"bkB2-203":["Queria poder ir ao seu casamento, mas estarei na Europa nessa época. Se ao menos as datas fossem diferentes!"],"bkB2-204":["A: Você se arrepende de ter se mudado para o interior?","B: Nem tanto, mas queria que houvesse um bom hospital por perto. E queria não ter vendido meu carro antes de nos mudarmos — preciso muito dele agora!"],"bkB2-205":["Se ao menos parasse de chover! Queria que tivéssemos ido à praia ontem, quando estava sol."],"bkB2-206":["Queria ser mais alta. Assim eu alcançaria a prateleira de cima sem escada."],"bkB2-207":["A Paula queria não ter dito aquelas coisas à irmã ontem à noite. Queria que elas ainda fossem amigas."],"bkB2-208":["Queria ter mais tempo livre."],"bkB2-209":["Se ao menos eu tivesse ouvido seu conselho no ano passado."],"bkB2-210":["Queria que meu colega de quarto lavasse a louça."],"bkB2-211":["Se ao menos eu tivesse tirado mais fotos na viagem."],"bkB2-212":["Queria saber tocar piano."],"bkB2-213":["Queria não ter gastado tanto dinheiro no fim de semana passado."],"bkB2-214":["Se ao menos tivéssemos mais tempo juntos."],"bkB2-215":["Estou preso no trânsito. / Queria não estar preso aqui.","Não trouxe jaqueta. / Queria ter trazido uma.","Meu cachorro late a noite toda. / Queria que ele parasse.","Não sei nadar. / Queria saber."],"bkB2-217":["A: Como foi o acampamento?","B: Terrível. Choveu o fim de semana todo.","A: Ah, não. Você não conferiu a previsão do tempo?","B: Não. Queria ter conferido antes de sairmos.","A: Se ao menos você tivesse me perguntado! Eu poderia ter emprestado minha barraca impermeável."],"bkB2-218":["Renan é desenvolvedor de software em Florianópolis. Ele adora o emprego, mas queria não ter que trabalhar até tão tarde toda noite. Também queria ter aprendido a surfar quando se mudou para lá, já que a praia fica logo em frente à janela dele. A namorada dele costuma dizer: \"Queria que você tirasse um dia de folga!\" No mês que vem, ele finalmente vai tirar duas semanas de férias."],"bkB2-219":["Minha irmã queria ter um quarto maior."],"bkB2-220":["Não como muita carne, mas adoro mesmo um bom churrasco de vez em quando."],"bkB2-221":["Minha falecida avó fazia mesmo o melhor pão de queijo do mundo — todo mundo dizia isso."],"bkB2-222":["Venha mesmo nos visitar quando estiver em Porto Alegre!"],"bkB2-223":["A: Você nunca ajuda em casa!","B: Isso não é justo! Eu fiz o jantar ontem à noite, sim, e levo o lixo para fora todo dia."],"bkB2-224":["O Rafael não gosta de lugares cheios, mas gosta mesmo de shows pequenos com amigos."],"bkB2-225":["Ele não passou na prova, mas se esforçou ao máximo, sim. Parece mesmo um pouco decepcionado, porém."],"bkB2-226":["Embora o hotel fosse antigo, tinha mesmo uma vista linda. A equipe nos fez nos sentir bem-vindos, sim."],"bkB2-227":["Eu avisei, sim, para você trazer um casaco!"],"bkB2-228":["Sente-se, por favor — o médico já vai atendê-lo."],"bkB2-229":["Ela parece mesmo cansada hoje."],"bkB2-230":["Nós nos divertimos muito mesmo na sua festa."],"bkB2-231":["Aceite mais um pedaço de bolo, por favor."],"bkB2-232":["Espero mesmo que você melhore logo."],"bkB2-233":["Ela pediu desculpas, sim, mas ele não ouviu."],"bkB2-234":["Não tenho carro, / mas tenho uma moto, sim.","Ela raramente come doces, / mas adora chocolate mesmo.","Não ganhamos o jogo, / mas marcamos dois gols, sim.","Eles não falam espanhol, / mas entendem um pouco, sim."],"bkB2-236":["A: Você tem certeza de que me enviou o arquivo? Não consigo achar.","B: Enviei sim! Enviei na segunda.","A: Qual endereço de e-mail você usou?","B: O do seu trabalho. Confira a caixa de spam.","A: Ah, aqui está. Desculpe, você enviou mesmo."],"bkB2-237":["Muita gente acha que os brasileiros só falam português. Na verdade, muitos brasileiros estudam outros idiomas, especialmente inglês e espanhol. Mariana, uma enfermeira de Belém, não fala espanhol fluentemente, mas entende a maior parte. Ela diz: \"Eu tentei fazer aulas, sim, mas nunca tive tempo.\" Agora ela pratica assistindo a séries argentinas."],"bkB2-238":["Pousada Sol, Paraty – Avaliação. A pousada não é luxuosa, e os quartos são bem pequenos. No entanto, tem um jardim lindo e um ótimo café da manhã. A equipe não fala muito inglês, mas se esforça bastante para ajudar. Tivemos um problema: o Wi-Fi parou de funcionar no último dia. No geral, recomendamos para um fim de semana relaxante."],"bkB2-239":["A: Por que você não me mandou mensagem? B: Mandei sim! Confira seu celular."],"bkB2-240":["Mal saímos de casa, começou a chover forte."],"bkB2-241":["Só depois da reunião percebi o quão sério era o problema."],"bkB2-242":["Em nenhum momento os passageiros correram perigo, garantiu-nos o piloto."],"bkB2-243":["Só quando as luzes se acenderam vimos quanta gente havia ali. Nem imaginávamos que o cantor também estava na plateia."],"bkB2-244":["Raramente a Luísa cozinha em casa, mas ontem à noite fez feijoada. Em nenhum outro lugar você encontrará frutos do mar tão frescos quanto neste mercado."],"bkB2-245":["Mal o avião decolou, o bebê começou a chorar. Em hipótese alguma os passageiros devem sair dos assentos durante a decolagem."],"bkB2-246":["A Rita não só dá aulas de ioga, como também administra um pequeno café."],"bkB2-247":["Em hipótese alguma você deve deixar sua bolsa sem vigilância. De modo algum o motorista foi responsável pelo acidente."],"bkB2-248":["Raramente vi uma praia tão cheia."],"bkB2-249":["Só quando ela ligou fiquei sabendo que estava doente."],"bkB2-250":["Mal começamos a comer, a luz acabou."],"bkB2-251":["Só quando ela explicou entendi a piada."],"bkB2-252":["O museu não só é lindo, como também é gratuito."],"bkB2-253":["Nunca antes a cidade tinha visto tanta neve."],"bkB2-254":["Só quando o bebê adormeceu conseguimos relaxar."],"bkB2-255":["Ele não só esqueceu meu aniversário, / como também esqueceu nosso aniversário de casamento.","Ela nem imaginava / que sua vida estava prestes a mudar.","Só trabalhando juntos / podemos resolver este problema.","Raramente me senti / tão bem-vinda numa cidade nova."],"bkB2-257":["A: Como foi o primeiro dia no novo emprego?","B: Exaustivo! Mal me sentei, meu chefe me chamou para uma reunião.","A: Sobre o que era a reunião?","B: Um cliente grande. Eu não só tive que fazer anotações, como também apresentar um relatório.","A: Nossa. Raramente alguém recebe tanta responsabilidade no primeiro dia!"],"bkB2-258":["No sábado passado, um pescador de Ubatuba, Seu Jorge Matos, resgatou dois turistas cujo barco havia virado. Nunca antes tinha visto ondas tão grandes, disse ele. Ele não só tirou os dois turistas da água, como também levou o cachorro deles de volta à margem. Só quando chegaram à praia ele notou que a própria mão estava sangrando. \"Em nenhum momento pensei na minha própria segurança\", disse aos repórteres."],"bkB2-259":["Raramente meu pai fica bravo, mas ontem ele estava furioso."],"bkB2-260":["As instruções estavam claríssimas, então ninguém se perdeu."],"bkB2-261":["Por favor, tenha em mente que o museu fecha cedo aos domingos."],"bkB2-262":["Depois de horas de negociação, as duas empresas finalmente chegaram a um acordo."],"bkB2-265":["As pequenas empresas no Brasil enfrentam muitos desafios. Muitos donos trabalham longas horas só para fechar as contas no fim do mês. Para sobreviver, precisam aproveitar as redes sociais e construir uma forte presença on-line. Aqueles que têm sucesso muitas vezes fazem um nome na sua cidade."],"bkB2-266":["Quando as crianças viram o palhaço, caíram na gargalhada. A irmãzinha delas, porém, ficou assustada e começou a chorar."],"bkB2-267":["Você poderia me dar uma mão com as compras? Faço um favor a você da próxima vez."],"bkB2-268":["O bebê dormia profundamente, mesmo estando um breu e com trovões estrondando lá fora."],"bkB2-269":["Este restaurante é altamente recomendado. Aconselho fortemente que você reserve uma mesa com antecedência."],"bkB2-270":["A polícia acredita que o crime foi cometido por dois homens."],"bkB2-271":["O festival acontecerá em Olinda em fevereiro do ano que vem."],"bkB2-272":["O estádio é novinho em folha; foi inaugurado na semana passada."],"bkB2-273":["Ela caiu no choro quando ouviu a notícia."],"bkB2-274":["Precisamos levar em conta a opinião de todos."],"bkB2-275":["commit / um crime","set / um recorde","pose / uma ameaça","lend / uma mão","place / um pedido"],"bkB2-276":["bitterly / decepcionado","highly / improvável","sound / adormecido","painfully / tímido"],"bkB2-278":["A: A reunião com os investidores foi boa?","B: Foi, finalmente chegamos a um acordo depois de três horas.","A: Que ótima notícia! Eles fizeram perguntas difíceis?","B: Algumas, mas tínhamos feito o dever de casa, então estávamos prontos.","A: Muito bem. É um peso enorme que sai das suas costas."],"bkB2-279":["No ano passado, uma pequena cidade em Goiás lançou uma campanha para reduzir o lixo plástico. O prefeito disse que a cidade enfrentava um problema sério, pois o rio estava muito poluído. As escolas locais tiveram um papel fundamental, ensinando as crianças a reciclar. A campanha superou todas as expectativas: em apenas seis meses, o lixo plástico caiu 40%. Outras cidades agora seguem o exemplo."],"bkB2-280":["Graças à nova linha de metrô, agora levo só 20 minutos para chegar ao trabalho."],"bkB2-281":["O hotel estava lotado. Mesmo assim, conseguimos encontrar um quarto por perto."],"bkB2-282":["Já que você vai ao mercado de qualquer jeito, poderia comprar uns limões?"],"bkB2-283":["Apesar de ser feriado, a loja estava aberta. No entanto, pouquíssimos clientes entraram."],"bkB2-284":["O Brasil é famoso por suas praias. No entanto, muitos turistas preferem o interior. Enquanto alguns visitantes adoram o calor do Nordeste, outros escolhem o clima ameno do Sul. Muitas pessoas viajam de ônibus já que as passagens aéreas são caras. Por causa das longas distâncias, uma viagem pelo país exige planejamento cuidadoso."],"bkB2-285":["Por mais que eu ame meu trabalho, preciso de uma pausa. Mesmo que você peça desculpas, ela não vai mudar de ideia."],"bkB2-286":["O projeto fracassou por causa do mau planejamento dos gerentes. A equipe, por outro lado, trabalhou extremamente duro."],"bkB2-287":["Apesar do trânsito, chegamos na hora."],"bkB2-288":["O show foi cancelado porque o cantor estava doente."],"bkB2-289":["Apesar de ser muito rica, ela mora num apartamento pequeno."],"bkB2-290":["Por causa da chuva forte, a partida foi adiada."],"bkB2-291":["Por mais tarde que fosse, continuamos conversando."],"bkB2-292":["Dado que é feriado, as estradas devem estar tranquilas."],"bkB2-293":["Ele foi reprovado na prova mesmo tendo estudado muito."],"bkB2-294":["Eu empresto o dinheiro, / mas você precisa me pagar de volta até sexta.","Já que é seu aniversário, / o jantar é por minha conta.","Em consequência da tempestade, / milhares de casas ficaram sem energia.","Por mais que eu admire o trabalho dela, / não concordo com as opiniões dela."],"bkB2-296":["A: Por que você não estava na conferência ontem?","B: Não pude ir por causa de uma emergência familiar.","A: Sinto muito. Está tudo bem agora?","B: Está, obrigado. Mesmo assim, fico triste por ter perdido a palestra principal.","A: Não se preocupe. Como foi gravada, você pode assistir on-line."],"bkB2-297":["Prezado Sr. Castro, Escrevo para reclamar da minha recente estadia no seu hotel. Embora o quarto estivesse limpo, o ar-condicionado não funcionou por causa de uma falha técnica. Como resultado, mal consegui dormir. A equipe foi educada; no entanto, ninguém veio consertar. Dado que paguei por um quarto premium, acredito merecer um reembolso parcial. Atenciosamente, Tânia Rocha"],"bkB2-298":["Por mais que o Leandro goste de morar em São Paulo, às vezes sente falta da cidade natal dele, na Bahia. Graças ao novo emprego, ele ganha um bom salário. Mesmo assim, o custo de vida é tão alto que ele economiza muito pouco. Como trabalha de casa duas vezes por semana, tem mais tempo para os hobbies. Mesmo assim, planeja voltar para a Bahia em alguns anos."],"bkB2-299":["O voo atrasou por causa de um problema no motor."],"bkB2-1001":["Daqui a uma semana, a esta hora, estarei deitado numa praia na Bahia."],"bkB2-1002":["Nossa equipe terá terminado o projeto quando o cliente visitar, no sábado."],"bkB2-1003":["A: Você estará em casa amanhã às oito?","B: Não, às oito estarei trabalhando na clínica. Mas terei terminado às dez, então me ligue depois.","A: Certo. Estarei na cozinha a partir das seis, então às dez terei cozinhado três pratos!"],"bkB2-1004":["Não me ligue amanhã às nove. Vou estar dormindo. Ligue ao meio-dia; até lá, terei acordado e tomado café da manhã."],"bkB2-1005":["Em junho do ano que vem, eles estarão morando no Canadá há cinco anos. Os pedreiros terão terminado até segunda."],"bkB2-1006":["Quando você chegar aqui, já teremos comido."],"bkB2-1007":["Amanhã a esta hora, estarei voando para Lisboa."],"bkB2-1008":["Amanhã às dez, estarei dando aula."],"bkB2-1009":["Até sexta, terei terminado o relatório."],"bkB2-1010":["Até o ano que vem, ela terá economizado dinheiro suficiente."],"bkB2-1011":["O Sr. Silva é motorista de ônibus. Na próxima segunda, às oito, estará fazendo seu trajeto habitual pela cidade. Ao meio-dia, terá levado cerca de duzentos passageiros ao trabalho. Em março, estará dirigindo ônibus há vinte anos, e planeja se aposentar no ano seguinte."],"bkB2-1012":["À meia-noite de hoje, estaremos / assistindo aos fogos.","Até a meia-noite de hoje, teremos / assistido aos três episódios.","No mês que vem, ela estará / morando aqui há um ano.","Você estará / usando a impressora esta tarde?"],"bkB2-1014":["Em dezembro, estarei estudando inglês há cinco anos."],"bkB2-1015":["Tendo terminado o relatório, ele o enviou ao gerente."],"bkB2-1016":["Os alunos que estudam na biblioteca estão se preparando para as provas."],"bkB2-1017":["1. O vaso encontrado no sótão é muito antigo.","2. Tendo morado na Espanha por anos, a Ana fala espanhol fluentemente.","3. Enquanto esperava o ônibus, li as notícias."],"bkB2-1018":["Escrito em inglês simples, o livro é fácil para iniciantes. Ao abrir a caixa, ela encontrou uma carta."],"bkB2-1019":["O queijo produzido nesta região é exportado. As crianças que brincam no jardim são os filhos dos meus vizinhos."],"bkB2-1020":["Tendo terminado o relatório, ele foi para casa."],"bkB2-1021":["Os livros escritos por Tolkien são famosos."],"bkB2-1022":["Sentindo-se nervosa, ela conferiu suas anotações de novo."],"bkB2-1023":["Depois de tomar café da manhã, ele saiu para o trabalho."],"bkB2-1024":["Sem saber o caminho, ele perguntou a um policial."],"bkB2-1025":["Nascido numa pequena vila, o Marco se mudou para Milão aos dezoito anos. Tendo estudado design, abriu a própria loja. As roupas vendidas na loja dele são feitas na Itália. Impressionado com a qualidade, um cantor famoso comprou três jaquetas."],"bkB2-1026":["O homem que está esperando lá fora / O homem esperando lá fora","O bolo que foi feito pela minha tia / O bolo feito pela minha tia","Depois de ter falado com o gerente, / Tendo falado com o gerente,","Porque sentia fome, / Sentindo fome,"],"bkB2-1028":["Tendo perdido as chaves, o Tom não conseguiu abrir a porta."],"bkB2-1029":["O documentário era tão interessante que eu assisti duas vezes."],"bkB2-1030":["Nosso time ganhou quatro jogos seguidos."],"bkB2-1031":["A criação do aplicativo levou dois anos.","Nossa amizade com a equipe de design facilitou as coisas.","O diretor falou com honestidade sobre o atraso."],"bkB2-1032":["A crise econômica atingiu duramente as pequenas lojas, então compramos um carro econômico."],"bkB2-1033":["É ilegal estacionar aqui, e a nova regra parece injusta."],"bkB2-1034":["Ela ficou muito constrangida quando esqueceu o nome dele."],"bkB2-1035":["Deixar o fogão ligado foi completamente irresponsável."],"bkB2-1036":["Ela é uma pessoa muito desonesta."],"bkB2-1037":["Ele dirigiu com cuidado."],"bkB2-1038":["A amizade deles ficou mais forte ao longo dos anos."],"bkB2-1039":["A: Você conseguiu o emprego?","B: Ainda não. Vão decidir na sexta.","A: Você está nervoso?","B: Um pouco, mas me senti confiante durante a entrevista."],"bkB2-1040":["O prefeito anunciou um novo plano na semana passada. O desemprego caiu dois por cento, e a cidade agora está mais segura por causa da melhor iluminação. Muitos moradores ficaram satisfeitos, mas alguns acham o plano irrealista. A maioria dos novos empregos é temporária."],"bkB2-1041":["Prezada Sra. Alves, Escrevo a respeito da vaga de voluntário no seu centro de leitura. Tenho dois anos de experiência ensinando crianças e sou uma pessoa paciente e criativa. Infelizmente, não estou disponível nas manhãs de dias úteis por causa dos estudos, mas tenho total flexibilidade nos fins de semana. Eu ficaria grato pela oportunidade de me juntar à sua equipe. Atenciosamente, Pedro Lima"],"bkB2-1043":["não legal / ilegal","não regular / irregular","não feliz / infeliz","não concordar / discordar"],"bkB2-1044":["Os cientistas querem saber a verdade sobre o vírus."],"bkB2-1045":["Obrigado pela sua gentileza com minha família."]};